window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s35-56","number":56,"surah":35,"verses":[37],"references":[{"surah":35,"verses":[37]}],"verseLabel":"فاطر: 37","question":"لماذا عبّر عن إمهالهم بقوله: ﴿نُعَمِّرْكُمْ﴾؟","answer":"لأن التعمير منح مدة ممتدة تتكرر فيها فرص التذكر؛ فكلما طال العمر قويت الحجة على من بقي معرضًا حتى جاءه النذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص229، تحت عنوان «دلالة التعبير بـجملة ﴿نعمركم﴾»","url":""}]},{"id":"s35-34","number":34,"surah":35,"verses":[39],"references":[{"surah":35,"verses":[39]}],"verseLabel":"فاطر: 39","question":"لماذا قيل للناس: ﴿جَعَلَكُمْ خَلَائِفَ فِي الْأَرْضِ﴾؟","answer":"لأن الأجيال يخلف بعضها بعضًا في عمارة الأرض والتصرف فيها؛ فاللفظ يجمع نعمة التمكين ومسؤولية الاختبار، وينبه كل جيل إلى أنه راحل وسيأتي بعده غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص251، تحت عنوان «غرض استعمال مفردة ﴿خلائف﴾»","url":""}]},{"id":"s35-35","number":35,"surah":35,"verses":[40],"references":[{"surah":35,"verses":[40]}],"verseLabel":"فاطر: 40","question":"لماذا تتابعت الأسئلة في إبطال الشرك من خلق الأرض إلى الشركة في السماء ثم الدليل من كتاب؟","answer":"لإحاطة كل دعاوى الشرك بالإبطال: سأل أولًا عن أثر محسوس خلقته الآلهة في الأرض، ثم عن نصيب لها في السماوات، ثم عن كتاب من الله يجيز عبادتها؛ فلما عجزوا عن الخلق والملك والحجة انكشف بطلانها كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص282، تحت عنوان «دلالات الاستفهام المتوالي»","url":""}]},{"id":"s35-36","number":36,"surah":35,"verses":[41],"references":[{"surah":35,"verses":[41]}],"verseLabel":"فاطر: 41","question":"ما الصورة في قوله: ﴿إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَنْ تَزُولَا﴾؟","answer":"صُورت السماوات والأرض كجسمين عظيمين يوشكان أن ينفصلا أو يسقطا، والله يمسكهما بقدرته؛ فتقرب الصورة حفظ النظام الكوني المستمر من غير دعامة يراها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص293، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s35-57","number":57,"surah":35,"verses":[41],"references":[{"surah":35,"verses":[41]}],"verseLabel":"فاطر: 41","question":"لماذا جاء إمساك السماوات والأرض بصيغة المضارع ﴿يُمْسِكُ﴾؟","answer":"ليصور الحفظ فعلًا متجددًا مستمرًا في كل لحظة؛ فبقاء الكون منوط دائمًا بقدرة الله، لا بفعل وقع ثم انقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص293–294، تحت عنوان «نكتة التعبير بالمضارع»","url":""}]},{"id":"s35-37","number":37,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ما الصورة التي ترسمها كلمة ﴿يَحِيقُ﴾ في قوله: ﴿وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ﴾؟","answer":"ترسم المكر كشيء يحيط بصاحبه وينزل به من كل جانب؛ فمن دبر السوء لغيره ارتد تدبيره عليه حتى صار هو المحاصر بنتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص326، تحت عنوان «بلاغة استعمال مفردة ﴿يحيق﴾ مادة وصيغة»","url":""}]},{"id":"s35-58","number":58,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يفيد القصر في قوله: ﴿وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ﴾؟","answer":"يفيد أن العاقبة الملازمة للمكر السيئ راجعة إلى أصحابه؛ فقد يصيب أذاهم غيرهم مؤقتًا، لكن وباله المستقر لا يفلت منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص328، تحت عنوان «بلاغة القصر ودلالته»","url":""}]},{"id":"s35-38","number":38,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يفيد نفي ﴿التَّبْدِيلِ﴾ عن سنة الله؟","answer":"يفيد أن سنة الله لا تستبدل بسنة أخرى تخالفها؛ فلا تتحول عاقبة المكذبين إلى نجاة مع بقاء أسبابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص335، تحت عنوان «نكتة استعمال (التبديل) وتنكيرها»","url":""}]},{"id":"s35-59","number":59,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يضيف نفي ﴿التَّحْوِيلِ﴾ بعد نفي التبديل؟","answer":"ينفي أن تُصرف السنة نفسها عن مستحقها أو تُحوّل إلى غير موضعها؛ فليس هناك قانون بديل، ولا مهرب بتحويل مجراه عن المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص336، تحت عنوان «نكتة استعمال (التحويل) وتنكيرها»","url":""}]},{"id":"s35-39","number":39,"surah":35,"verses":[44],"references":[{"surah":35,"verses":[44]}],"verseLabel":"فاطر: 44","question":"ما أثر الجمع بين قوله عن السابقين: ﴿كَانُوا أَشَدَّ مِنْهُمْ قُوَّةً﴾ وختم الآية: ﴿وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِنْ شَيْءٍ﴾؟","answer":"يبدأ المشهد بقوة الأمم التي توهم المنعة، ثم ينتهي بنفي أن يعجز الله شيء؛ فتلتقي بدايته ونهايته لتبين أن أشد قوة بشرية لا تخرج عن قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص354–355، تحت عنوان «بلاغة تشابه الأطراف»","url":""}]},{"id":"s35-40","number":40,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل: ﴿وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا﴾ ولم يقل: المشركين؟","answer":"لأن التقصير والكسب السيئ لا يختصان بالمشركين؛ فلفظ الناس يعمهم ويذكر الجميع بأن بقاءهم قائم على حلم الله، لا على استحقاق السلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص362، تحت عنوان «نكتة استعمال لفظ ﴿الناس﴾ دون (المشركين)»","url":""}]},{"id":"s35-60","number":60,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ماذا يفيد قوله: ﴿مِنْ دَابَّةٍ﴾ في ﴿مَا تَرَكَ عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾؟","answer":"يفيد العموم المؤكد: لو جرت المؤاخذة العاجلة لاستأصل أثرها كل دابة على الأرض، لا الإنسان وحده؛ فيظهر اتساع أثر الذنوب وعظم الحلم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص365، تحت عنوان «دلالة العموم في قيد ﴿من دابة﴾»","url":""}]},{"id":"s35-41","number":41,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا حُذف جواب الشرط في ختام السورة: ﴿فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا﴾؟","answer":"لأن الجملة الأخيرة تدل عليه: إذا جاء الأجل جازاهم الله بما عملوا؛ فحذف الجزاء يجعله مهيبًا مفتوحًا على ما يقتضيه علم الله التام من ثواب وعقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص370، تحت عنوان «بلاغة حذف جواب الشرط»","url":""}]},{"id":"s35-61","number":61,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل: ﴿كَانَ بِعِبَادِهِ بَصِيرًا﴾ بصيغة الماضي؟","answer":"للدلالة على أن إحاطته بأعمال عباده صفة قديمة ثابتة لم تبدأ عند مجيء أجلهم؛ فهو كان ولا يزال بصيرًا بهم، ولذلك لا يضيع عند الجزاء شيء من أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص371، تحت عنوان «سر ذكر فعل الكون الماضي»","url":""}]},{"id":"s35-42","number":42,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل في فاطر: ﴿عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾، وفي النحل: ﴿عَلَيْهَا مِنْ دَابَّةٍ﴾؟","answer":"في فاطر سبق مشهد ظاهر الأرض من ألوان الجبال، فناسب ذكر ﴿ظهرها﴾ وخصّ الظاهر مع سياق المعاصي؛ أما النحل فالسياق في الظلم والشرك الأعم، فجيء بالضمير ﴿عليها﴾ ليشمل الأرض كلها من غير تخصيص ظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص364–365، تحت عنوان «توجيه المتشابه اللفظي في (الإظهار والإضمار)»","url":""}]},{"id":"s36-1","number":1,"surah":36,"verses":[1],"references":[{"surah":36,"verses":[1]}],"verseLabel":"يس: 1","question":"ما دلالة افتتاح السورة بـ﴿يس﴾ على توجيهها من الحروف المقطعة؟","answer":"توجه الموسوعة ﴿يس﴾ على أنها من الحروف المقطعة التي افتتحت بها بعض السور للإشارة إلى إعجاز القرآن، ثم يتبعها القسم بالقرآن الحكيم على صدق الرسالة. وبهذا يرتبط الافتتاح بالكتاب الذي تقوم به حجة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص387، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s36-2","number":2,"surah":36,"verses":[2],"references":[{"surah":36,"verses":[2]}],"verseLabel":"يس: 2","question":"لماذا أقسم الله بـ﴿الْقُرْآنِ الْحَكِيمِ﴾ على صدق الرسالة؟","answer":"لأن القرآن نفسه أعظم معجزة للرسول ﷺ ودليل رسالته؛ فجاء القسم به في صورة استشهاد بالدليل، مع تعظيم المقسَم به والمقسَم عليه ودعوة المنكر إلى تدبر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص389، تحت عنوان «سر تخصيص القسم بالقرآن المقيد بصفة الحكيم»","url":""}]},{"id":"s36-3","number":3,"surah":36,"verses":[3,4],"references":[{"surah":36,"verses":[3,4]}],"verseLabel":"يس: 3-4","question":"لماذا توالت المؤكدات في قوله: ﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾؟","answer":"جاء القسم ثم ﴿إن﴾ واللام والجملة الاسمية لتثبيت الرسالة في وجه إنكار شديد؛ فكل مؤكد يبدد شبهة ويقرر الخبر حتى يستقر في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص392، تحت عنوان «بلاغة تتابع التأكيد في السياق المجيد»","url":""}]},{"id":"s36-4","number":4,"surah":36,"verses":[5],"references":[{"surah":36,"verses":[5]}],"verseLabel":"يس: 5","question":"ما سرّ الجمع بين وصفي ﴿الْعَزِيزِ الرَّحِيمِ﴾ في إنزال القرآن؟","answer":"إضافة التنزيل إلى العزيز الرحيم تجمع الترهيب والترغيب: فهو صادر عن غالب قادر على عقاب المعرضين، ورحيم بعباده أنزل إليهم ما يهديهم. فالعزة تؤكد سلطان الوحي، والرحمة تظهر النعمة في إنزاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص403–404، تحت عنوان «براعة إضافة التنزيل إلى العزة والرحمة»","url":""}]},{"id":"s36-5","number":5,"surah":36,"verses":[6],"references":[{"surah":36,"verses":[6]}],"verseLabel":"يس: 6","question":"كيف تُفهم ﴿مَا﴾ في قوله: ﴿مَا أُنْذِرَ آبَاؤُهُمْ﴾؟","answer":"أشهر وجوهها النفي: أي لم يأت آباءهم الأقربين نذير فطالت الغفلة واشتدت الحاجة إلى الإنذار. وتحتمل الوصل أو المصدرية، أي لتنذرهم الذي أُنذر به آباؤهم أو إنذارًا مثل إنذارهم، فتصل الرسالة بخط الرسل السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص409–410، تحت عنوان «دلالة ﴿ما﴾ في قوله: ﴿ما أنذر آباؤهم﴾»","url":""}]},{"id":"s36-6","number":6,"surah":36,"verses":[8],"references":[{"surah":36,"verses":[8]}],"verseLabel":"يس: 8","question":"ما الذي تصوره الأغلال البالغة إلى الأذقان في قوله: ﴿فَهُمْ مُقْمَحُونَ﴾؟","answer":"تصوّر عنادهم قيدًا يغل أعناقهم ويرفع رؤوسهم ويمنعهم من الإطراق والنظر؛ فكأن استكبارهم وإصرارهم على الكفر هيئة حسية من العجز والانحباس عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص431–432، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s36-7","number":7,"surah":36,"verses":[9],"references":[{"surah":36,"verses":[9]}],"verseLabel":"يس: 9","question":"ما الصورة في جعل سدٍّ من أمام الكافرين وسدٍّ من خلفهم ثم إغشائهم؟","answer":"هي صورة تمثيلية لانغلاق جهات الاعتبار عليهم: لا ينظرون فيما أمامهم من الآيات والعواقب، ولا فيما خلفهم من أخبار الأمم، وقد غطى العناد بصائرهم؛ فبدوا محاصرين لا يبصرون سبيل الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص446، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s36-8","number":8,"surah":36,"verses":[11],"references":[{"surah":36,"verses":[11]}],"verseLabel":"يس: 11","question":"لماذا قُصر الإنذار النافع على من اتبع الذكر في قوله: ﴿إِنَّمَا تُنْذِرُ﴾؟","answer":"ليس المراد أن الإنذار لا يوجَّه إلى غيرهم، بل أن الانتفاع التام به لا يكون إلا لمن اتبع القرآن وخشي الله؛ فالقصر يميز المستجيب من المعاند بعد عموم البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص464–465، تحت عنوان «دلالة القصر بـ ﴿إنما﴾»","url":""}]},{"id":"s36-9","number":9,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"لماذا عطف الله ﴿وَآثَارَهُمْ﴾ على ما قدَّم الناس من أعمال؟","answer":"ليدخل في الكتابة ما يبقى بعد صاحبه من نتائج عمله، خيرًا أو شرًّا؛ فليس المحفوظ فعله المباشر وحده، بل ما سنَّه وخلّفه وامتد أثره في الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص486–487، تحت عنوان «سبب إيثار التعبير بـ﴿وآثارهم﴾»","url":""}]},{"id":"s36-10","number":10,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"لماذا سُمّي الكتاب الذي أحصى الله فيه كل شيء ﴿إِمَامًا﴾؟","answer":"لأنه أصل جامع يُرجع إليه ويتبع ما أثبته، فكأنه إمام تتبعه أحوال الخلق عند الحساب؛ واللفظ يوحي بالمرجعية والإحاطة لا بمجرد كونه سجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص489–490، تحت عنوان «دلالة لفظ ﴿إمام﴾»","url":""}]},{"id":"s36-52","number":52,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة وصف الإمام بأنه ﴿مُبِينٍ﴾؟","answer":"يدل على أنه بيّن في نفسه ومبيّن لما أودع فيه، فلا خفاء في سجله ولا التباس في دلالته عند الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص490، تحت عنوان «نكتة التقييد بالصفة ﴿مبين﴾»","url":""}]},{"id":"s36-11","number":11,"surah":36,"verses":[13],"references":[{"surah":36,"verses":[13]}],"verseLabel":"يس: 13","question":"ما سرّ عدم تسمية القرية في قوله ﴿أَصْحَابَ الْقَرْيَةِ﴾؟","answer":"لم تسم القرية لأن المقصود ضرب المثل بحال أصحابها مع الرسل، وما جرى من التكذيب وعاقبته، لا معرفة مكانها. فإبهام الاسم يوجه النظر إلى العبرة التي من أجلها سيقت القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص498–499، تحت عنوان «نكتة عدم تعيين القرية»","url":""}]},{"id":"s36-12","number":12,"surah":36,"verses":[14],"references":[{"surah":36,"verses":[14]}],"verseLabel":"يس: 14","question":"لماذا عُبّر عن إرسال الرسول الثالث بقوله: ﴿فَعَزَّزْنَا بِثَالِثٍ﴾؟","answer":"لأن الثالث قوّى الرسولين وشد أزرهما وزاد الحجة ظهورًا؛ فلفظ التعزيز يصور الرسالة قوة متساندة، لا مجرد زيادة عددية.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص508–509، تحت عنوان «نكتة التعبير بلفظ (عزز)»","url":""}]},{"id":"s36-13","number":13,"surah":36,"verses":[15],"references":[{"surah":36,"verses":[15]}],"verseLabel":"يس: 15","question":"ماذا أراد المكذبون بقولهم للرسل: ﴿مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا﴾؟","answer":"حصروا الرسل في وصف البشرية توهمًا أن الرسول يجب أن يكون ملكًا، وجعلوا مماثلتهم لهم حجة على نفي الرسالة؛ فتكشف العبارة أصل شبهتهم وفسادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص515، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s36-14","number":14,"surah":36,"verses":[18],"references":[{"surah":36,"verses":[18]}],"verseLabel":"يس: 18","question":"لماذا قال أهل القرية للرسل: ﴿إِنَّا تَطَيَّرْنَا بِكُمْ﴾؟","answer":"استعاروا التطير للتشاؤم، كأن قدوم الرسل هو الطائر الذي جلب الشؤم؛ وبذلك قلبوا نعمة النصح سببًا للمصيبة تهربًا من الحجة وتبريرًا للتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص537–538، تحت عنوان «بلاغة التعبير بـ﴿تطيرنا﴾»","url":""}]},{"id":"s36-15","number":15,"surah":36,"verses":[19],"references":[{"surah":36,"verses":[19]}],"verseLabel":"يس: 19","question":"ماذا يعني جواب الرسل: ﴿طَائِرُكُمْ مَعَكُمْ﴾؟","answer":"يعني أن سبب ما ينالهم ملازم لهم ناشئ من كفرهم وأعمالهم، لا من الرسل؛ فالتعبير يعيد الشؤم المزعوم إلى مصدره الحقيقي ويحمّلهم مسؤولية اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص548–549، تحت عنوان «بلاغة التعبير بـ﴿طائركم﴾»","url":""}]},{"id":"s36-16","number":16,"surah":36,"verses":[20],"references":[{"surah":36,"verses":[20]}],"verseLabel":"يس: 20","question":"ماذا يوحي مجيء الرجل ﴿مِنْ أَقْصَى الْمَدِينَةِ﴾؟","answer":"يوحي بأن دعوة الرسل بلغت أطراف المدينة، وأن الرجل قطع المسافة لنصرتهم؛ فيبرز صدق إيمانه وحرصه، ويدفع توهم تواطئه القريب معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص560، تحت عنوان «دلالة التعبير بقوله تعالى ﴿من أقصى المدينة﴾»","url":""}]},{"id":"s36-17","number":17,"surah":36,"verses":[21],"references":[{"surah":36,"verses":[21]}],"verseLabel":"يس: 21","question":"ما الذي يضيفه قوله عن الرسل: ﴿وَهُمْ مُهْتَدُونَ﴾؟","answer":"يضم إلى إخلاصهم سلامة الطريق؛ فهم لا يطلبون منفعة لأنفسهم، وهم كذلك على هدى في علمهم وسلوكهم، فاجتمع للدعوة صدق القصد وصحة المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص571، تحت عنوان «فائدة الإخبار بقوله ﴿وهم مهتدون﴾»","url":""}]},{"id":"s36-18","number":18,"surah":36,"verses":[22],"references":[{"surah":36,"verses":[22]}],"verseLabel":"يس: 22","question":"لماذا قال المؤمن: ﴿وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي﴾ بدل أن يقول لقومه: ما لكم لا تعبدون؟","answer":"عدل إلى الحديث عن نفسه تعريضًا لطيفًا؛ قدّم لهم النصيحة في صورة محاسبة ذاتية حتى لا يثير عنادهم، مع أن المقصود دعوتهم إلى عبادة فاطرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص574–575، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s36-19","number":19,"surah":36,"verses":[22],"references":[{"surah":36,"verses":[22]}],"verseLabel":"يس: 22","question":"لماذا انتقل الرجل من قوله: ﴿فَطَرَنِي﴾ إلى خطاب قومه: ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"بدأ بنفسه تلطفًا وتعريضًا، ثم واجههم بحقيقة الرجوع لأنها تشملهم ولا تحتمل الإعراض؛ فجمع رفق الدعوة مع صراحة الإنذار والمساءلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص575، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s36-20","number":20,"surah":36,"verses":[26],"references":[{"surah":36,"verses":[26]}],"verseLabel":"يس: 26","question":"ما سرّ الانتقال إلى قوله ﴿قِيلَ ادْخُلِ الْجَنَّةَ﴾ بعد موقف الرجل المؤمن؟","answer":"طوى النظم ما وقع للرجل بين إعلان إيمانه والأمر بدخول الجنة، وفيه كناية عن قتله وانتقاله إلى كرامة الله. فالإيجاز يوجه الاهتمام إلى فوزه، ويجعل جزاء إيمانه هو المشهد البارز في القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص600–601، تحت عنوان «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s36-21","number":21,"surah":36,"verses":[26,27],"references":[{"surah":36,"verses":[26,27]}],"verseLabel":"يس: 26-27","question":"لماذا تمنى المؤمن بعد دخوله الجنة أن يعلم قومه بما أكرمه الله؟","answer":"بقي ناصحًا لقومه حتى بعد أذاهم له؛ تمنى أن يعرفوا أن الإيمان الذي دعاهم إليه أورث المغفرة والكرامة، لعل علمهم بذلك يحملهم على التصديق والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص604–605، تحت عنوان «سبب إيراد التمني»","url":""}]},{"id":"s36-22","number":22,"surah":36,"verses":[29],"references":[{"surah":36,"verses":[29]}],"verseLabel":"يس: 29","question":"لماذا وُصفت الصيحة التي أهلكتهم بأنها ﴿وَاحِدَةً﴾؟","answer":"لتأكيد أنها لم تحتج إلى تكرار ولا معالجة؛ صيحة واحدة أنهت قوتهم، وفي ذلك تصوير لسرعة الهلاك وسهولة إنفاذ القدرة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص621، تحت عنوان «فائدة توكيد الموصوف بـ﴿واحدة﴾»","url":""}]},{"id":"s36-53","number":53,"surah":36,"verses":[29],"references":[{"surah":36,"verses":[29]}],"verseLabel":"يس: 29","question":"ما الصورة في قوله عن أصحاب القرية: ﴿فَإِذَا هُمْ خَامِدُونَ﴾؟","answer":"شبّههم بنار كانت متقدة ثم انطفأت فجأة؛ فبعد الحركة والصخب صاروا ساكنين لا أثر للحياة فيهم، وتختصر كلمة ﴿خامدون﴾ انقلابهم الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص623، تحت عنوان «بلاغة الاستعارة ﴿فإذا هم خامدون﴾»","url":""}]},{"id":"s36-23","number":23,"surah":36,"verses":[30],"references":[{"surah":36,"verses":[30]}],"verseLabel":"يس: 30","question":"ما سر النداء في قوله: ﴿يَا حَسْرَةً عَلَى الْعِبَادِ﴾؟","answer":"يصوّر الحسرة كأنها شيء حاضر يُنادى ليقبل، لأن الحال بلغت غاية الأسف: يتكرر مجيء الرسل ويتكرر الاستهزاء بهم، فكأن هذا موطن الحسرة الكبرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص627–628، تحت عنوان «فائدة النداء ﴿يا حسرة﴾ وغرضه»","url":""}]},{"id":"s36-24","number":24,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"لماذا رتبت الآية إحياء الأرض ثم إخراج الحب ثم أكل الناس منه؟","answer":"لأنها تنتقل من أصل الدليل إلى ثمرته المشاهدة: تحيا الأرض الميتة، فيخرج منها القوت، ثم يصل إلى الإنسان؛ فيجتمع برهان البعث مع تذكيرهم بالنعمة التي يعيشون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص652، تحت عنوان «بلاغة الترتيب بين الجمل المتعاطفة»","url":""}]},{"id":"s36-54","number":54,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"لماذا خُصَّ ﴿الْحَبَّ﴾ بالذكر بعد إحياء الأرض؟","answer":"لأنه أبرز ما تقوم به حياة الإنسان وأقرب ثمرات الأرض إلى حاجته؛ فذِكره يدمج في دليل الإحياء تذكيرًا بنعمة الرزق والقوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص654، تحت عنوان «بديع الإدماج ﴿وأخرجنا منها حبًّا﴾»","url":""}]},{"id":"s36-55","number":55,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"ما الذي يضيفه قوله بعد إخراج الحب: ﴿فَمِنْهُ يَأْكُلُونَ﴾؟","answer":"يلفتهم من مشهد النبات إلى صلته المباشرة بحياتهم؛ فما يخرج من الأرض ليس منظرًا فحسب بل قوتهم، فتقوى الحجة بالنعمة المحسوسة التي يباشرونها كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص655، تحت عنوان «براعة الإيماء بمفردة الأكل»","url":""}]},{"id":"s36-25","number":25,"surah":36,"verses":[35],"references":[{"surah":36,"verses":[35]}],"verseLabel":"يس: 35","question":"كيف تتسع ﴿وَمَا عَمِلَتْهُ أَيْدِيهِمْ﴾ لمعنيين مع قراءتي إثبات الهاء وحذفها؟","answer":"بإثبات الهاء تكون ﴿ما﴾ موصولة: يأكلون من ثمرٍ لم تصنعه أيديهم. وبحذفها تحتمل المصدرية، أي ومن عمل أيديهم، فتجمع القراءتان بين كون الثمر خلقًا لله وكون بعض الطعام مما يعالجه الإنسان ويصنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص668–669، تحت عنوان «توجيه القراءات القرآنية في الآية»","url":""}]},{"id":"s36-26","number":26,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"لماذا افتتح الحديث عن خلق الأزواج بالتسبيح لا بالحمد: ﴿سُبْحَانَ الَّذِي خَلَقَ﴾؟","answer":"لأن تنوع الأزواج ودقة نظامها يكشفان كمال الخالق وتنزهه عن الشريك والعجز؛ فناسب المقام تنزيهه عما لا يليق به قبل تعداد دلائل قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص674، تحت عنوان «مناسبة إيثار التسبيح على الحمد»","url":""}]},{"id":"s36-56","number":56,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"ما سر اختيار كلمة ﴿الْأَزْوَاجَ﴾ في قوله: ﴿خَلَقَ الْأَزْوَاجَ كُلَّهَا﴾؟","answer":"تشمل الأصناف والأنواع المتقابلة والمتآلفة، لا الذكر والأنثى وحدهما؛ فتفتح اللفظة معنى التنوع الشامل في النبات والأنفس وما يجهله البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص675، تحت عنوان «نكتة استعمال لفظ ﴿الأزواج﴾»","url":""}]},{"id":"s36-57","number":57,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"لماذا عطف ﴿وَمِمَّا لَا يَعْلَمُونَ﴾ على الأزواج التي يعرفها الناس؟","answer":"ليدل على أن ما عرفوه جزء يسير من نظام الخلق، وأن وراءه أنواعًا لا يحيطون بها؛ فيتسع الدليل ويتجدد مع كل ما يكشفه العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص677–678، تحت عنوان «سر عطف المجهول على المعلوم ﴿ومما لا يعلمون﴾»","url":""}]},{"id":"s36-27","number":27,"surah":36,"verses":[37],"references":[{"surah":36,"verses":[37]}],"verseLabel":"يس: 37","question":"ما سرّ التعبير بـ﴿وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ﴾؟","answer":"استعير السلخ لإزالة ضوء النهار عن موضع الليل، كما ينزع الجلد عما يستره فينكشف ما تحته. فالصورة تجعل ذهاب النور وظهور الظلمة مشهدًا محسوسًا، وتبرز دقة الانتقال بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص685–686، تحت عنوان «بلاغة الاستعارة في ﴿نسلخ﴾»","url":""}]},{"id":"s36-28","number":28,"surah":36,"verses":[38],"references":[{"surah":36,"verses":[38]}],"verseLabel":"يس: 38","question":"لماذا قيل عن الشمس: ﴿تَجْرِي﴾؟","answer":"ليصور حركتها المستمرة السريعة في نظام لا يفتر؛ فاللفظ ينقلها من جرم يبدو ساكنًا للناظر إلى آية متحركة منضبطة بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص693، تحت عنوان «نكتة استعمال مفردة الجري»","url":""}]},{"id":"s36-29","number":29,"surah":36,"verses":[39],"references":[{"surah":36,"verses":[39]}],"verseLabel":"يس: 39","question":"لماذا شُبّه القمر في آخر منازله بـ﴿الْعُرْجُونِ﴾؟","answer":"لأنه يعود دقيقًا مقوسًا مصفرًا كعود عذق النخل بعد أن يجف؛ فالتشبيه يرسم الهيئة واللون والدقة والانحناء في صورة مألوفة دقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص704–705، تحت عنوان «بلاغة التشبيه التمثيلي ﴿كالعرجون القديم﴾»","url":""}]},{"id":"s36-58","number":58,"surah":36,"verses":[39],"references":[{"surah":36,"verses":[39]}],"verseLabel":"يس: 39","question":"ما الذي يضيفه وصف العرجون بـ﴿الْقَدِيمِ﴾؟","answer":"فالعرجون لا يدق ويقوس ويصفر تمامًا إلا بعد أن ييبس ويقدم؛ لذلك أكمل الوصف أوجه الشبه وجعل الصورة أشد دقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص705، تحت عنوان «نكتة التقييد بالصفة ﴿القديم﴾»","url":""}]},{"id":"s36-30","number":30,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"لماذا قيل: ﴿لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ﴾؟","answer":"لأن ﴿ينبغي﴾ تنفي الإمكان والملاءمة معًا؛ فليس من شأن الشمس في النظام الذي قدره الله أن تلحق القمر فتفسد حسابه، لا أنها تحاول ثم تعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص709–710، تحت عنوان «نكتة استعمال فعل ﴿ينبغي﴾»","url":""}]},{"id":"s36-59","number":59,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"ما الصورة في قوله: ﴿وَلَا اللَّيْلُ سَابِقُ النَّهَارِ﴾؟","answer":"صوّر الليل والنهار كمتسابقين، لكل منهما حد لا يتجاوزه؛ فلا يطغى أحدهما على الآخر، ويظل تعاقبهما جاريًا وفق التقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص713، تحت عنوان «بلاغة الكناية ﴿ولا الليل سابق النهار﴾»","url":""}]},{"id":"s36-31","number":31,"surah":36,"verses":[41],"references":[{"surah":36,"verses":[41]}],"verseLabel":"يس: 41","question":"ما دلالة وصف الفلك بأنه ﴿الْمَشْحُونِ﴾؟","answer":"يدل على امتلائه بالناس وما يحتاجون إليه، ومع ذلك حملهم الله سالمين؛ فيبرز عظم القدرة والعناية في سفينة مثقلة وسط الطوفان.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص730، تحت عنوان «نكتة التعبير بقوله: ﴿المشحون﴾»","url":""}]},{"id":"s36-32","number":32,"surah":36,"verses":[45],"references":[{"surah":36,"verses":[45]}],"verseLabel":"يس: 45","question":"ما سرّ حذف جواب الشرط بعد قوله ﴿وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ﴾؟","answer":"حذف الجواب، وتقديره أنهم أعرضوا، لدلالة السياق التالي عليه. وفي الحذف تصوير لعدم مبالاتهم بالنصح؛ فكأن الأمر بالتقوى لم يلق منهم ما يستحق أن يذكر سوى ما يكشفه السياق من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص755، تحت عنوان «بلاغة حذف جواب الشرط»","url":""}]},{"id":"s36-33","number":33,"surah":36,"verses":[47],"references":[{"surah":36,"verses":[47]}],"verseLabel":"يس: 47","question":"ماذا يكشف سؤال الكافرين: ﴿أَنُطْعِمُ مَنْ لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ﴾؟","answer":"هو استفهام إنكاري اتخذوه ذريعة للبخل: احتجوا بأن فقر المحتاج واقع بمشيئة الله، وغفلوا أن أمره بالإنفاق من مشيئته وأن المال الذي بأيديهم رزقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص771، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s36-60","number":60,"surah":36,"verses":[47],"references":[{"surah":36,"verses":[47]}],"verseLabel":"يس: 47","question":"كيف قلب الكافرون الاحتجاج بمشيئة الله في قولهم: ﴿لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ﴾؟","answer":"علّقوا إطعام الفقير على المشيئة ليوهموا أنهم يوافقون إرادة الله بتركه، مع أن الله ابتلاهم بالمال وأمرهم بالإنفاق؛ فستروا البخل بكلمة حق أريد بها إسقاط التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص772، تحت عنوان «بلاغة الكناية في تعليق الجزاء بالمشيئة»","url":""}]},{"id":"s36-34","number":34,"surah":36,"verses":[49],"references":[{"surah":36,"verses":[49]}],"verseLabel":"يس: 49","question":"ما دلالة أخذهم بالصيحة ﴿وَهُمْ يَخِصِّمُونَ﴾؟","answer":"يفاجئهم العذاب وهم غارقون في خصومات الأسواق والمعاملات، لا ينتظرون نهاية العالم؛ فالكلمة ترسم انشغالهم وصخبهم لحظة الانقطاع المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص790، تحت عنوان «دلالة لفظ ﴿يخصمون﴾ في السياق»","url":""}]},{"id":"s36-35","number":35,"surah":36,"verses":[51],"references":[{"surah":36,"verses":[51]}],"verseLabel":"يس: 51","question":"ما الذي تصوره كلمة ﴿يَنْسِلُونَ﴾ في خروجهم من الأجداث؟","answer":"تصور خروجًا سريعًا متتابعًا، كأنهم يندفعون من القبور إلى المحشر لا يملكون التوقف؛ فتجعل حركة البعث مشهدًا حيًا عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص15، تحت عنوان «سر التعبير بلفظ: ﴿ينسلون﴾»","url":""}]},{"id":"s36-36","number":36,"surah":36,"verses":[52],"references":[{"surah":36,"verses":[52]}],"verseLabel":"يس: 52","question":"لماذا سمّى المبعوثون قبورهم ﴿مَرْقَدَنَا﴾؟","answer":"لأن ما كانوا فيه يشبه الرقاد بالنسبة إلى هول البعث، أو لأنهم ناموا حقيقة بين النفختين؛ فاللفظ يصور دهشتهم من الانتقال المفاجئ من السكون إلى المشهد العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص21–22، تحت عنوان «توجيه التعبير بلفظ: ﴿مرقدنا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s36-61","number":61,"surah":36,"verses":[52],"references":[{"surah":36,"verses":[52]}],"verseLabel":"يس: 52","question":"كيف جاء جواب ﴿هَذَا مَا وَعَدَ الرَّحْمَنُ﴾ على سؤالهم: ﴿مَنْ بَعَثَنَا﴾؟","answer":"عدل عن تعيين الباعث إلى ما هو أهم: هذا هو البعث الذي كذبوا به، وقد صدق المرسلون؛ فواجه دهشتهم بالحقيقة التي تنفعهم وتبكت إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص24–25، تحت عنوان «بلاغة العدول بطريق الأسلوب الحكيم»","url":""}]},{"id":"s36-37","number":37,"surah":36,"verses":[55],"references":[{"surah":36,"verses":[55]}],"verseLabel":"يس: 55","question":"ما دلالة كون أهل الجنة ﴿فِي شُغُلٍ﴾؟","answer":"يدل على استغراقهم في نعيم متجدد يملك عليهم نفوسهم، فلا يلتفتون إلى أهل النار ولا إلى ما يكدر سرورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص47، تحت عنوان «دلالة لفظ ﴿شغل﴾»","url":""}]},{"id":"s36-62","number":62,"surah":36,"verses":[55],"references":[{"surah":36,"verses":[55]}],"verseLabel":"يس: 55","question":"لماذا وُصف أصحاب الجنة بأنهم ﴿فَاكِهُونَ﴾؟","answer":"لأن اللفظ يجمع التلذذ والسرور والمرح الطيب؛ فهو أوسع من مجرد الضحك ويصور نعيم النفس مع نعيم الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص49، تحت عنوان «نكتة التعبير بـ﴿فاكهون﴾»","url":""}]},{"id":"s36-38","number":38,"surah":36,"verses":[58],"references":[{"surah":36,"verses":[58]}],"verseLabel":"يس: 58","question":"ما الذي يضيفه قوله في سلام أهل الجنة: ﴿مِنْ رَبٍّ﴾؟","answer":"يجعل السلام صادرًا من الله نفسه لا بواسطة، وذلك غاية التكريم والأمان؛ فشرف التحية من شرف قائلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص68–69، تحت عنوان «نكتة تقييد القول بكونه من الله»","url":""}]},{"id":"s36-63","number":63,"surah":36,"verses":[58],"references":[{"surah":36,"verses":[58]}],"verseLabel":"يس: 58","question":"لماذا خُتم سلام أهل الجنة بوصف ﴿رَحِيمٍ﴾؟","answer":"ليدل على أن هذا السلام والنعيم أثر من رحمته، ويطمئنهم إلى دوام الإكرام والأمان؛ فمقام الجنة مقام الرحمة الكاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص69، تحت عنوان «مناسبة إيثار التعبير بوصف الربوبية»","url":""}]},{"id":"s36-39","number":39,"surah":36,"verses":[59],"references":[{"surah":36,"verses":[59]}],"verseLabel":"يس: 59","question":"ما دلالة الأمر للمجرمين: ﴿وَامْتَازُوا الْيَوْمَ﴾؟","answer":"هو أمر إهانة وفصل: انفردوا عن المؤمنين وعن شفعائكم المزعومين، واذهبوا إلى مصيركم؛ فيجسد انقطاع الروابط وظهور العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص73–74، تحت عنوان «غرض التعبير بلفظ ﴿وامتازوا﴾»","url":""}]},{"id":"s36-40","number":40,"surah":36,"verses":[60],"references":[{"surah":36,"verses":[60]}],"verseLabel":"يس: 60","question":"لماذا سمّى القرآن طاعة الشيطان ﴿عِبَادَةً﴾ له؟","answer":"لأن من أطاعه في الكفر والمعصية واتبع أمره فقد خضع له خضوع العابد، وإن لم يسجد له؛ فتكشف التسمية خطورة الطاعة التي تصرف حق الله إلى عدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص82–83، تحت عنوان «نكتة نسبة العبادة إلى ﴿الشيطان﴾»","url":""}]},{"id":"s36-41","number":41,"surah":36,"verses":[65],"references":[{"surah":36,"verses":[65]}],"verseLabel":"يس: 65","question":"لماذا يُختم على أفواه المجرمين يوم القيامة؟","answer":"لأنهم اعتادوا الإنكار والكذب، فيمنع اللسان وتنتقل الشهادة إلى الجوارح التي لا تستطيع المكابرة؛ فتقوم الحجة من أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص112، تحت عنوان «نكتة التعبير بالختم على الأفواه»","url":""}]},{"id":"s36-64","number":64,"surah":36,"verses":[65],"references":[{"surah":36,"verses":[65]}],"verseLabel":"يس: 65","question":"لماذا جُعل الكلام للأيدي والشهادة للأرجل؟","answer":"لأن اليد تباشر معظم الأعمال فنسب إليها الكلام، والرجل تحضر مواقعها فناسبها أن تشهد؛ فتتوزع الجوارح وصف الواقعة وإثبات مكانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص115، تحت عنوان «سبب إيثار جعل الكلام للأيدي والشهادة للأرجل»","url":""}]},{"id":"s36-42","number":42,"surah":36,"verses":[66],"references":[{"surah":36,"verses":[66]}],"verseLabel":"يس: 66","question":"ما دلالة التهديد بقوله: ﴿لَطَمَسْنَا عَلَى أَعْيُنِهِمْ﴾؟","answer":"يصور إمكان محو أعينهم وملامحها حتى لا يبقى منفذ للبصر، أو طمس بصائرهم؛ وفي الحالين تهديد بسلب وسيلة الاهتداء التي عطلوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص126، تحت عنوان «دلالة التعبير بـ﴿لطمسنا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s36-65","number":65,"surah":36,"verses":[66],"references":[{"surah":36,"verses":[66]}],"verseLabel":"يس: 66","question":"ما الذي تصوره كلمة ﴿فَاسْتَبَقُوا الصِّرَاطَ﴾ بعد طمس الأعين؟","answer":"تصورهم يحاولون الوصول مسرعين إلى الطريق، لكن الطمس يجعل السباق عبثًا؛ فتجتمع شدة الحرص مع استحالة الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص127، تحت عنوان «دلالة لفظ ﴿فاستبقوا﴾»","url":""}]},{"id":"s36-43","number":43,"surah":36,"verses":[68],"references":[{"surah":36,"verses":[68]}],"verseLabel":"يس: 68","question":"ما الصورة في قوله: ﴿وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ﴾؟","answer":"يصوّر الشيخوخة تنكيسًا بعد اكتمال البنية والقوة: يعود الإنسان من الصعود إلى الضعف ونقص الحواس، كأن خلقه قُلب على مراحله الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص146، تحت عنوان «بلاغة الاستعارة في التنكيس»","url":""}]},{"id":"s36-44","number":44,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"لماذا نفى الله أنه علّم النبي ﷺ الشعر؟","answer":"ليقطع شبهة أن القرآن كلام شاعر؛ فطبيعة الوحي والذكر تختلف عن صنعة الشعر وتخييله، والرسول لم يُعرف به أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص154، تحت عنوان «فائدة النفي في قوله: ﴿وما علمناه الشعر وما ينبغي له﴾»","url":""}]},{"id":"s36-66","number":66,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"ماذا يضيف قوله عن الشعر: ﴿وَمَا يَنْبَغِي لَهُ﴾ بعد نفي تعليمه؟","answer":"ينفي مجرد ملاءمة الشعر لطبيعة رسالته، لا وقوعه فقط؛ فليس الشعر من شأنه ولا مما ينسجم مع مقام الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص155، تحت عنوان «فائدة عطف نفي الانبغاء»","url":""}]},{"id":"s36-45","number":45,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"ما دلالة قوله عن الأنعام: ﴿مِمَّا عَمِلَتْ أَيْدِينَا﴾؟","answer":"هو تمثيل لقدرة الله المباشرة في الإيجاد والإتقان بما يقرّب المعنى، مع إضافة الأيدي إلى ضمير العظمة لتفخيم الصنع والعناية، من غير تشبيه للخالق بالمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص173، تحت عنوان «بلاغة إضافة الأيدي إلى ضمير العظمة»","url":""}]},{"id":"s36-67","number":67,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"لماذا خُصت ﴿أَنْعَامًا﴾ بالذكر من بين مخلوقات الله؟","answer":"لشدة اتصالها بمعاشهم ومنافعهم من ركوب وغذاء ولباس؛ فهي نعمة حاضرة يرونها ويملكونها، ومع ذلك لم يصنعوا أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص173، تحت عنوان «فائدة إيثار ذكر الأنعام»","url":""}]},{"id":"s36-46","number":46,"surah":36,"verses":[74],"references":[{"surah":36,"verses":[74]}],"verseLabel":"يس: 74","question":"كيف يكون المشركون ﴿لَهُمْ جُنْدٌ مُحْضَرُونَ﴾ مع أنهم يرجون نصر آلهتهم؟","answer":"انقلبت العلاقة: بدل أن تكون الآلهة جندًا ينصرونهم، صار العابدون هم الجند الذين يحضرون لخدمتها والدفاع عنها، ثم يُحشر الجميع للعذاب؛ وفي ذلك تهكم بعجز المعبود والعابد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص200–201، تحت عنوان «دلالة الواو في ﴿وهم لهم جند﴾»","url":""}]},{"id":"s36-47","number":47,"surah":36,"verses":[77],"references":[{"surah":36,"verses":[77]}],"verseLabel":"يس: 77","question":"كيف يحتج خلق الإنسان من نطفة على بطلان إنكاره للبعث؟","answer":"ينقله الدليل من أصل ضئيل لا حياة ظاهرة فيه إلى إنسان كامل يجادل خالقه؛ فمن قدر على الإنشاء الأول من نطفة قادر على الإعادة، والمفارقة تفضح نسيانه لأصل خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص217، تحت عنوان «بلاغة الحجاج في الآية»","url":""}]},{"id":"s36-48","number":48,"surah":36,"verses":[78],"references":[{"surah":36,"verses":[78]}],"verseLabel":"يس: 78","question":"لماذا قيل عن منكر البعث: ﴿وَضَرَبَ لَنَا مَثَلًا﴾؟","answer":"جعل العظم البالي مثالًا يقيس عليه استحالة الإحياء، لكنه أقام المثال في غير موضعه؛ قاس قدرة الخالق على قدرة المخلوق وغفل عن الإنشاء الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص231، تحت عنوان «بلاغة الاستعارة في لفظ ﴿مثلًا﴾»","url":""}]},{"id":"s36-68","number":68,"surah":36,"verses":[78],"references":[{"surah":36,"verses":[78]}],"verseLabel":"يس: 78","question":"ما دلالة قوله عن منكر البعث: ﴿وَنَسِيَ خَلْقَهُ﴾؟","answer":"يكشف أصل شبهته: نظر إلى العظم بعد فنائه ونسي أنه نفسه خُلق من عدم؛ فلو استحضر بدايته لزالت دعوى استحالة الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص233، تحت عنوان «نكتة التعبير بلفظ ﴿ونسي﴾»","url":""}]},{"id":"s36-49","number":49,"surah":36,"verses":[80],"references":[{"surah":36,"verses":[80]}],"verseLabel":"يس: 80","question":"ما سر الجمع بين ﴿الشَّجَرِ الْأَخْضَرِ﴾ وإيقاد النار منه؟","answer":"جمع بين الخضرة الرطبة والنار الحارة في مشهد واحد؛ فالذي أودع النار في ضدها وأخرجها منه قادر على إعادة الحياة إلى العظام، وفي التضاد حجة محسوسة قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص249، تحت عنوان «براعة الطباق الخفي»","url":""}]},{"id":"s36-50","number":50,"surah":36,"verses":[82],"references":[{"surah":36,"verses":[82]}],"verseLabel":"يس: 82","question":"ما دلالة القصر في قوله: ﴿إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا﴾؟","answer":"يقصر شأن الإيجاد على إرادة نافذة لا تحتاج معالجة ولا زمنًا ولا معينًا؛ فإذا أراد الله شيئًا وقع بلا مانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص262–263، تحت عنوان «بلاغة القصر بـ﴿إنما﴾»","url":""}]},{"id":"s36-51","number":51,"surah":36,"verses":[83],"references":[{"surah":36,"verses":[83]}],"verseLabel":"يس: 83","question":"ما الصورة في قوله: ﴿بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ﴾؟","answer":"هي كناية عن انفراده بالملك والتدبير والقدرة التامة، كأن زمام كل موجود في قبضته؛ ولذلك كان الرجوع إليه وحده خاتمة لازمة للسورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص273، تحت عنوان «بلاغة الكناية»","url":""}]},{"id":"s37-1","number":1,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"لماذا افتتحت سورة الصافات بالقسم؟","answer":"لتوكيد التوحيد الذي سيأتي جوابًا للقسم؛ فالمشركون بالغوا في إنكاره، فجاء القسم في المطلع تعظيمًا للخبر وزيادةً في تثبيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص286، تحت عنوان «سر الافتتاح بالقسم»","url":""}]},{"id":"s37-51","number":51,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"لماذا أقسم الله بالصافات والزاجرات والتاليات؟","answer":"لأن هذه الصفات ـ وهي للملائكة على الأظهر ـ تكشف انتظامها في العبادة وتنفيذ أمر الله وتلاوة ذكره؛ فالقسم بها تعظيم لشأنها ودلالة على عظمة خالقها ووحدانيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص286، تحت عنوان «سر القسم بالمذكورات»","url":""}]},{"id":"s37-52","number":52,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"ما الصورة التي يرسمها وصف الملائكة بـ﴿الصافات صفًّا﴾؟","answer":"يصورها منتظمة في مراتب العبادة والطاعة، بعضها فوق بعض أو مصطفة في خط مستقيم؛ وفي هذا النظام المحكم إشارة إلى دقة تدبير الخالق ووحدانيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص287، تحت عنوان «نكتة التعبير بالصف»","url":""}]},{"id":"s37-2","number":2,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا جاء قوله ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ﴾ جوابًا للقسم؟","answer":"لأنه الحقيقة المقصودة التي مهد لها القسم: تقرير وحدانية الله. فجاءت الجملة جوابًا مباشرًا لما أقسم به، وأبرزت أهم الحقائق التي أنكرها المشركون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص292، تحت عنوان «موقع جملة ﴿إن إلهكم لواحد﴾»","url":""}]},{"id":"s37-53","number":53,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ﴾؟","answer":"لأن المخاطبين شديدو الإنكار للوحدانية، فقوبل إنكارهم بالقسم و﴿إن﴾ واللام والجملة الاسمية حتى يثبت الخبر من وجوه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص294، تحت عنوان «بلاغة توالي المؤكدات»","url":""}]},{"id":"s37-54","number":54,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا قيل ﴿لَوَاحِدٌ﴾ في وصف الإله؟","answer":"لنفي تعدد الآلهة نفيًا صريحًا؛ فالواحد هو المنفرد الذي لا شريك له، وهو وصف يواجه أصل اعتقاد المشركين مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص294، تحت عنوان «سر التعبير بـ﴿لواحد﴾»","url":""}]},{"id":"s37-3","number":3,"surah":37,"verses":[6],"references":[{"surah":37,"verses":[6]}],"verseLabel":"الصافات: 6","question":"ماذا تفيد إضافة الزينة إلى الكواكب في قوله ﴿بِزِينَةٍ الْكَوَاكِبِ﴾؟","answer":"تفيد أن الكواكب نفسها هي زينة السماء بما فيها من تعدد الأشكال وحسن الانتظام والضوء؛ فليست الزينة أمرًا منفصلًا عنها، بل هي المظهر الذي تتجلى به الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص308، تحت عنوان «دلالة إضافة الزينة إلى ﴿الكواكب﴾»","url":""}]},{"id":"s37-4","number":4,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا عبّر عن استراق الشيطان للسمع بـ﴿خَطْفَةَ﴾؟","answer":"لأن الخطف أخذ سريع خفي؛ فيصور أن ما يناله الشيطان قليل عاجل، يختلسه على خوف قبل أن يدركه الشهاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص320، تحت عنوان «سر التعبير بالخطف»","url":""}]},{"id":"s37-55","number":55,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا قيل عن الشهاب ﴿فَأَتْبَعَهُ﴾؟","answer":"ليصور الشهاب لاحقًا بالشيطان فور خطفته، كأنه يتعقبه ولا يفارقه حتى يصيبه؛ فالتعبير يشعر بسرعة المطاردة واتصالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص321، تحت عنوان «سر التعبير بالإتباع»","url":""}]},{"id":"s37-56","number":56,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا وُصف الشهاب بأنه ﴿ثَاقِبٌ﴾؟","answer":"لأنه نافذ شديد الإضاءة والإصابة؛ يخترق الظلمة ويبلغ الشيطان، فيجمع الوصف قوة الضوء وقوة الأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص322، تحت عنوان «بلاغة الوصف بـ﴿ثاقب﴾»","url":""}]},{"id":"s37-5","number":5,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"ما دلالة الاستفهام في قوله ﴿أَهُمْ أَشَدُّ خَلْقًا أَمْ مَنْ خَلَقْنَا﴾؟","answer":"هو استفهام تقريري يفضح ضعف إنكارهم للبعث؛ فخلق السماوات والملائكة والكواكب أعظم من خلق البشر، ومن قدر على الأعظم قدر على إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص329، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s37-57","number":57,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا قيل ﴿مَنْ خَلَقْنَا﴾ مع أن المقصود يشمل السماوات والأرض وغيرها؟","answer":"غُلِّب العاقل لأن المذكورات تشمل الملائكة والعقلاء وغيرهم، وفي هذا التغليب إشارة إلى أشرف ما خلق الله مع بقاء العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص331، تحت عنوان «نكتة تغليب العاقل»","url":""}]},{"id":"s37-6","number":6,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا نُكّر ﴿طِينٍ﴾ في قوله ﴿مِنْ طِينٍ لَازِبٍ﴾؟","answer":"للدلالة على نوع مخصوص من الطين أصلحُه الله لبدء خلق الإنسان، مع التحقير المناسب للاحتجاج على من يستبعد البعث وهو مخلوق من مادة ضعيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص333، تحت عنوان «نكتة تنكير ﴿طين﴾»","url":""}]},{"id":"s37-58","number":58,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا وُصف الطين الذي خُلق منه الإنسان بأنه ﴿لَازِبٍ﴾؟","answer":"لأنه طين متماسك يلتصق بعضه ببعض؛ والوصف يبرز ضعف أصل الإنسان ولين مادته، فيسقط استبعاده أن يعيده الله بعد موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص333، تحت عنوان «نكتة الوصف بـ﴿لازب﴾»","url":""}]},{"id":"s37-7","number":7,"surah":37,"verses":[12],"references":[{"surah":37,"verses":[12]}],"verseLabel":"الصافات: 12","question":"كيف يُفهم قوله ﴿بَلْ عَجِبْتَ وَيَسْخَرُونَ﴾ على قراءة ضم التاء؟","answer":"المقصود عجب يليق بالله لا عجبُ جهلٍ أو خفاء؛ أي تعظيمُ أمرهم أو إنكارُ فعلهم وإظهارُ شناعته، بينما هم يقابلون دلائل القدرة بالسخرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص334–335، تحت عنوان «توجيه القراءات في ﴿عجبت﴾ وبالغتها»","url":""}]},{"id":"s37-8","number":8,"surah":37,"verses":[19],"references":[{"surah":37,"verses":[19]}],"verseLabel":"الصافات: 19","question":"لماذا وُصفت الزجرة يوم البعث بأنها ﴿وَاحِدَةٌ﴾؟","answer":"لتأكيد أن بعث الخلق جميعًا لا يحتاج إلا صيحة واحدة؛ وفي ذلك تحقير لاستبعادهم البعث وإظهار كمال قدرة الله وسرعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص357، تحت عنوان «نكتة الوصف بـ﴿واحدة﴾»","url":""}]},{"id":"s37-59","number":59,"surah":37,"verses":[19],"references":[{"surah":37,"verses":[19]}],"verseLabel":"الصافات: 19","question":"ماذا تصور ﴿إِذَا﴾ في قوله ﴿فَإِذَا هُمْ يَنْظُرُونَ﴾؟","answer":"تصور المفاجأة وسرعة الانتقال: تقع الزجرة، فإذا هم قيام ينظرون من غير مهلة؛ فكأن البعث حاضر مباغت.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص358، تحت عنوان «دلالة (إذا)»","url":""}]},{"id":"s37-9","number":9,"surah":37,"verses":[22,23],"references":[{"surah":37,"verses":[22,23]}],"verseLabel":"الصافات: 22-23","question":"ما البلاغة في الأمر ﴿فَاهْدُوهُمْ﴾ وهم مساقون إلى النار؟","answer":"هو تهكم مرير؛ استُعيرت الهداية ـ التي تكون إلى الخير ـ للدلالة إلى طريق الجحيم، فصار اللفظ نفسه يزيدهم إذلالًا وحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص370، تحت عنوان «بلاغة الاستعارة في الهداية»","url":""}]},{"id":"s37-60","number":60,"surah":37,"verses":[22,23],"references":[{"surah":37,"verses":[22,23]}],"verseLabel":"الصافات: 22-23","question":"لماذا سُمّي طريق النار ﴿صِرَاطَ الْجَحِيمِ﴾؟","answer":"استُعير الصراط للطريق الذي يسيرون فيه إلى الهلاك، وفي إضافته إلى الجحيم تصوير لطريق محدد لا يفضي إلا إلى النار مع شدة التهكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص371، تحت عنوان «بلاغة الاستعارة في الصراط»","url":""}]},{"id":"s37-10","number":10,"surah":37,"verses":[24],"references":[{"surah":37,"verses":[24]}],"verseLabel":"الصافات: 24","question":"ماذا يفيد الأمر ﴿وَقِفُوهُمْ﴾ يوم القيامة؟","answer":"يفيد إلزام الملائكة بحبسهم ومنعهم من تجاوز الموقف؛ فبعد سوقهم إلى الجحيم يوقفون للسؤال والتوبيخ، ولا يملكون فرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص372، تحت عنوان «دلالة صيغة الأمر»","url":""}]},{"id":"s37-61","number":61,"surah":37,"verses":[24],"references":[{"surah":37,"verses":[24]}],"verseLabel":"الصافات: 24","question":"لماذا لم يُذكر في قوله ﴿إِنَّهُمْ مَسْئُولُونَ﴾ عمّا يُسألون؟","answer":"لأن المقام يدل عليه، ولأن حذف المسؤول عنه يعمم السؤال فيشمل عقائدهم وأعمالهم وتقصيرهم كله، فيكون أشد تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص373، تحت عنوان «نكتة حذف المسؤول عنه»","url":""}]},{"id":"s37-11","number":11,"surah":37,"verses":[25],"references":[{"surah":37,"verses":[25]}],"verseLabel":"الصافات: 25","question":"ما غرض السؤال التوبيخي ﴿مَا لَكُمْ لَا تَنَاصَرُونَ﴾؟","answer":"يسخر من عجزهم بعد أن كانوا يتناصرون في الدنيا ويزعمون أن آلهتهم تنصرهم؛ فيكشف الفرق بين دعاواهم القديمة وذلهم التام يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص377، تحت عنوان «دلالة الاستفهام بـ﴿ما﴾ وغرضه البلاغي»","url":""}]},{"id":"s37-12","number":12,"surah":37,"verses":[27],"references":[{"surah":37,"verses":[27]}],"verseLabel":"الصافات: 27","question":"ما الصورة في قوله ﴿وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ﴾ يوم القيامة؟","answer":"يصوّر شدة توجههم بعضهم إلى بعض للوم والمحاكمة، كأن كل فريق يواجه الآخر مواجهة مباشرة؛ فتتحول صحبتهم القديمة إلى خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص386، تحت عنوان «بلاغة الاستعارة في (أقبل)»","url":""}]},{"id":"s37-62","number":62,"surah":37,"verses":[27],"references":[{"surah":37,"verses":[27]}],"verseLabel":"الصافات: 27","question":"لماذا قيل ﴿يَتَسَاءَلُونَ﴾ لا «يسألون»؟","answer":"لأن صيغة التفاعل تصور سؤالًا متبادلًا متكررًا بين الأطراف، يحمل اللوم والجدال ومحاولة كل فريق إلقاء التبعة على غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص388، تحت عنوان «سر اختيار ﴿يتساءلون﴾ مادة وصيغة»","url":""}]},{"id":"s37-13","number":13,"surah":37,"verses":[28],"references":[{"surah":37,"verses":[28]}],"verseLabel":"الصافات: 28","question":"ما الصورة في قول الأتباع للمتبوعين ﴿كُنْتُمْ تَأْتُونَنَا عَنِ الْيَمِينِ﴾؟","answer":"استُعيرت اليمين لطريق الخير والقوة والثقة؛ فهم يتهمون قادتهم بأنهم جاؤوهم من الجهة التي اطمأنوا إليها، فلبّسوا الباطل بصورة النصح والحق حتى أضلوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص396–397، تحت عنوان «بلاغة الاستعارة والكناية في لفظ ﴿اليمين﴾»","url":""}]},{"id":"s37-14","number":14,"surah":37,"verses":[35],"references":[{"surah":37,"verses":[35]}],"verseLabel":"الصافات: 35","question":"لماذا عُبّر عن موقفهم من ﴿لَا إِلَهَ إِلَّا اللَّهُ﴾ بالمضارع ﴿يَسْتَكْبِرُونَ﴾؟","answer":"ليصور استكبارهم عادةً متجددة لا موقفًا عابرًا؛ فكلما دُعوا إلى التوحيد تجدد منهم الإباء والتعالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص429، تحت عنوان «نكتة إيثار المضارع ﴿يستكبرون﴾»","url":""}]},{"id":"s37-15","number":15,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا قيل عن الرسول ﷺ ﴿بَلْ جَاءَ بِالْحَقِّ﴾ بصيغة الماضي؟","answer":"للدلالة على أن مجيئه بالحق أمر متحقق ثابت، لا دعوى منتظرة؛ فهو قد جاء برسالة واضحة من عند الله وانتهى وقوعها إلى اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص438، تحت عنوان «نكتة إيثار فعل (المجيء) ماضيًا»","url":""}]},{"id":"s37-63","number":63,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا عُرّف ﴿الْحَقِّ﴾ في قوله ﴿بَلْ جَاءَ بِالْحَقِّ﴾؟","answer":"للدلالة على الحق الكامل المعروف في بابه: الوحي والتوحيد الذي لا يلابسه باطل؛ وفي التعريف رد جامع على وصفي الشعر والجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص439، تحت عنوان «إيثار التعبير بلفظ (الحق) معرفًا»","url":""}]},{"id":"s37-64","number":64,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا قيل ﴿وَصَدَّقَ الْمُرْسَلِينَ﴾؟","answer":"لأن ما جاء به موافق لما جاءت به الرسل قبله في أصل التوحيد والهدى، فكان مجيئه تصديقًا لرسالاتهم وزيادة حجة على صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص440، تحت عنوان «سر إيثار لفظ (صدق) مادة وصيغة»","url":""}]},{"id":"s37-16","number":16,"surah":37,"verses":[40,41],"references":[{"surah":37,"verses":[40,41]}],"verseLabel":"الصافات: 40-41","question":"لماذا تكرر استثناء ﴿عِبَادَ اللَّهِ الْمُخْلَصِينَ﴾؟","answer":"لأن الاستثناء الثاني ليس تكرارًا محضًا، بل استدراك يفصل مصيرهم عن مصير المكذبين: أولئك للعذاب، وهؤلاء لجزاء معلوم كريم؛ فيرسخ الفرق بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص457، تحت عنوان «توجيه تكرار الاستثناء»","url":""}]},{"id":"s37-65","number":65,"surah":37,"verses":[40,41],"references":[{"surah":37,"verses":[40,41]}],"verseLabel":"الصافات: 40-41","question":"لماذا وُصف رزقهم في الجنة بأنه ﴿مَعْلُومٌ﴾؟","answer":"لأنه رزق حاضر مضمون يعرفون وقته وصفته، لا ينقطع ولا يتخلف؛ فالإشارة إليه كالمشاهد تزيد شعورهم بالأمن والاختصاص والتكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص460، تحت عنوان «نكتة وصف الرزق بـ﴿معلوم﴾»","url":""}]},{"id":"s37-17","number":17,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا وُصفت خمر الجنة بأنها ﴿بَيْضَاءَ﴾؟","answer":"لأن البياض يجمع صفاء اللون وبهاءه ونقاء الشراب، فيوحي بلذة خالصة لا كدر فيها ولا قبح كخمر الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص469، تحت عنوان «سر الوصف بلفظ ﴿بيضاء﴾»","url":""}]},{"id":"s37-66","number":66,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا قيل عن خمر الجنة ﴿لَذَّةٍ لِلشَّارِبِينَ﴾ بالمصدر؟","answer":"جاء المصدر للمبالغة، فكأنها اللذة نفسها لا مجرد شراب لذيذ؛ فيدل على خلو متعتها من كل منغص.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص469–470، تحت عنوان «دلالة الوصف بالمصدر في ﴿لذة﴾»","url":""}]},{"id":"s37-67","number":67,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا نُكّر ﴿غَوْلٌ﴾ في قوله ﴿لَا فِيهَا غَوْلٌ﴾؟","answer":"لنفي أي نوع من الأذى والفساد الذي يغتال العقل أو البدن؛ فالتنكير في سياق النفي يعم كل عيب تعرفه خمور الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص472، تحت عنوان «بلاغة استعمال لفظ ﴿غول﴾ نكرة»","url":""}]},{"id":"s37-18","number":18,"surah":37,"verses":[48],"references":[{"surah":37,"verses":[48]}],"verseLabel":"الصافات: 48","question":"ما دلالة وصف الحور بـ﴿قَاصِرَاتُ الطَّرْفِ﴾؟","answer":"يدل على العفة وكمال المحبة؛ فقد قصرن أبصارهن على أزواجهن فلا ينظرن إلى غيرهم، وفي الصيغة مبالغة في ثبات هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص476، تحت عنوان «وجه تعريف ﴿قاصرات﴾ بالإضافة»","url":""}]},{"id":"s37-68","number":68,"surah":37,"verses":[48],"references":[{"surah":37,"verses":[48]}],"verseLabel":"الصافات: 48","question":"ماذا يضيف وصف الحور بأنهن ﴿عِينٌ﴾؟","answer":"يضيف جمال العيون واتساعها وحسن النظر، فيكتمل وصف العفة في ﴿قاصرات الطرف﴾ بوصف الجمال في ﴿عين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص477، تحت عنوان «توجيه الوصف بـ(العين)»","url":""}]},{"id":"s37-19","number":19,"surah":37,"verses":[49],"references":[{"surah":37,"verses":[49]}],"verseLabel":"الصافات: 49","question":"لماذا شُبّه الحور بـ﴿بَيْضٌ﴾؟","answer":"شُبّه بياضهن وصفاؤهن ببيض النعام الذي يجمع لونًا نقيًا رقيقًا مشوبًا بصفرة محببة، وهو من ألوان الحسن عند العرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص478، تحت عنوان «وجه التعبير بلفظ ﴿بيض﴾»","url":""}]},{"id":"s37-69","number":69,"surah":37,"verses":[49],"references":[{"surah":37,"verses":[49]}],"verseLabel":"الصافات: 49","question":"لماذا وُصف البيض في التشبيه بأنه ﴿مَكْنُونٌ﴾؟","answer":"لأن المصون المستور لا تمسه الأيدي ولا الغبار، فالوصف يزيد التشبيه معنى الصفاء والحفظ والعفة مع جمال اللون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص478، تحت عنوان «سر وصف البيض بـ﴿مكنون﴾»","url":""}]},{"id":"s37-20","number":20,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"لماذا اختير لفظ ﴿قَرِينٌ﴾ في حديث أهل الجنة عن صاحبهم القديم؟","answer":"لأن القرين ملازم لصاحبه، فيصور قرب ذلك المشكك وشدة صحبته في الدنيا؛ ولذلك كان خلاص المؤمن من تأثيره نعمة تستحق الاستذكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص486، تحت عنوان «سر اختيار لفظ ﴿قرين﴾ مادة وصيغة»","url":""}]},{"id":"s37-70","number":70,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"لماذا قال المؤمن في الجنة ﴿كَانَ لِي قَرِينٌ﴾ بالماضي؟","answer":"ليستحضر نعمة نجاته بمقارنة حاله الحاضر في الجنة بصحبته الماضية لذلك المشكك؛ فالماضي يباعد بين حالين متقابلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص486، تحت عنوان «دلالة فعل الكون الماضي»","url":""}]},{"id":"s37-71","number":71,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"ما غرض استفهام القرين ﴿أَإِنَّكَ لَمِنَ الْمُصَدِّقِينَ﴾؟","answer":"ليس طلبًا للجواب، بل إنكار وسخرية وتعجب من الإيمان بالبعث؛ فهو يضغط على صاحبه ليشككه ويصوره ساذجًا بسبب تصديقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص491، تحت عنوان «الغرض من الاستفهام بـ (الهمزة) في الآية»","url":""}]},{"id":"s37-21","number":21,"surah":37,"verses":[55],"references":[{"surah":37,"verses":[55]}],"verseLabel":"الصافات: 55","question":"لماذا قيل عن القرين في النار إنه ﴿فِي سَوَاءِ الْجَحِيمِ﴾؟","answer":"لأن ﴿سواء﴾ تصور وقوعه في وسط الجحيم وأشد مواضعه، محاطًا بالعذاب من كل جهة؛ فتبرز هول ما نجا منه المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص509، تحت عنوان «دلالة التعبير بـ﴿سواء﴾»","url":""}]},{"id":"s37-72","number":72,"surah":37,"verses":[55],"references":[{"surah":37,"verses":[55]}],"verseLabel":"الصافات: 55","question":"ماذا تضيف إضافة ﴿سَوَاء﴾ إلى ﴿الْجَحِيمِ﴾؟","answer":"تعيّن أن التوسط ليس في نار عارضة بل في الجحيم المعروف بعذابه المتفاقم، فتزيد المشهد رهبة وتذكّر المؤمن بفضل الله في نجاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص510، تحت عنوان «الغرض من إضافة ﴿سواء﴾ إلى ﴿الجحيم﴾»","url":""}]},{"id":"s37-22","number":22,"surah":37,"verses":[62],"references":[{"surah":37,"verses":[62]}],"verseLabel":"الصافات: 62","question":"ما غرض الاستفهام في قوله ﴿أَذَلِكَ خَيْرٌ نُزُلًا أَمْ شَجَرَةُ الزَّقُّومِ﴾؟","answer":"هو تهكم وتقريع؛ فلا خير في الزقوم، وإنما وُضعت ضيافة الجنة والعذاب في مقابلة تكشف سوء اختيار المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص541، تحت عنوان «غرض الاستفهام بـ (الهمزة) في الآية»","url":""}]},{"id":"s37-73","number":73,"surah":37,"verses":[62],"references":[{"surah":37,"verses":[62]}],"verseLabel":"الصافات: 62","question":"لماذا استُعمل التفضيل ﴿خَيْرٌ﴾ بين نعيم الجنة وشجرة الزقوم؟","answer":"لزيادة التهكم بهم؛ إذ لا اشتراك حقيقي بين النعيم والعذاب في الخير، فكأن من يختار الكفر يفضّل الزقوم على الرزق الكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص542–543، تحت عنوان «دلالة التعبير بالتفضيل في الآية»","url":""}]},{"id":"s37-23","number":23,"surah":37,"verses":[65],"references":[{"surah":37,"verses":[65]}],"verseLabel":"الصافات: 65","question":"ما سرّ تشبيه طلع الزقوم برؤوس الشياطين مع أنهم لم يروها؟","answer":"اعتمد التشبيه على ما استقر في النفوس من تمثل الشيطان في غاية القبح، وإن لم تشاهد صورته. فإحالته إلى هذه الصورة المتخيلة تزيد النفرة والتهويل، وتجعل طلع الزقوم بالغًا أقصى ما يتصور من البشاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص553–554، تحت عنوان «بلاغة التشبيه في جملة: ﴿كأنه رؤوس الشياطين﴾»","url":""}]},{"id":"s37-24","number":24,"surah":37,"verses":[69,70],"references":[{"surah":37,"verses":[69,70]}],"verseLabel":"الصافات: 69-70","question":"لماذا قيل ﴿أَلْفَوْا آبَاءَهُمْ ضَالِّينَ﴾ بدل «وجدوا»؟","answer":"لأن الإلفاء يشعر بمصادفة حال ثابتة أمامهم؛ وجدوا آباءهم على الضلال فتلقوه بلا نظر ولا برهان، وكأن مجرد وجودهم عليه صار حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص568، تحت عنوان «سر إيثار التعبير بـ (الإلفاء) دون غيره»","url":""}]},{"id":"s37-74","number":74,"surah":37,"verses":[69,70],"references":[{"surah":37,"verses":[69,70]}],"verseLabel":"الصافات: 69-70","question":"ما الصورة في قوله ﴿فَهُمْ عَلَى آثَارِهِمْ يُهْرَعُونَ﴾؟","answer":"تصورهم يندفعون مسرعين خلف آثار آبائهم بلا تفكير، كأن قوة تدفعهم؛ فتفضح شدة التقليد وغياب العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص571–572، تحت عنوان «دلالة التعبير بالهرع في الفعل ﴿يهرعون﴾»","url":""}]},{"id":"s37-25","number":25,"surah":37,"verses":[75],"references":[{"surah":37,"verses":[75]}],"verseLabel":"الصافات: 75","question":"لماذا عبّر عن دعاء نوح بقوله ﴿نَادَانَا﴾؟","answer":"النداء دعاء بصوت واستغاثة بعد طول المعاناة، فيصور شدة اضطراره وتوجهه إلى الله وحده طلبًا للنجاة والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص592، تحت عنوان «دلالة التعبير بالفعل الماضي (نادى)»","url":""}]},{"id":"s37-75","number":75,"surah":37,"verses":[75],"references":[{"surah":37,"verses":[75]}],"verseLabel":"الصافات: 75","question":"لماذا قيل ﴿فَلَنِعْمَ الْمُجِيبُونَ﴾؟","answer":"﴿نعم﴾ صيغة مدح تبلغ بالإجابة غايتها؛ فاستجابة الله كاملة عاجلة، وجمع المجيبون للتعظيم وتطمين كل داع صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص594، تحت عنوان «دلالة التعبير بـ (نعم)»","url":""}]},{"id":"s37-26","number":26,"surah":37,"verses":[77],"references":[{"surah":37,"verses":[77]}],"verseLabel":"الصافات: 77","question":"ماذا يفيد قوله ﴿وَجَعَلْنَا ذُرِّيَّتَهُ هُمُ الْبَاقِينَ﴾؟","answer":"يفيد الحصر: ذرية نوح هي التي امتد منها نسل البشر بعد الطوفان، فجيء بضمير الفصل لتأكيد اختصاصهم بالبقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص603–604، تحت عنوان «نوع الحصر ودلالته»","url":""}]},{"id":"s37-76","number":76,"surah":37,"verses":[77],"references":[{"surah":37,"verses":[77]}],"verseLabel":"الصافات: 77","question":"ما البلاغة في التعبير عن امتداد نسل نوح بـ﴿الْبَاقِينَ﴾؟","answer":"كنّى بالبقاء عن استمرار الذرية وامتدادها بعد هلاك المكذبين؛ فالكلمة تجمع النجاة واستمرار النسل في إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص605، تحت عنوان «بلاغة الكناية في استعمال مفردة البقاء»","url":""}]},{"id":"s37-27","number":27,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"لماذا بدأ قوله ﴿سَلَامٌ عَلَى نُوحٍ﴾ بكلمة ﴿سَلَامٌ﴾ نكرة؟","answer":"للدلالة على سلام عظيم متجدد يفوق الوصف، باقٍ لنوح في الأمم بعده جزاءً لإيمانه وصبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص609، تحت عنوان «علة الابتداء بالنكرة»","url":""}]},{"id":"s37-77","number":77,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"ماذا يفيد حرف ﴿عَلَى﴾ في قوله ﴿سَلَامٌ عَلَى نُوحٍ﴾؟","answer":"يفيد شمول السلام له وتمكنه منه، كأنه غطاء يحيط به، مع دلالة على دوام تكريمه وعلو منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص609–610، تحت عنوان «دلالة حرف الاستعلاء»","url":""}]},{"id":"s37-28","number":28,"surah":37,"verses":[83],"references":[{"surah":37,"verses":[83]}],"verseLabel":"الصافات: 83","question":"ما معنى كون إبراهيم ﴿مِنْ شِيعَةِ﴾ نوح؟","answer":"أي أنه على طريقته في التوحيد والدعوة والثبات، لا أنه من زمنه أو أتباعه المباشرين؛ فالشيعة هنا جماعة المنهج الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص619–620، تحت عنوان «تعيين مرجع الضمير»","url":""}]},{"id":"s37-78","number":78,"surah":37,"verses":[83],"references":[{"surah":37,"verses":[83]}],"verseLabel":"الصافات: 83","question":"لماذا أكّد قوله ﴿وَإِنَّ مِنْ شِيعَتِهِ لَإِبْرَاهِيمَ﴾ بإن واللام؟","answer":"لتثبيت قوة الصلة المنهجية بين إبراهيم ونوح مع تباعد الزمن، وإبراز أن دعوة التوحيد سلسلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص620، تحت عنوان «بلاغة التوكيد ودلالته البيانية»","url":""}]},{"id":"s37-29","number":29,"surah":37,"verses":[84],"references":[{"surah":37,"verses":[84]}],"verseLabel":"الصافات: 84","question":"لماذا نُسبت السلامة إلى ﴿قَلْبٍ﴾ إبراهيم؟","answer":"لأن القلب موضع الاعتقاد والقصد، فإذا سلم من الشرك والغل والفساد تبعه العمل؛ فسلامته أصل سلامة الإنسان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص623، تحت عنوان «بلاغة استعمال مفردة القلب»","url":""}]},{"id":"s37-79","number":79,"surah":37,"verses":[84],"references":[{"surah":37,"verses":[84]}],"verseLabel":"الصافات: 84","question":"لماذا نُكّر ﴿قَلْبٍ﴾ في قوله ﴿بِقَلْبٍ سَلِيمٍ﴾؟","answer":"للتعظيم؛ أي بقلب عظيم الشأن بلغ درجة متميزة من الصفاء والإخلاص لا يحيط بمدحه وصف موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص624، تحت عنوان «نكتة تنكير لفظ (قلب)»","url":""}]},{"id":"s37-30","number":30,"surah":37,"verses":[88,89],"references":[{"surah":37,"verses":[88,89]}],"verseLabel":"الصافات: 88-89","question":"لماذا قيل ﴿فَنَظَرَ نَظْرَةً فِي النُّجُومِ﴾ لا «إلى النجوم»؟","answer":"لأن المراد إعمال الفكر فيما يتعلق بالنجوم لا مجرد إبصارها؛ اتخذ النظر فيها وسيلةً للتورية والخلاص من الخروج معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص635، تحت عنوان «فائدة استعمال حرف الظرفية دون (إلى)»","url":""}]},{"id":"s37-80","number":80,"surah":37,"verses":[88,89],"references":[{"surah":37,"verses":[88,89]}],"verseLabel":"الصافات: 88-89","question":"أين التورية في قول إبراهيم ﴿إِنِّي سَقِيمٌ﴾؟","answer":"أوهم قومه مرض الجسد، وأراد معنى صحيحًا يحتمله اللفظ؛ كسقمه من شركهم أو أنه صائر إلى السقم والموت، فنجا من الخروج دون تصريح بالكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص639، تحت عنوان «بديع فن التورية»","url":""}]},{"id":"s37-31","number":31,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"ما غرض سؤال إبراهيم الأصنام ﴿أَلَا تَأْكُلُونَ﴾؟","answer":"هو استهزاء وتعريض بعجزها؛ قدّم لها الطعام ثم سألها ليقيم على قومه حجة محسوسة: من لا يأكل ولا يجيب لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص645–646، تحت عنوان «معنى الاستفهام وغرضه المجازي»","url":""}]},{"id":"s37-81","number":81,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"ما غرض قوله للأصنام ﴿مَا لَكُمْ لَا تَنْطِقُونَ﴾؟","answer":"زيادة في التحقير وإلزام لقومه؛ فصمتها بعد السؤال يكشف عجزها التام عن النفع والجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص648، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s37-82","number":82,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"لماذا خاطب إبراهيم الأصنام خطاب العقلاء؟","answer":"ليجاري تصور عابديها ثم يهدمه عمليًا؛ عاملها لحظةً كمن يسمع ويجيب، فظهر للحاضرين أنها جماد أعجز من أن تُعبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص648، تحت عنوان «نكتة مخاطبة الجماد مخاطبة العقلاء»","url":""}]},{"id":"s37-32","number":32,"surah":37,"verses":[93],"references":[{"surah":37,"verses":[93]}],"verseLabel":"الصافات: 93","question":"ما المعنيان اللذان يجتمعان في قوله ﴿ضَرْبًا بِالْيَمِينِ﴾؟","answer":"يحتمل اليمين الجارحة التي باشر بها الضرب، ويحتمل القوة أو القسم الذي سبق منه بكسر الأصنام؛ فيجمع التعبير قوة التنفيذ وصدق العزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص651–652، تحت عنوان «براعة استعمال مفردة (اليمين) بمعنيين مرادين»","url":""}]},{"id":"s37-33","number":33,"surah":37,"verses":[99],"references":[{"surah":37,"verses":[99]}],"verseLabel":"الصافات: 99","question":"لماذا عبّر إبراهيم عن هجرته بقوله ﴿إِنِّي ذَاهِبٌ إِلَى رَبِّي﴾؟","answer":"لأن ذهابه لم يكن انتقال مكان فحسب، بل مفارقةً للشرك وتوجهًا إلى الله بالطاعة؛ فربط الهجرة بقصدها الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص667، تحت عنوان «دلالة التعبير بلفظ ﴿ذاهب﴾»","url":""}]},{"id":"s37-83","number":83,"surah":37,"verses":[99],"references":[{"surah":37,"verses":[99]}],"verseLabel":"الصافات: 99","question":"لماذا قال ﴿إِلَى رَبِّي﴾ ولم يقل «إلى الله»؟","answer":"عنوان الربوبية يناسب طلب الرعاية والهداية في الغربة، ويظهر ثقته بمن تولى تربيته وإحسانه وتدبير أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص668، تحت عنوان «بلاغة إيثار عنوان الربوبية على الألوهية»","url":""}]},{"id":"s37-34","number":34,"surah":37,"verses":[100],"references":[{"surah":37,"verses":[100]}],"verseLabel":"الصافات: 100","question":"لماذا قال إبراهيم ﴿رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ﴾ ولم يصرح بالولد؟","answer":"حذف المفعول اعتمادًا على وضوح المراد، وفيه أدب ورقة في الطلب؛ لم يتكلف التفصيل بل فوّض إلى ربه أن يهبه غلامًا صالحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص670، تحت عنوان «علة حذف مفعول فعل الهبة»","url":""}]},{"id":"s37-84","number":84,"surah":37,"verses":[100],"references":[{"surah":37,"verses":[100]}],"verseLabel":"الصافات: 100","question":"لماذا عبّر عن طلب الولد بلفظ ﴿هَبْ﴾؟","answer":"لأن الولد هبة محضة من الله لا تنالها القدرة البشرية وحدها؛ فاللفظ يعلن افتقاره ورجاءه في فضل ربه بلا استحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص671، تحت عنوان «بلاغة استعمال مفردة الهبة»","url":""}]},{"id":"s37-35","number":35,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قال الابن ﴿افْعَلْ مَا تُؤْمَرُ﴾ ولم يقل «اذبحني»؟","answer":"لإظهار امتثاله الكامل للوحي وتثبيت أبيه؛ أحال الفعل إلى أمر الله دون تصوير ألم الذبح، فجمع الأدب والشجاعة والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص683–684، تحت عنوان «بلاغة استعمال مفردة الفعل دون الذبح»","url":""}]},{"id":"s37-36","number":36,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"ماذا تفيد السين في قول الابن ﴿سَتَجِدُنِي﴾؟","answer":"تفيد وعدًا قريبًا واثقًا بأنه سيثبت عند التنفيذ، مع أدبٍ لا يزكي النفس لأنه علق ذلك بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص684–685، تحت عنوان «معنى السين في: ﴿ستجدني﴾»","url":""}]},{"id":"s37-85","number":85,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قدّم قوله ﴿إِنْ شَاءَ اللَّهُ﴾ قبل ﴿مِنَ الصَّابِرِينَ﴾؟","answer":"ليعلن أن الصبر لا يكون بقوة النفس وحدها، بل بتوفيق الله؛ فسبق الاستعانةُ دعوى القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص685، تحت عنوان «نكتة تقديم المشيئة»","url":""}]},{"id":"s37-86","number":86,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قال ﴿مِنَ الصَّابِرِينَ﴾ بالجمع؟","answer":"تواضع فلم يدع أنه الصابر الكامل منفردًا، بل سأل أن ينتظم في جماعة أهل الصبر؛ والجماعة أعون على الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص685، تحت عنوان «نكتة الجمع دون الإفراد»","url":""}]},{"id":"s37-37","number":37,"surah":37,"verses":[103],"references":[{"surah":37,"verses":[103]}],"verseLabel":"الصافات: 103","question":"لماذا قال ﴿فَلَمَّا أَسْلَمَا﴾ بضمير التثنية؟","answer":"لأن الامتحان قام على تسليم الأب والابن معًا: إبراهيم نفذ أمر ربه، والابن رضي وانقاد؛ فنجاح البلاء ثمرة موقفهما المشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص691، تحت عنوان «نكتة ذكر ضمير التثنية في ﴿أسلما﴾»","url":""}]},{"id":"s37-87","number":87,"surah":37,"verses":[103],"references":[{"surah":37,"verses":[103]}],"verseLabel":"الصافات: 103","question":"ما الصورة في قوله ﴿وَتَلَّهُ لِلْجَبِينِ﴾؟","answer":"﴿تله﴾ تصور إضجاعه بقوة وثبات، ووضع الجبين على الأرض يبرز كمال الخضوع ويبعد النظر إلى وجهه رحمةً به واستعدادًا للتنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص692، تحت عنوان «نكتة التعبير في قوله: ﴿وتله للجبين﴾»","url":""}]},{"id":"s37-38","number":38,"surah":37,"verses":[104,105],"references":[{"surah":37,"verses":[104,105]}],"verseLabel":"الصافات: 104-105","question":"كيف قيل لإبراهيم ﴿قَدْ صَدَّقْتَ الرُّؤْيَا﴾ مع أن الذبح لم يقع؟","answer":"لأنه حقق المقصود من الابتلاء: صدق العزم وباشر أسباب التنفيذ حتى لم يبق إلا إمرار السكين، فعدّ امتثاله تصديقًا تامًا للرؤيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص694–695، تحت عنوان «نكتة استعمال فعل التصديق وتأكيده بحرف التحقيق»","url":""}]},{"id":"s37-39","number":39,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"ماذا يفيد قوله ﴿وَفَدَيْنَاهُ﴾ وإسناد الفداء إلى ضمير العظمة؟","answer":"يبرز أن الله تولى الفداء بفضله، وأن الواقعة عظيمة متصلة بعنايته؛ فصار الفداء تشريفًا لإبراهيم وابنه وإبقاءً لذكرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص700، تحت عنوان «نكتة التعبير بجملة: ﴿وفديناه﴾ وإسناد الفعل لضمير العظمة»","url":""}]},{"id":"s37-88","number":88,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"لماذا نُكّر ﴿ذِبْحٍ﴾ في قوله ﴿بِذِبْحٍ عَظِيمٍ﴾؟","answer":"للتعظيم؛ أي بفداء جليل الشأن غير مألوف، قُدّم بدلًا من الابن في هذا الامتحان العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص701، تحت عنوان «نكتة تنكير لفظ (ذبح)»","url":""}]},{"id":"s37-89","number":89,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"لماذا وُصف الذبح بأنه ﴿عَظِيمٍ﴾؟","answer":"لعظمة الفداء والمفديّ به ومَن شرعه؛ فهو آية على رحمة الله وطاعة خليله، وبقي أثره سنةً في الأضاحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص701، تحت عنوان «نكتة وصف الذبح بـ﴿عظيم﴾»","url":""}]},{"id":"s37-40","number":40,"surah":37,"verses":[112],"references":[{"surah":37,"verses":[112]}],"verseLabel":"الصافات: 112","question":"لماذا جاءت البشارة بإسحاق موصوفًا بأنه ﴿نَبِيًّا﴾؟","answer":"لأنها ليست بشارة بولادته فقط، بل بمستقبله وعلو منزلته؛ سيكون نبيًا، فاجتمع لإبراهيم سرور الولد وشرف النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص715، تحت عنوان «دلالة موقع لفظ ﴿نبيًّا﴾»","url":""}]},{"id":"s37-90","number":90,"surah":37,"verses":[112],"references":[{"surah":37,"verses":[112]}],"verseLabel":"الصافات: 112","question":"ماذا تضيف عبارة ﴿مِنَ الصَّالِحِينَ﴾ بعد وصف إسحاق بالنبوة؟","answer":"تثبت أن النبوة اقترنت بصلاح السيرة والعمل، وهو مدح مستقل لا يغني عنه ذكر المنصب؛ فالصلاح كمال أخلاقي وعبادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص716، تحت عنوان «دلالة موقع: ﴿من الصالحين﴾»","url":""}]},{"id":"s37-41","number":41,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"ما غرض استفهام إلياس ﴿أَتَدْعُونَ بَعْلًا﴾؟","answer":"إنكار وتوبيخ على عبادة صنم عاجز وترك عبادة الله؛ فالاستفهام يوقظهم إلى قبح المفاضلة التي صنعوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص749، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s37-91","number":91,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"ما أثر الطباق بين ﴿تَدْعُونَ﴾ و﴿تَذَرُونَ﴾؟","answer":"يكشف المفارقة بحدة: أقبلوا على الباطل وتركوا الحق، فجمع الفعلان المتضادان انحرافهم في صورة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص751، تحت عنوان «بلاغة الطباق بين (تدعون) و(تذرون)»","url":""}]},{"id":"s37-92","number":92,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"لماذا وُصف الله بأنه ﴿أَحْسَنَ الْخَالِقِينَ﴾ في هذا المقام؟","answer":"لمقابلة الصنم المصنوع بالخالق الحق المتصف بأكمل الصفات؛ ففي الوصف تسفيه لمن ترك الأحسن وعبد ما صنعته الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص751، تحت عنوان «غرض وصف الله تعالى بـ﴿أحسن الخالقين﴾»","url":""}]},{"id":"s37-42","number":42,"surah":37,"verses":[139],"references":[{"surah":37,"verses":[139]}],"verseLabel":"الصافات: 139","question":"لماذا أكدت الآية رسالة يونس قبل ذكر إباقه؟","answer":"دفعًا لتوهم أن خطأه يبطل رسالته؛ أكدت أنه من المرسلين، فالنبوة ثابتة لا تفارقه، وما وقع كان اجتهادًا عوتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص793، تحت عنوان «نكتة تتابع المؤكدات في الآية»","url":""}]},{"id":"s37-93","number":93,"surah":37,"verses":[139],"references":[{"surah":37,"verses":[139]}],"verseLabel":"الصافات: 139","question":"لماذا عبّر عن ذهاب يونس إلى السفينة بقوله ﴿أَبَقَ﴾؟","answer":"شبّه خروجه قبل الإذن بإباق العبد من سيده، لا انتقاصًا من نبوته بل لتصوير شدة العتاب ووحشته حين فارق قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص794–795، تحت عنوان «دلالة التعبير بـ﴿أبق﴾ مادة وصيغة»","url":""}]},{"id":"s37-43","number":43,"surah":37,"verses":[141],"references":[{"surah":37,"verses":[141]}],"verseLabel":"الصافات: 141","question":"لماذا قيل ﴿فَسَاهَمَ﴾ في وصف القرعة؟","answer":"لأن ركاب السفينة اشتركوا فيها كل بسهم، فصيغة المشاركة تصور عدل الاقتراع وتكافؤهم فيه حتى خرج السهم على يونس.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص797، تحت عنوان «دلالة التعبير بـ﴿ساهم﴾ مادة وصيغة»","url":""}]},{"id":"s37-94","number":94,"surah":37,"verses":[141],"references":[{"surah":37,"verses":[141]}],"verseLabel":"الصافات: 141","question":"ما الصورة في وصف يونس بأنه ﴿مِنَ الْمُدْحَضِينَ﴾؟","answer":"تصوره مزلقًا مزاحًا من مكانه إلى البحر بعد غلبة سهمه؛ واستعير الإدحاض للخسران في القرعة وما ترتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص799، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿المدحضين﴾»","url":""}]},{"id":"s37-44","number":44,"surah":37,"verses":[143,144],"references":[{"surah":37,"verses":[143,144]}],"verseLabel":"الصافات: 143-144","question":"ماذا تفيد الشرطية ﴿فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ لَلَبِثَ فِي بَطْنِهِ﴾؟","answer":"تقرر أن تسبيحه كان سبب النجاة؛ فلولا ذكره وصلاته لبقي في بطن الحوت إلى البعث، فتظهر قيمة العبادة في زمن الرخاء والشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص802، تحت عنوان «بلاغة التعبير بالشرطية»","url":""}]},{"id":"s37-95","number":95,"surah":37,"verses":[143,144],"references":[{"surah":37,"verses":[143,144]}],"verseLabel":"الصافات: 143-144","question":"لماذا قيل ﴿مِنَ الْمُسَبِّحِينَ﴾ لا «مسبحًا»؟","answer":"ليدل على رسوخ التسبيح واستمراره وأنه واحد من جماعة عُرفوا به، لا أنه ذكر طارئ عند المحنة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص804، تحت عنوان «دلالة التعبير بـ﴿المسبحين﴾ مادة وصيغة»","url":""}]},{"id":"s37-45","number":45,"surah":37,"verses":[145],"references":[{"surah":37,"verses":[145]}],"verseLabel":"الصافات: 145","question":"لماذا قيل إن يونس نُبذ ﴿بِالْعَرَاءِ﴾؟","answer":"العراء أرض مكشوفة خالية من النبات والظل؛ فيصور انتقاله من ظلمات البحر إلى فضاء خالٍ وهو شديد الضعف، لتظهر عناية الله اللاحقة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص14–15، تحت عنوان «دلالة التعبير بلفظ العراء مادة وصيغة»","url":""}]},{"id":"s37-96","number":96,"surah":37,"verses":[145],"references":[{"surah":37,"verses":[145]}],"verseLabel":"الصافات: 145","question":"ما دلالة قوله ﴿وَأَنْبَتْنَا عَلَيْهِ شَجَرَةً مِنْ يَقْطِينٍ﴾ بعد نبذه سقيمًا؟","answer":"يعطف حال الرعاية على حال الضعف: أنبت الله عليه ما يظله ويلائمه سريعًا، فبرز التحول من الكرب والعراء إلى الرحمة والشفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص16، تحت عنوان «معنى الواو ودلالتها في قوله: ﴿وأنبتنا﴾»","url":""}]},{"id":"s37-46","number":46,"surah":37,"verses":[147],"references":[{"surah":37,"verses":[147]}],"verseLabel":"الصافات: 147","question":"ما أوجه دلالة ﴿أَوْ يَزِيدُونَ﴾ في قوله ﴿مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ﴾؟","answer":"تذكر الموسوعة أن ﴿أو﴾ قد تكون بمعنى الواو، أو للإضراب بمعنى بل، فتثبت الزيادة على المائة ألف. وقد تأتي على تقدير الرائي الذي يشاهد كثرتهم فيقول: مائة ألف أو يزيدون؛ فالتردد في هذا الوجه وصف لتقدير الناظر، لا لعلم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص21–22، تحت عنوان «معنى ﴿أو﴾ ودلالتها»","url":""}]},{"id":"s37-47","number":47,"surah":37,"verses":[149],"references":[{"surah":37,"verses":[149]}],"verseLabel":"الصافات: 149","question":"لماذا قيل ﴿لِرَبِّكَ﴾ في هذا الإنكار؟","answer":"إضافة الرب إلى النبي ﷺ تستحضر كمال الربوبية والعناية والخلق، فتجعل نسبة النقص إلى الرب الكامل أشد قبحًا وتناقضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص32، تحت عنوان «نكتة التعبير بلفظ الربوبية وإضافتها في ﴿ألربك﴾»","url":""}]},{"id":"s37-48","number":48,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"ماذا يفيد قول الملائكة ﴿إِلَّا لَهُ مَقَامٌ مَعْلُومٌ﴾؟","answer":"يفيد أن لكل ملك منزلة ووظيفة محددة لا يتجاوزها، فعبوديتهم منظمة خاضعة وليست لهم ألوهية كما زعم المشركون.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص81–82، تحت عنوان «بلاغة التعبير بالمقام»","url":""}]},{"id":"s37-97","number":97,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"لماذا وصف الملائكة أنفسهم بأنهم ﴿الصَّافُّونَ﴾؟","answer":"لأن الاصطفاف يصور اجتماعهم المنظم في العبادة والطاعة، ثابتين في مقاماتهم خاضعين لربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص84، تحت عنوان «بلاغة التعبير بمادة الاصطفاف»","url":""}]},{"id":"s37-98","number":98,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"لماذا قالوا ﴿وَإِنَّا لَنَحْنُ الْمُسَبِّحُونَ﴾؟","answer":"ليقرروا أنهم منزهون لله عابدون له، فيبطلوا قول من نسب إليهم البنوة أو جعلهم شركاء؛ فالتسبيح صفتهم لا الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص86، تحت عنوان «نكتة استعمال مادة التسبيح»","url":""}]},{"id":"s37-49","number":49,"surah":37,"verses":[171,172,173],"references":[{"surah":37,"verses":[171,172,173]}],"verseLabel":"الصافات: 171-173","question":"كيف يكون الرسل ﴿لَهُمُ الْمَنْصُورُونَ﴾ مع ما يصيبهم من أذى؟","answer":"النصر أوسع من السلامة العاجلة؛ هو ظهور الحجة وثبات الرسالة وحسن العاقبة، وقد يتأخر أو يأتي معنويًا، لكن كلمة الله لا تُغلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص106–107، تحت عنوان «دلالة استعمال مادة النصر»","url":""}]},{"id":"s37-99","number":99,"surah":37,"verses":[171,172,173],"references":[{"surah":37,"verses":[171,172,173]}],"verseLabel":"الصافات: 171-173","question":"لماذا قال ﴿وَإِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ﴾؟","answer":"الغلبة تشمل قهر الباطل وعلو الحجة وانتصار المؤمنين في المآل؛ وإضافتهم إلى الله تشريف وضمان بأن العاقبة لجنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص109، تحت عنوان «بلاغة استعمال مادة الغلبة»","url":""}]},{"id":"s37-50","number":50,"surah":37,"verses":[180,181,182],"references":[{"surah":37,"verses":[180,181,182]}],"verseLabel":"الصافات: 180-182","question":"ما سر ترتيب ختام السورة: تسبيح ثم سلام على المرسلين ثم حمد؟","answer":"بدأ بتنزيه الله عما نسبه المشركون إليه، ثم نزّه رسله وسلّم عليهم، ثم ختم بالحمد الجامع لكل كمال؛ فانتظم الختام من دفع النقص إلى الثناء التام.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص131، تحت عنوان «براعة الترتيب بالعطف»","url":""}]},{"id":"s37-100","number":100,"surah":37,"verses":[180,181,182],"references":[{"surah":37,"verses":[180,181,182]}],"verseLabel":"الصافات: 180-182","question":"لماذا ختمت سورة الصافات بالحمد؟","answer":"لأن الحمد يجمع الثناء على الله بعد تنزيهه ونصر رسله، ويؤذن بأن العاقبة المحمودة للحق وأهله؛ فوافق مطلع التوحيد خاتمة التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص136، تحت عنوان «براعة اختتام السورة بالحمد»","url":""}]},{"id":"s38-1","number":1,"surah":38,"verses":[1],"references":[{"surah":38,"verses":[1]}],"verseLabel":"ص: 1","question":"ما دلالة افتتاح السورة بحرف ﴿ص﴾؟","answer":"توجه الموسوعة هذا الافتتاح على أنه من الحروف المقطعة الدالة على إعجاز القرآن؛ فهو مركب من الحروف التي يعرفونها ويؤلفون منها كلامهم، ثم يعجزون عن الإتيان بمثله. فيهيئ الحرف للقسم بالقرآن ويستدعي الإصغاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص146–147، تحت عنوان «سر الافتتاح بالحرف: ﴿ص﴾»","url":""}]},{"id":"s38-2","number":2,"surah":38,"verses":[1],"references":[{"surah":38,"verses":[1]}],"verseLabel":"ص: 1","question":"ما الذي يضيفه وصف القرآن بأنه ﴿ذِي الذِّكْرِ﴾؟","answer":"يصفه بأنه صاحب الشرف والبيان والتذكير والموعظة؛ فهو كتاب يوقظ القلوب ويبين لها ما ينفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص148، تحت عنوان «دلالة وصف المقسم به بوصف: ﴿ذِي الذِّكْرِ﴾»","url":""}]},{"id":"s38-3","number":3,"surah":38,"verses":[2],"references":[{"surah":38,"verses":[2]}],"verseLabel":"ص: 2","question":"ماذا تفيد ﴿بَلْ﴾ في قوله: ﴿بَلِ الَّذِينَ كَفَرُوا فِي عِزَّةٍ وَشِقَاقٍ﴾؟","answer":"تنقل الكلام من إثبات شأن القرآن إلى كشف سبب الإعراض عنه: ليس في القرآن ما يوجب الشك، وإنما منعهم الكبر ومشاقة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص151–152، تحت عنوان «الغرض من التعبير باسم الموصول»","url":""}]},{"id":"s38-60","number":60,"surah":38,"verses":[2],"references":[{"surah":38,"verses":[2]}],"verseLabel":"ص: 2","question":"لماذا جُمعت ﴿عِزَّةٍ﴾ و﴿شِقَاقٍ﴾؟","answer":"لأن استكبارهم الباطن أورثهم المخالفة الظاهرة؛ فالعزة بالإثم سبب، والشقاق أثرها في معاداة الرسول والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص153، تحت عنوان «دلالة عطف: (شقاق) على: ﴿عِزَّةٍ﴾»","url":""}]},{"id":"s38-4","number":4,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"ماذا يصور قوله عن الهالكين: ﴿فَنَادَوْا﴾؟","answer":"تصور الفاء مبادرتهم إلى الصراخ والاستغاثة فور نزول العذاب، لكن النداء جاء بعدما فات زمن النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص159، تحت عنوان «معنى الفاء ودلالتها في ﴿فَنَادَوْا﴾»","url":""}]},{"id":"s38-61","number":61,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"لماذا لم يذكر القرآن مَن ناداه الهالكون ولا ما طلبوه؟","answer":"ليعم كل ما يمكن أن يصدر عن المذعور من استغاثة وطلب نجاة؛ فالحذف يترك صرختهم مفتوحة على شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص160، تحت عنوان «بلاغة حذف معمول فعل النداء»","url":""}]},{"id":"s38-62","number":62,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"ما دلالة التعبير بـ﴿وَلَاتَ حِينَ مَنَاصٍ﴾؟","answer":"ينفي إمكان الفرار أو النجاة في ذلك الوقت خاصة؛ فقد جاء الندم والاستغاثة بعد انقضاء المهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص161، تحت عنوان «دلالة النفي بـ: (لات)»","url":""}]},{"id":"s38-5","number":5,"surah":38,"verses":[4],"references":[{"surah":38,"verses":[4]}],"verseLabel":"ص: 4","question":"لماذا عبّر عن موقف المشركين بقوله: ﴿وَعَجِبُوا﴾؟","answer":"ليكشف أنهم جعلوا أمرًا لا موجب للعجب منه موضع استغراب: أن يختار الله رسولًا من البشر؛ فالتعبير يفضح فساد معيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص163–164، تحت عنوان «دلالة التعبير بالفعل: (عجبوا)»","url":""}]},{"id":"s38-6","number":6,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"ما غرض الاستفهام في قولهم: ﴿أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا﴾؟","answer":"هو الإنكار المشوب بالتعجب؛ استبعدوا التوحيد لأنهم ألفوا كثرة المعبودات، لا لأن حجته خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص171، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أَجَعَلَ﴾»","url":""}]},{"id":"s38-63","number":63,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"لماذا عبّروا عن التوحيد بفعل ﴿جَعَلَ﴾؟","answer":"صوروه كأنه تحويل للآلهة الكثيرة إلى إله واحد، مع أن الدعوة تكشف بطلان ألوهيتها ولا تحول ذواتها؛ وفي ذلك أثر تصورهم الفاسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص171–172، تحت عنوان «دلالة التعبير بالفعل: (جعل)»","url":""}]},{"id":"s38-64","number":64,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"لماذا نسبوا هذا «الجعل» إلى الرسول ﷺ؟","answer":"ليوهموا أن التوحيد شيء ابتدعه الرسول من عنده، مع أنه مبلغ عن الله؛ فالإسناد يكشف تعمدهم صرف الناس عن أصل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص172، تحت عنوان «دلالة إسناد فعل الجعل إلى ضمير الرسول»","url":""}]},{"id":"s38-7","number":7,"surah":38,"verses":[6],"references":[{"surah":38,"verses":[6]}],"verseLabel":"ص: 6","question":"ماذا أراد الملأ بقولهم: ﴿امْشُوا﴾؟","answer":"أرادوا حث قومهم على المضي في عبادتهم أو الانصراف عن مجلس الدعوة، فجاء الأمر تحريضًا على الثبات في الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص178، تحت عنوان «الغرض من التعبير بالأمر: ﴿امْشُوا﴾»","url":""}]},{"id":"s38-65","number":65,"surah":38,"verses":[6],"references":[{"surah":38,"verses":[6]}],"verseLabel":"ص: 6","question":"لماذا قالوا: ﴿وَاصْبِرُوا عَلَى آلِهَتِكُمْ﴾؟","answer":"جعلوا التمسك بالأصنام صبرًا يحتاج إلى احتمال، ليشدوا أتباعهم أمام تأثير دعوة التوحيد؛ فقلبوا الصبر من نصرة الحق إلى حماية الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص178–179، تحت عنوان «دلالة عطف الأمر بالصبر»","url":""}]},{"id":"s38-8","number":8,"surah":38,"verses":[7],"references":[{"surah":38,"verses":[7]}],"verseLabel":"ص: 7","question":"لماذا احتجوا بقولهم: ﴿مَا سَمِعْنَا بِهَذَا﴾؟","answer":"جعلوا حدود ما ألفوه وسمعوه معيارًا للحق، فكأن عدم سماعهم بالتوحيد من قبل دليل على بطلانه؛ وهو احتجاج بالتقليد لا بالحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص183–184، تحت عنوان «دلالة نفي فعل السمع دون غيره»","url":""}]},{"id":"s38-66","number":66,"surah":38,"verses":[7],"references":[{"surah":38,"verses":[7]}],"verseLabel":"ص: 7","question":"ما دلالة تقييد نفي السماع بقولهم: ﴿فِي الْمِلَّةِ الْآخِرَةِ﴾؟","answer":"قيدوا معرفتهم بدين متأخر أدركوه أو بدين آبائهم الأقربين، ليصوروا دعوة التوحيد خروجًا عما استقر في محيطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص185، تحت عنوان «سر تقييد نفي السماع بالجار والمجرور»","url":""}]},{"id":"s38-9","number":9,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"ما غرض الاستفهام في قولهم: ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنَا﴾؟","answer":"هو إنكار حسدٍ لا طلب جواب؛ استبعدوا أن يختص الرسول ﷺ بالوحي لأنهم قاسوا الاصطفاء بمكانتهم الدنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص190–191، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أَأُنْزِلَ﴾»","url":""}]},{"id":"s38-67","number":67,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"لماذا قُدّم ﴿عَلَيْهِ﴾ في قولهم: ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ﴾؟","answer":"لإبراز الشخص الذي اعترضوا على اختصاصه بالوحي؛ فموضع إنكارهم لم يكن الذكر نفسه بقدر ما كان نزوله عليه دونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص191–192، تحت عنوان «دلالة تقديم الجار والمجرور على نائب الفاعل»","url":""}]},{"id":"s38-10","number":10,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"لماذا تتابعت ﴿بَلْ﴾ في الرد على منكري الوحي؟","answer":"لأن كل واحدة تنقل إلى سبب أعمق من سابقه: من حسدهم للرسول إلى شكهم في الوحي، ثم إلى أنهم لم يذوقوا العذاب الذي سيزيل شكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص195، تحت عنوان «سر تتابع الإضراب في قوله: ﴿بَلْ لَمَّا﴾»","url":""}]},{"id":"s38-11","number":11,"surah":38,"verses":[9],"references":[{"surah":38,"verses":[9]}],"verseLabel":"ص: 9","question":"ما غرض السؤال: ﴿أَمْ عِنْدَهُمْ خَزَائِنُ رَحْمَةِ رَبِّكَ﴾؟","answer":"إنكار أن تكون خزائن الرحمة في ملكهم حتى يمنحوا النبوة من شاءوا ويمنعوها عمن شاءوا؛ فالاختيار لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص199، تحت عنوان «معنى ﴿أَمْ﴾ ودلالتها في أول الآية»","url":""}]},{"id":"s38-12","number":12,"surah":38,"verses":[10],"references":[{"surah":38,"verses":[10]}],"verseLabel":"ص: 10","question":"ما غرض الأمر في قوله: ﴿فَلْيَرْتَقُوا فِي الْأَسْبَابِ﴾؟","answer":"هو التعجيز والتهكم: إن زعموا أنهم يملكون تدبير الوحي فليصعدوا في طرق السماوات ويتولوا قسمته؛ وعجزهم يفضح دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص203–204، تحت عنوان «الغرض من التعبير بالمضارع المقترن بلام الأمر»","url":""}]},{"id":"s38-13","number":13,"surah":38,"verses":[11],"references":[{"surah":38,"verses":[11]}],"verseLabel":"ص: 11","question":"ماذا تفيد ﴿مَا﴾ في قوله: ﴿جُنْدٌ مَا هُنَالِكَ مَهْزُومٌ﴾؟","answer":"تحتمل تحقير جمعهم أو إبهامه، وحتى على معنى التعظيم فالمحصلة أن أي جند يجمعونه حقير المصير أمام أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص208، تحت عنوان «معنى ﴿مَا﴾ ودلالتها»","url":""}]},{"id":"s38-68","number":68,"surah":38,"verses":[11],"references":[{"surah":38,"verses":[11]}],"verseLabel":"ص: 11","question":"لماذا وصف جند المشركين بـ﴿مَهْزُومٌ﴾ قبل وقوع الهزيمة؟","answer":"استعمل اسم المفعول للمستقبل المحقق كأنه واقع حاضر، تثبيتًا للرسول ﷺ ووعدًا بأن هذا الجمع سيُكسر لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص210، تحت عنوان «دلالة المجاز في التعبير باسم المفعول»","url":""}]},{"id":"s38-14","number":14,"surah":38,"verses":[12],"references":[{"surah":38,"verses":[12]},{"surah":89,"verses":[10]}],"verseLabel":"ص: 12؛ الفجر: 10","question":"لماذا وُصف فرعون بأنه ﴿ذُو الْأَوْتَادِ﴾؟","answer":"لأن الأوتاد توحي بسلطان ثابت كثير الجند والخيام، وقيل هي أدوات تعذيبه؛ وعلى الوجهين ترسم قوة دنيوية لم تمنع عنه الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص216–217، تحت عنوان «دلالة وصف (فرعون) بـ﴿ذُو الْأَوْتَادِ﴾، وسر إضافته»","url":""}]},{"id":"s38-15","number":15,"surah":38,"verses":[13],"references":[{"surah":38,"verses":[13]}],"verseLabel":"ص: 13","question":"لماذا قيل عن الأمم المكذبة: ﴿أُولَئِكَ الْأَحْزَابُ﴾؟","answer":"قصر حقيقة التحزب فيهم؛ فهم الذين تجمعوا على مخالفة الرسل، فصار مشركو مكة حزبًا صغيرًا ملحقًا بأحزاب انتهت إلى الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص219–220، تحت عنوان «الغرض من التعبير بأسلوب القصر»","url":""}]},{"id":"s38-16","number":16,"surah":38,"verses":[15],"references":[{"surah":38,"verses":[15]}],"verseLabel":"ص: 15","question":"لماذا وُصفت الصيحة بأنها ﴿وَاحِدَةً﴾؟","answer":"لتأكيد أن إهلاكهم لا يحتاج تكرارًا ولا معالجة؛ صيحة واحدة تكفي لإنهاء جمعهم مهما بلغت قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص229، تحت عنوان «سر تقييد المفعول بـ: ﴿وَاحِدَةً﴾»","url":""}]},{"id":"s38-69","number":69,"surah":38,"verses":[15],"references":[{"surah":38,"verses":[15]}],"verseLabel":"ص: 15","question":"ماذا تفيد الجملة الاسمية: ﴿مَا لَهَا مِنْ فَوَاقٍ﴾؟","answer":"تفيد ثبات انتفاء الإفاقة أو الرجوع أو المهلة عنها؛ فإذا جاءت الصيحة لم تتوقف ولم تترك فرصة للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص229–230، تحت عنوان «دلالة وصف الصيحة بالجملة الاسمية»","url":""}]},{"id":"s38-17","number":17,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"ما غرض قولهم: ﴿رَبَّنَا عَجِّلْ لَنَا﴾؟","answer":"قالوه استهزاءً وتكذيبًا، فطلبوا تقديم نصيبهم من العذاب بدل أن يخافوه؛ وفي الأمر كشف لجهلهم وجرأتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص234، تحت عنوان «الغرض من التعبير بفعل الأمر: ﴿عَجِّلْ﴾»","url":""}]},{"id":"s38-70","number":70,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"لماذا سموا نصيبهم من العذاب ﴿قِطَّنَا﴾؟","answer":"القط هو النصيب أو الصك المكتوب، فاستعاروه ساخرين لما وُعدوا به كأنهم يطلبون وثيقة نصيبهم عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص235، تحت عنوان «دلالة التعبير بالـ(قط)، والغرض من إضافته»","url":""}]},{"id":"s38-71","number":71,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"لماذا قالوا: ﴿قَبْلَ يَوْمِ الْحِسَابِ﴾؟","answer":"زادوا في الاستهزاء بطلب العذاب قبل وقته، وسمّوا الآخرة يوم الحساب مع أن الحساب نفسه مما كانوا ينكرونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص235، تحت عنوان «الغرض من التعبير عن الآخرة بـ﴿يَوْمِ الْحِسَابِ﴾»","url":""}]},{"id":"s38-18","number":18,"surah":38,"verses":[17],"references":[{"surah":38,"verses":[17]}],"verseLabel":"ص: 17","question":"لماذا وُصف داود عليه السلام بأنه ﴿ذَا الْأَيْدِ﴾؟","answer":"هي كناية عن القوة في الطاعة والعبادة وتدبير الملك، لا مجرد قوة البدن؛ فاستحضار ثباته يعين الرسول ﷺ على الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص243، تحت عنوان «بيان المراد بالكناية ﴿ذَا الْأَيْدِ﴾»","url":""}]},{"id":"s38-19","number":19,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"ماذا يصور المضارع في قوله عن الجبال: ﴿يُسَبِّحْنَ﴾؟","answer":"يستحضر تسبيح الجبال مع داود كأنه مشهد يتجدد أمام السامع، فيبرز دوام العبادة وتكرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص249، تحت عنوان «دلالة الجملة الفعلية المضارعية»","url":""}]},{"id":"s38-72","number":72,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"ما دلالة الجمع بين ﴿بِالْعَشِيِّ وَالْإِشْرَاقِ﴾؟","answer":"يجمع طرفي النهار ليدل على استمرار التسبيح وتجدد العبادة من أوله إلى آخره، لا على لحظتين معزولتين فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص251، تحت عنوان «بلاغة الطباق بين أول النهار وآخره»","url":""}]},{"id":"s38-73","number":73,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"لماذا قيل: ﴿وَالطَّيْرَ مَحْشُورَةً﴾ بدل أن يقال: والطير تحشر؟","answer":"لإبراز هيئة الطير مجتمعة مسخرة حول داود، وكأن حشرها حال ثابتة مشاهدة تشارك فيها الجبال تسبيحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص253، تحت عنوان «سر العدول عن الجملة الحالية»","url":""}]},{"id":"s38-20","number":20,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ما الصورة في قوله عن داود: ﴿وَشَدَدْنَا مُلْكَهُ﴾؟","answer":"شُبه الملك ببناء يُشد ويوثق حتى لا يتزعزع؛ فالتعبير يصور ما أمده الله به من قوة وهيبة وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص260، تحت عنوان «دلالة الاستعارة في ﴿وَشَدَدْنَا مُلْكَهُ﴾»","url":""}]},{"id":"s38-74","number":74,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ماذا يفيد تعريف ﴿الْحِكْمَةَ﴾ في قوله: ﴿وَآتَيْنَاهُ الْحِكْمَةَ﴾؟","answer":"يفيد كمال الحكمة المعروفة الجامعة للنبوة والعلم وإتقان القول والعمل، لا قدرًا مبهمًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص261، تحت عنوان «دلالة التعريف لـ﴿الْحِكْمَةَ﴾»","url":""}]},{"id":"s38-75","number":75,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ما دلالة التعبير بـ﴿فَصْلَ الْخِطَابِ﴾؟","answer":"يدل على القدرة على تمييز الحق من الباطل وإنهاء الخصومة بكلام واضح حاسم؛ فالإضافة تجمع حسن البيان وصواب الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص262، تحت عنوان «دلالة إضافة المصدر ﴿وَفَصْلَ﴾»","url":""}]},{"id":"s38-21","number":21,"surah":38,"verses":[21],"references":[{"surah":38,"verses":[21]}],"verseLabel":"ص: 21","question":"لماذا قيل عن الخصمين: ﴿تَسَوَّرُوا الْمِحْرَابَ﴾؟","answer":"هي كناية عن دخولهم من أعلى السور على غير الطريق المعتاد؛ فتوجز هيئة مفاجئة تفسر فزع داود منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص271، تحت عنوان «بلاغة الكناية في ﴿تَسَوَّرُوا الْمِحْرَابَ﴾»","url":""}]},{"id":"s38-22","number":22,"surah":38,"verses":[22],"references":[{"surah":38,"verses":[22]}],"verseLabel":"ص: 22","question":"لماذا بادر الخصمان داود بقولهم: ﴿لَا تَخَفْ﴾؟","answer":"لأن دخولهما المفاجئ من غير الباب أفزعه، فبدآ بإزالة الخوف قبل عرض القضية حتى يطمئن ويسمع حجتهما؛ وفي النهي إيناس وتهيئة للمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص277، تحت عنوان «دلالة النهي في ﴿لا تخف﴾»","url":""}]},{"id":"s38-23","number":23,"surah":38,"verses":[23],"references":[{"surah":38,"verses":[23]}],"verseLabel":"ص: 23","question":"ما الصورة في قول صاحب النعجة: ﴿وَعَزَّنِي فِي الْخِطَابِ﴾؟","answer":"جعل الخطاب ميدانًا تقع فيه الغلبة، كأن المتخاصمين يتباريان فيه فيقوى أحدهما بالحجة أو الفصاحة أو الجاه؛ وتوجز العبارة شدة ضغط خصمه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص290، تحت عنوان «سر جعل الخطاب ظرفًا للعزة والغلبة»","url":""}]},{"id":"s38-24","number":24,"surah":38,"verses":[24],"references":[{"surah":38,"verses":[24]}],"verseLabel":"ص: 24","question":"ماذا يكشف تتابع ﴿فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ﴾؟","answer":"يكشف سرعة داود إلى تصحيح الموقف: استغفار بالقلب واللسان، وخضوع بالجسد، ثم رجوع كامل إلى الله؛ فترتيب الأفعال يصور توبة شاملة عاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص305، تحت عنوان «دلالة العطف في قوله: ﴿فاستغفر ربه وخر راكعًا وأناب﴾»","url":""}]},{"id":"s38-25","number":25,"surah":38,"verses":[25],"references":[{"surah":38,"verses":[25]}],"verseLabel":"ص: 25","question":"لماذا أعقب الله مغفرة داود بقوله: ﴿وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى وَحُسْنَ مَآبٍ﴾؟","answer":"ليبين أن المغفرة لم تكن مجرد ستر للذنب، بل أعقبها قرب وكرامة وحسن مرجع؛ فالتوبة رفعت مقامه ولم تنقصه، وجاءت المؤكدات لرد كل توهم بخلاف ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص311، تحت عنوان «دلالة وصل ﴿وإن له عندنا لزلفى﴾»","url":""}]},{"id":"s38-26","number":26,"surah":38,"verses":[26],"references":[{"surah":38,"verses":[26]}],"verseLabel":"ص: 26","question":"لماذا قابلت الآية بين الحكم بالحق واتباع الهوى؟","answer":"لأن الحق ميزان ثابت يوصل إلى حكم الله، أما الهوى فميل شخصي يصد عن سبيله؛ فالمقابلة تقرر أن القاضي لا يجمع بينهما، وأن أول واجب للاستخلاف مقاومة الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص323، تحت عنوان «دلالة التقابل بين الحق والهوى»","url":""}]},{"id":"s38-27","number":27,"surah":38,"verses":[27],"references":[{"surah":38,"verses":[27]}],"verseLabel":"ص: 27","question":"ما الذي ينفيه قوله: ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا﴾؟","answer":"ينفي أن يكون الخلق عبثًا بلا حكمة ولا حساب؛ فهذا النظام المقصود يقتضي تمييز المحسن من المسيء وبعث الخلق للجزاء، وإلا استوى الحق والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص335، تحت عنوان «دلالة لفظ ﴿باطلًا﴾»","url":""}]},{"id":"s38-28","number":28,"surah":38,"verses":[28],"references":[{"surah":38,"verses":[28]}],"verseLabel":"ص: 28","question":"ما غرض السؤال: ﴿أَمْ نَجْعَلُ الَّذِينَ آمَنُوا... كَالْمُفْسِدِينَ فِي الْأَرْضِ﴾؟","answer":"هو إنكار شديد لاستواء الفريقين؛ فعدل الله وحكمة الخلق يأبيان أن تكون عاقبة المؤمن المصلح كعاقبة المفسد، وبذلك يقيم السؤال دليلًا على الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص343، تحت عنوان «توجيه العطف بـ﴿أم﴾»","url":""}]},{"id":"s38-29","number":29,"surah":38,"verses":[29],"references":[{"surah":38,"verses":[29]}],"verseLabel":"ص: 29","question":"لماذا وُصف القرآن بأنه ﴿كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ﴾؟","answer":"لأن خيره كثير دائم متجدد: يهدي ويصلح القلوب والأعمال، وتتولد من تدبر آياته معانٍ وهدايات لا تنفد؛ فبركته في أثره وفي عطائه المتواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص358، تحت عنوان «وجه وصف القرآن بـ﴿مبارك﴾»","url":""}]},{"id":"s38-30","number":30,"surah":38,"verses":[30],"references":[{"surah":38,"verses":[30]}],"verseLabel":"ص: 30","question":"لماذا خُص سليمان بالثناء: ﴿إِنَّهُ أَوَّابٌ﴾؟","answer":"لأن ﴿أواب﴾ صيغة مبالغة تدل على كثرة رجوعه إلى الله في كل شأن؛ فليست الإنابة موقفًا عابرًا بل صفة راسخة تفسر استحقاقه المدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص370، تحت عنوان «سر التعبير بصيغة المبالغة ﴿أواب﴾»","url":""}]},{"id":"s38-31","number":31,"surah":38,"verses":[31],"references":[{"surah":38,"verses":[31]}],"verseLabel":"ص: 31","question":"ما دلالة الجمع بين وصف الخيل بـ﴿الصَّافِنَاتُ الْجِيَادُ﴾؟","answer":"جمع لها جمال الوقوف وقوة العدو: تصفن في سكونها هيئةً وأصالة، وتجود بالسرعة عند جريها؛ فاستوعب الوصفان محاسن الخيل في حالتي السكون والحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص378، تحت عنوان «دلالة الجمع بين الوصفين»","url":""}]},{"id":"s38-32","number":32,"surah":38,"verses":[32],"references":[{"surah":38,"verses":[32]}],"verseLabel":"ص: 32","question":"لماذا عبّر سليمان عن الصلاة بـ﴿ذِكْرِ رَبِّي﴾؟","answer":"لأن الصلاة أعظم صور الذكر، ولأن اللفظ يعم ما يتصل بذكر الله من عبادة ووحي؛ فالتعبير يكشف أن القضية ليست حركةً فاتته بل صلةً بربه يحرص عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص386، تحت عنوان «وجه التعبير بلفظ ﴿ذكر﴾»","url":""}]},{"id":"s38-33","number":33,"surah":38,"verses":[34],"references":[{"surah":38,"verses":[34]}],"verseLabel":"ص: 34","question":"ماذا يفيد قوله بعد فتنة سليمان: ﴿ثُمَّ أَنَابَ﴾؟","answer":"يفيد أن الفتنة انتهت برجوعه الكامل إلى الله، وأن الإنابة جاءت بعد إدراك ما في الابتلاء؛ و﴿ثم﴾ تصور انتقالًا من المحنة إلى حال جديدة من التوبة والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص403–404، تحت عنوان «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s38-34","number":34,"surah":38,"verses":[35],"references":[{"surah":38,"verses":[35]}],"verseLabel":"ص: 35","question":"لماذا قدّم سليمان طلب المغفرة على سؤال الملك العظيم؟","answer":"لأن تطهير النفس وإصلاح الصلة بالله مقدمان على طلب حظوظ الدنيا، ولأن المغفرة تهيئ الدعاء للقبول؛ فبدأ بحاجة الدين قبل عطية الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص409، تحت عنوان «علة تقديم الاستغفار على استيهاب الملك»","url":""}]},{"id":"s38-35","number":35,"surah":38,"verses":[36],"references":[{"surah":38,"verses":[36]}],"verseLabel":"ص: 36","question":"لماذا وُصفت الريح المسخرة لسليمان بأنها ﴿رُخَاءً﴾؟","answer":"لأن تسخيرها جمع القوة واللين: تجري بأمره حيث يريد، لكنها رخية طيبة لا تؤذيه ولا تعصف به؛ فكانت طائعة نافعة لا مجرد ريح شديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص422–423، تحت عنوان «سر وصف الريح بكونها ﴿رخاء﴾»","url":""}]},{"id":"s38-36","number":36,"surah":38,"verses":[38],"references":[{"surah":38,"verses":[38]}],"verseLabel":"ص: 38","question":"ما الصورة في قوله عن الشياطين: ﴿مُقَرَّنِينَ فِي الْأَصْفَادِ﴾؟","answer":"تصور المردة وقد شُد بعضهم إلى بعض في القيود، أو جُمعت أيديهم إلى أعناقهم؛ فالتضعيف في ﴿مقرنين﴾ والأصفاد يصوران إحكام أسر قوتهم وإذلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص428–429، تحت عنوان «سر إيثار صيغة ﴿مقرنين﴾ بالتضعيف»","url":""}]},{"id":"s38-37","number":37,"surah":38,"verses":[39],"references":[{"surah":38,"verses":[39]}],"verseLabel":"ص: 39","question":"ما دلالة قوله لسليمان: ﴿فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ﴾؟","answer":"هو كناية عن سعة التفويض وتمام الثقة: أعط من تشاء أو امنع من تشاء، فلا تضييق عليك في هذا العطاء ولا مؤاخذة على وجوه تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص437، تحت عنوان «الكناية في نفي الحساب»","url":""}]},{"id":"s38-38","number":38,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"لماذا نسب أيوب ما مسه إلى الشيطان؟","answer":"تأدبًا مع الله فلم ينسب إليه النصب والعذاب، وذكر الشيطان بوصفه سببًا للوسوسة والشماتة أو لما أذن الله أن يقع؛ مع يقينه أن الشفاء والضر بيد الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص450–451، تحت عنوان «سر نسبة المس إلى ﴿الشيطان﴾»","url":""}]},{"id":"s38-39","number":39,"surah":38,"verses":[42],"references":[{"surah":38,"verses":[42]}],"verseLabel":"ص: 42","question":"ما دلالة أمر أيوب: ﴿ارْكُضْ بِرِجْلِكَ﴾ مع أن الله قادر على شفائه بلا حركة؟","answer":"ليباشر سبب الشفاء بنفسه ويظهر صدق امتثاله، مع أن الركضة وحدها لا تخرج ماءً؛ فاجتمع الأخذ بالسبب وإظهار أن أثره من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص455، تحت عنوان «دلالة الأمر ﴿اركض﴾»","url":""}]},{"id":"s38-40","number":40,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة قوله في نعمة أيوب: ﴿رَحْمَةً مِنَّا﴾؟","answer":"يدل على أن رد أهله ومثلهم معهم فضل صادر من الله وحده، لا استحقاقًا ولا مقابلًا؛ والإضافة إلى ضمير العظمة تفخم الرحمة وتبرز قرب العناية بأيوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص469–470، تحت عنوان «نكتة ذكر ﴿منا﴾»","url":""}]},{"id":"s38-41","number":41,"surah":38,"verses":[44],"references":[{"surah":38,"verses":[44]}],"verseLabel":"ص: 44","question":"لماذا أُمر أيوب أن يضرب بالضغث وفاءً بيمينه؟","answer":"لأن الضغث حزمة من عيدان دقيقة تجمع العدد في ضربة رفيقة؛ فحقق ظاهر يمينه من غير إيذاء زوجته الصابرة، وجمع الحكم بين الوفاء والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص475–476، تحت عنوان «بلاغة اختيار مفردة الضغث»","url":""}]},{"id":"s38-42","number":42,"surah":38,"verses":[45],"references":[{"surah":38,"verses":[45]}],"verseLabel":"ص: 45","question":"ما دلالة وصف إبراهيم وإسحاق ويعقوب بـ﴿أولي الأيدي والأبصار﴾؟","answer":"تستعار الأيدي للقوة في الطاعة والعمل، والأبصار للبصيرة في الدين والعلم. فيجمع الوصف كمال القدرة وكمال الإدراك، ويشير إلى أن جوارحهم وقواهم متجهة إلى المقاصد التي خلقوا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص486، تحت عنوان «بلاغة التعبير المجازي»","url":""}]},{"id":"s38-43","number":43,"surah":38,"verses":[46],"references":[{"surah":38,"verses":[46]}],"verseLabel":"ص: 46","question":"لماذا قال الله عن إبراهيم وإسحاق ويعقوب: ﴿إِنَّا أَخْلَصْنَاهُمْ﴾؟","answer":"لأن الله اصطفاهم ونقّاهم من الشوائب والعيوب، فجعل إخلاصهم وصفًا راسخًا وهيأهم للنبوة والاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص488، تحت عنوان «بلاغة اختيار مفردة ﴿أخلصناهم﴾»","url":""}]},{"id":"s38-76","number":76,"surah":38,"verses":[46],"references":[{"surah":38,"verses":[46]}],"verseLabel":"ص: 46","question":"ما دلالة إضافة ﴿ذِكْرَى﴾ إلى ﴿الدَّارِ﴾؟","answer":"تجعل تذكّر الآخرة وتذكير الناس بها خصلةً راسخة فيهم؛ فاستحقوا المنزلة الرفيعة لأنهم وجّهوا القلوب إلى الدار الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص490–491، تحت عنوان «دلالة إضافة ﴿ذكرى﴾ للفظ ﴿الدار﴾»","url":""}]},{"id":"s38-44","number":44,"surah":38,"verses":[49],"references":[{"surah":38,"verses":[49]}],"verseLabel":"ص: 49","question":"لماذا جاء بعد قصص الأنبياء قوله: ﴿هَذَا ذِكْرٌ﴾؟","answer":"ليطوي ما سبق في جملة تذكير وعبرة، ثم ينقل السامع إلى جزاء المتقين؛ فكانت العبارة فاصلة تحفظ صلة الغرضين من غير إطالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص506–507، تحت عنوان «بلاغة فصل الخطاب أو الانتقال الاقتضابي»","url":""}]},{"id":"s38-77","number":77,"surah":38,"verses":[49],"references":[{"surah":38,"verses":[49]}],"verseLabel":"ص: 49","question":"لماذا اختيرت كلمة ﴿ذِكْرٌ﴾ في قوله: ﴿هَذَا ذِكْرٌ﴾؟","answer":"لأنها تجمع التذكير والاعتبار، وشرف الأنبياء المذكورين، والقرآن الذي حفظ خبرهم؛ فلفظ واحد يستوعب هذه المعاني المتآزرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص508، تحت عنوان «بلاغة استعمال مفردة ﴿ذكر﴾ دون رديفاتها»","url":""}]},{"id":"s38-45","number":45,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"ماذا تصوّر صيغة ﴿مُفَتَّحَةً﴾ في أبواب الجنة؟","answer":"تصوّر كثرة الأبواب ويسر فتحها، وأنها مهيأة على الدوام لاستقبال أهل الجنة بالإكرام والترحيب من غير عناء ولا انتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص514، تحت عنوان «فائدة صيغة المبالغة ﴿مفتحة﴾»","url":""}]},{"id":"s38-78","number":78,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"لماذا قُدّم ﴿لَهُمُ﴾ في قوله: ﴿مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"لإبراز أن هذا الفتح خاص بالمتقين تكريمًا واحتفاءً بهم، وكأن أبواب الجنة فُتحت لهم قبل وصولهم انتظارًا لقدومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص515، تحت عنوان «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s38-79","number":79,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"لماذا لم يُذكر دخول المتقين الجنة بعد قوله: ﴿مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"لأن فتح الأبواب لهم كناية تكفي عن الإذن بالدخول والتمكين من النعيم؛ وطيّ الحدث يسرّع المشهد ويترك النفس تتشوق لما وراء الأبواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص516، تحت عنوان «بلاغة الكناية في طيّ حديث دخول الجنات»","url":""}]},{"id":"s38-46","number":46,"surah":38,"verses":[55],"references":[{"surah":38,"verses":[55]}],"verseLabel":"ص: 55","question":"ما سر الانتقال بقوله: ﴿هَذَا وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ﴾؟","answer":"يفصل اسم الإشارة بين مشهد نعيم المتقين ومشهد عذاب الطاغين، مع إبقاء المقابلة حاضرة؛ فيتهيأ السامع للانتقال من الترغيب إلى الترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص539–540، تحت عنوان «براعة استعمال اسم الإشارة في الانتقال بين الأغراض»","url":""}]},{"id":"s38-80","number":80,"surah":38,"verses":[55],"references":[{"surah":38,"verses":[55]}],"verseLabel":"ص: 55","question":"لماذا قوبل ﴿حُسْنَ مَآبٍ﴾ للمتقين بـ﴿شَرَّ مَآبٍ﴾ للطاغين؟","answer":"لأن اختيار الشر يلمّح بضده إلى الخير الذي سبق للمتقين، فتوجز المقابلة تفاوت المصيرين وتبرز أن نهاية الطغيان شر محض.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص543، تحت عنوان «بلاغة اختلاف المقابلة في اختيار مفردة (شر)»","url":""}]},{"id":"s38-47","number":47,"surah":38,"verses":[57],"references":[{"surah":38,"verses":[57]}],"verseLabel":"ص: 57","question":"لماذا أشير إلى عذاب أهل النار بلفظ القريب: ﴿هَذَا﴾؟","answer":"ليُستحضر العذاب كأنه حاضر قريب تراه العين، فيشتد التحذير والتهويل من عاقبة الطاغين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص548، تحت عنوان «وظيفة اسم الإشارة للقريب»","url":""}]},{"id":"s38-81","number":81,"surah":38,"verses":[57],"references":[{"surah":38,"verses":[57]}],"verseLabel":"ص: 57","question":"لماذا قيل لأهل النار: ﴿فَلْيَذُوقُوهُ﴾؟","answer":"استُعمل الذوق تهكمًا وتوبيخًا؛ فبدل أن يذوقوا طعامًا أو شرابًا لذيذًا يُجبرون على مباشرة الحميم والغساق، فيظهر هوانهم وشدة عقابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص549، تحت عنوان «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s38-48","number":48,"surah":38,"verses":[59],"references":[{"surah":38,"verses":[59]}],"verseLabel":"ص: 59","question":"لماذا استقبل أهل النار الفوج الداخل بقولهم: ﴿لَا مَرْحَبًا بِهِمْ﴾؟","answer":"لأن نفي الترحيب أبلغ في إظهار البغض والتحقير من مجرد وصفهم بالذم؛ فهو دعاء بضيق المكان عليهم وكراهية شديدة لقدومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص560–561، تحت عنوان «نكتة إيثار نفي الترحيب على إثبات الذم»","url":""}]},{"id":"s38-82","number":82,"surah":38,"verses":[59],"references":[{"surah":38,"verses":[59]}],"verseLabel":"ص: 59","question":"لماذا ردّ الأتباع على رؤسائهم بالكلمة نفسها: ﴿بَلْ أَنْتُمْ لَا مَرْحَبًا بِكُمْ﴾؟","answer":"ليردوا اللعنة على من أضلهم؛ فالكلمة المطابقة تكشف انقلاب الاتباع في الدنيا إلى خصومة، وتحمل الرؤساء مسؤولية ما انتهوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص565، تحت عنوان «دلالة استعمال ﴿لا مرحبًا بكم﴾ النظيرة لكلمة الأسياد»","url":""}]},{"id":"s38-49","number":49,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا يكشف سؤال أهل النار: ﴿مَا لَنَا لَا نَرَى رِجَالًا﴾؟","answer":"يكشف تعجبهم وحسرتهم حين لم يجدوا المؤمنين الذين كانوا يحتقرونهم؛ فقد انقلب معيارهم، وبان لهم أنهم هم الذين ضلوا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص581، تحت عنوان «غرض الاستفهام بـ﴿ما﴾»","url":""}]},{"id":"s38-83","number":83,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا يفيد المضارع في قولهم: ﴿كُنَّا نَعُدُّهُمْ مِنَ الْأَشْرَارِ﴾؟","answer":"يفيد أن احتقارهم للمؤمنين كان عادة متجددة لا حكمًا عابرًا؛ ظلوا يكررونه في الدنيا حتى رسخ في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص583، تحت عنوان «دلالة التعبير بالمضارع ﴿نعدهم﴾»","url":""}]},{"id":"s38-84","number":84,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا تكشف عبارة ﴿مِنَ الْأَشْرَارِ﴾ عن نظرة الكافرين للمؤمنين؟","answer":"تكشف أنهم لم يكتفوا بوصفهم بالشر، بل زعموهم مندمجين في زمرة الأشرار؛ ثم قلبت الآخرة حكمهم حين ظهر فساد مقياسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص584، تحت عنوان «دلالة ﴿من﴾»","url":""}]},{"id":"s38-50","number":50,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"ماذا يفيد تنكير ﴿نَبَأٌ﴾ في قوله: ﴿هُوَ نَبَأٌ عَظِيمٌ﴾؟","answer":"يفيد التفخيم؛ فكأنه نبأ لا يحيط الوصف بقدره، ويحتمل من وجوه العظمة ما يوجب الإصغاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620، تحت عنوان «نكتة تنكير النبأ»","url":""}]},{"id":"s38-85","number":85,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"لماذا وُصف النبأ بأنه ﴿عَظِيمٌ﴾؟","answer":"لتأكيد جلال شأنه وخطر عاقبته؛ فهو وحي من الله، في التصديق به نجاة وفي تكذيبه هلاك، فلا يصح الاستخفاف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620، تحت عنوان «نكتة وصف النبأ بالعظيم»","url":""}]},{"id":"s38-86","number":86,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"ما الذي يضيفه قوله: ﴿أَنْتُمْ عَنْهُ مُعْرِضُونَ﴾ بعد وصفه بالنبأ العظيم؟","answer":"يفضح المفارقة بين عظمة النبأ وثبات إعراضهم عنه، فيتحول الوصف إلى توبيخ مباشر لمن يهمل خبرًا يمس مصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620–621، تحت عنوان «علة فصل ﴿أنتم عنه معرضون﴾»","url":""}]},{"id":"s38-51","number":51,"surah":38,"verses":[69],"references":[{"surah":38,"verses":[69]}],"verseLabel":"ص: 69","question":"كيف صار قول الرسول: ﴿مَا كَانَ لِي مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَى﴾ دليلًا على الوحي؟","answer":"لأنه لم يشهد اختصام الملأ الأعلى ولم يكن يعلمه قبل الوحي، فإخباره به بعد ذلك يدل على أن العلم جاءه من الله لا من نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص625، تحت عنوان «علة فصل الآية»","url":""}]},{"id":"s38-52","number":52,"surah":38,"verses":[72],"references":[{"surah":38,"verses":[72]}],"verseLabel":"ص: 72","question":"ماذا تفيد ﴿سَوَّيْتُهُ﴾ في وصف خلق آدم؟","answer":"تفيد أن الله أتم خلقه في صورة متناسقة، وجعل أعضاءه سليمة تؤدي وظائفها على أكمل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص643، تحت عنوان «دلالة التعبير بالتسوية»","url":""}]},{"id":"s38-87","number":87,"surah":38,"verses":[72],"references":[{"surah":38,"verses":[72]}],"verseLabel":"ص: 72","question":"لماذا عُبّر عن إحياء آدم بالنفخ؟","answer":"هو تصوير لطيف لإفاضة الحياة في الجسد وسريان الروح في أجزائه، من غير أن يكون النفخ على حقيقته البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص644، تحت عنوان «بلاغة التعبير بالنفخ»","url":""}]},{"id":"s38-53","number":53,"surah":38,"verses":[74],"references":[{"surah":38,"verses":[74]}],"verseLabel":"ص: 74","question":"لماذا عبّر عن موقف إبليس بقوله: ﴿اسْتَكْبَرَ﴾؟","answer":"لأن الصيغة تصوّر أنه طلب الكِبَر وتعاظم على أمر الله، فكان امتناعه ثمرة استعلاء شديد لا مجرد ترك عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص654، تحت عنوان «سر التعبير بالاستكبار»","url":""}]},{"id":"s38-88","number":88,"surah":38,"verses":[74],"references":[{"surah":38,"verses":[74]}],"verseLabel":"ص: 74","question":"ماذا تفيد ﴿كَانَ﴾ في قوله: ﴿وَكَانَ مِنَ الْكَافِرِينَ﴾؟","answer":"تحتمل أن كفره كان كامنًا فظهر عند الامتحان، أو أنه صار من الكافرين بسبب امتناعه؛ وعلى الوجهين تكشف رسوخ صلة الكبر بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص654، تحت عنوان «دلالة التعبير بـ(كان)»","url":""}]},{"id":"s38-54","number":54,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"ما غرض السؤال الإلهي لإبليس: ﴿مَا مَنَعَكَ أَنْ تَسْجُدَ﴾؟","answer":"ليس لطلب العلم، بل للتوبيخ والإنكار وإلزام إبليس أن يقر بسبب عصيانه، فتظهر قبح سريرته أمام الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص659–660، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s38-89","number":89,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"لماذا أضاف الله خلق آدم إلى نفسه في قوله: ﴿لِمَا خَلَقْتُ﴾؟","answer":"لتشريف آدم وبيان اختصاصه بعناية الله الذي تولى خلقه في أحسن صورة؛ فيزداد قبح رفض إبليس السجود له.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص662، تحت عنوان «سر إضافة الله الخلق إلى نفسه»","url":""}]},{"id":"s38-90","number":90,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"ما دلالة قوله تعالى عن آدم: ﴿خَلَقْتُ بِيَدَيَّ﴾؟","answer":"ذكر اليدين وتثنيتهما يبرز كمال العناية والتكريم واختصاص آدم بالتشريف، من غير واسطة أب ولا أم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص662، تحت عنوان «نكتة ذكر اليدين وتثنيتهما»","url":""}]},{"id":"s38-55","number":55,"surah":38,"verses":[76],"references":[{"surah":38,"verses":[76]}],"verseLabel":"ص: 76","question":"لماذا قدّم إبليس ذكر خلقه من النار على خلق آدم من الطين؟","answer":"اعتناءً بنفسه وزعمًا أنه أحق بالتقديم حالًا ومقالًا؛ فترتيبه يكشف أنانيته وتعاظمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص667، تحت عنوان «غرض تقديم خلق إبليس»","url":""}]},{"id":"s38-91","number":91,"surah":38,"verses":[76],"references":[{"surah":38,"verses":[76]}],"verseLabel":"ص: 76","question":"ماذا يفيد تنكير ﴿طِينٍ﴾ في احتجاج إبليس؟","answer":"يفيد التحقير في سياق استكباره، إذ صوّر أصل آدم مادة مجهولة حقيرة ليهوّن شأنه ويرفع نفسه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص668، تحت عنوان «نكتة تنكير ﴿طين﴾»","url":""}]},{"id":"s38-56","number":56,"surah":38,"verses":[82],"references":[{"surah":38,"verses":[82]}],"verseLabel":"ص: 82","question":"لماذا أقسم إبليس بعزة الله في قوله: ﴿فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ﴾؟","answer":"لأن العزة الكاملة لله هي التي لا يقع الإغواء إلا بما أذن به تقديرًا، فكأنه يقر بأنه لا يقدر على شيء خارج سلطان الله مع عزمه على الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص690، تحت عنوان «سر القسم بصفة العزة دون غيرها»","url":""}]},{"id":"s38-92","number":92,"surah":38,"verses":[82],"references":[{"surah":38,"verses":[82]}],"verseLabel":"ص: 82","question":"ما دلالة توالي المؤكدات في قول إبليس: ﴿فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"يصور فرط ثقته وعزمه على إغواء بني آدم: جمع القسم ولام الجواب ونون التوكيد و﴿أجمعين﴾ ليؤكد شمول قصده وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص691، تحت عنوان «غرض توالي المؤكدات»","url":""}]},{"id":"s38-58","number":58,"surah":38,"verses":[86],"references":[{"surah":38,"verses":[86]}],"verseLabel":"ص: 86","question":"ما الذي ينفيه قول الرسول ﷺ: ﴿وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ﴾؟","answer":"ينفي أن يتصنع الوحي أو ينسب إلى الله ما لم يوح به، وأن يحمل الناس على كلام مختلق أو يتجاوز حدود البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص721، تحت عنوان «دلالة التعبير بالتكلف في ﴿المتكلفين﴾»","url":""}]},{"id":"s38-93","number":93,"surah":38,"verses":[86],"references":[{"surah":38,"verses":[86]}],"verseLabel":"ص: 86","question":"لماذا قال الرسول ﷺ: ﴿مِنَ الْمُتَكَلِّفِينَ﴾ بدل «ما أتكلف»؟","answer":"لأن نفي الانتساب إلى فئة المتكلفين أبلغ من نفي فعل عارض؛ فهو يبرئه من أن يكون التكلف طبعًا له أو شأنًا يُعرف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص722، تحت عنوان «نكتة إيثار التعبير بقوله: ﴿من المتكلفين﴾»","url":""}]},{"id":"s38-59","number":59,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87-88","question":"لماذا جاء الوعد: ﴿وَلَتَعْلَمُنَّ نَبَأَهُ﴾ مؤكدًا بالقسم؟","answer":"لتوكيد أنهم سيبلغون علمًا يقينيًا بصدق القرآن عند ظهور خبره، فيكون تهديدًا للمعرضين وبشارة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص727، تحت عنوان «معنى (اللام) في قوله: ﴿ولتعلمن﴾»","url":""}]},{"id":"s38-94","number":94,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87-88","question":"كيف أحسن ختام سورة ص بقوله: ﴿وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ﴾؟","answer":"ردّ آخر السورة إلى أولها الذي وصف القرآن بذي الذكر، وختم بوعد ووعيد مؤكدين؛ فظهر صدق الذكر واتصل ختام السورة بمطلعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص732، تحت عنوان «بلاغة حسن الختام في الآية»","url":""}]},{"id":"s39-1","number":1,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزمر»، وما صلة الاسم بمشهد سوق الفريقين في خاتمتها؟","answer":"ورد اسم الزمر في مشهدي سوق الكافرين والمتقين جماعات إلى مصيرهما. ويصل المبحث التسمية بمحور السورة في تحقيق الدين الخالص لله؛ إذ تتقابل فيها طوائف الناس ومواقفهم، ثم تظهر عواقبهم في مشهد الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص737–738، تحت عنوان «اسم السورة وسبب التسمية»","url":""}]},{"id":"s39-2","number":2,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"الزمر: 1","question":"ما سر الجمع بين اسمي الله ﴿الْعَزِيزِ الْحَكِيمِ﴾ في مطلع السورة؟","answer":"ليدل على أن منزل القرآن غالب لا يعجزه شيء، وحكيم يضع تشريعه ووحيه في موضعهما؛ فاجتمعت قوة السلطان وكمال الحكمة ضمانًا لحق الكتاب وأحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص754–755، تحت عنوان «لطيفة الجمع بين ﴿العزيز﴾ و﴿الحكيم﴾»","url":""}]},{"id":"s39-3","number":3,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"الزمر: 1","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْحَكِيمِ﴾ في مصدر التنزيل؟","answer":"يذكر المبحث أن تقديم العزيز من تقديم السبب على المسبب؛ فالقدرة مقدمة على حسن التقدير، والعزة من صفات الذات والحكمة من صفات الأفعال. ويلائم الترتيب مقام بيان سلطان القرآن على معارضيه بالحجة وإحكام ما جاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص755، تحت عنوان «نكتة تقديم ﴿العزيز﴾ على ﴿الحكيم﴾»","url":""}]},{"id":"s39-4","number":4,"surah":39,"verses":[2],"references":[{"surah":39,"verses":[2]}],"verseLabel":"الزمر: 2","question":"ماذا يفيد قوله: ﴿تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ﴾؟","answer":"تفيد ﴿مِنْ﴾ ابتداء صدور التنزيل من عند الله، فتقطع نسبته إلى غيره، وتزيد الكتاب تشريفًا لأن مصدره هو الله العزيز الحكيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص752، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من الله﴾»","url":""}]},{"id":"s39-116","number":116,"surah":39,"verses":[2],"references":[{"surah":39,"verses":[2]}],"verseLabel":"الزمر: 2","question":"لماذا انتقل التعبير من الغيبة في ﴿مِنَ اللَّهِ﴾ إلى التكلم في ﴿إِنَّا أَنْزَلْنَا إِلَيْكَ﴾؟","answer":"لينتقل السامع من الخبر عن منزل الكتاب إلى خطاب الرسول مباشرة، فيقوى معنى العناية به وبما أنزل إليه، ويجيء ضمير التعظيم ملائمًا لجلال القرآن وصدق إنزاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص757–758، تحت عنوان «نكتة العدول عن أسلوب الغيبة إلى التكلم»","url":""}]},{"id":"s39-5","number":5,"surah":39,"verses":[2,3],"references":[{"surah":39,"verses":[2,3]}],"verseLabel":"الزمر: 2–3","question":"ماذا يضيف قوله: ﴿مُخْلِصًا لَهُ الدِّينَ﴾ إلى الأمر بعبادة الله؟","answer":"يبين أن العبادة المطلوبة لا يكفي فيها ظاهر العمل، بل لا بد أن تُنقّى من كل شرك ورياء، فتكون الطاعة والقصد لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص766، تحت عنوان «دلالة التعبير بالإخلاص في القيد ﴿مخلصًا﴾»","url":""}]},{"id":"s39-6","number":6,"surah":39,"verses":[3],"references":[{"surah":39,"verses":[3]}],"verseLabel":"الزمر: 3","question":"لماذا قال المشركون: ﴿لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى﴾ ولم يقولوا: ليكونوا واسطة؟","answer":"لأن ﴿زُلْفَى﴾ تصور غاية القرب وتمامه، فكشفت ضخامة وهمهم: ظنوا أن عبادة الأصنام تبلغ بهم أقصى القرب من الله، مع أن هذا الطريق نفسه يبعدهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص783، تحت عنوان «دلالة التعبير بـ﴿زلفى﴾ دون (واسطة)»","url":""}]},{"id":"s39-7","number":7,"surah":39,"verses":[3],"references":[{"surah":39,"verses":[3]}],"verseLabel":"الزمر: 3","question":"لماذا قُدّم وصف ﴿كَاذِبٌ﴾ على ﴿كَفَّارٌ﴾؟","answer":"لتفظيع كذبهم؛ لأن دعوى الولد والشفعاء كذب على الله، وهذا الكذب هو الذي ساقهم إلى شدة الكفر، فذُكر السبب قبل ما نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص793، تحت عنوان «نكتة تقديم ﴿كاذب﴾ على ﴿كفار﴾»","url":""}]},{"id":"s39-8","number":8,"surah":39,"verses":[4],"references":[{"surah":39,"verses":[4]}],"verseLabel":"الزمر: 4","question":"لماذا قال: ﴿لَاصْطَفَى مِمَّا يَخْلُقُ مَا يَشَاءُ﴾ ولم يقل: لاتخذ ولدًا؟","answer":"لأن الاصطفاء اختيار وتشريف لمخلوق، لا ولادة ولا مشاركة في الألوهية؛ فحوّل الفرض نفسه إلى ما يليق بالخالق، وأبطل تصور الولد من داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص804–805، تحت عنوان «لطيفة العدول عن فعل الاتخاذ في الشرط»","url":""}]},{"id":"s39-9","number":9,"surah":39,"verses":[4],"references":[{"surah":39,"verses":[4]}],"verseLabel":"الزمر: 4","question":"ما مناسبة ختم نفي الولد بقوله: ﴿هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"فـ﴿الواحد﴾ ينفي النظير والشريك والولد، و﴿القهار﴾ يقرر أن كل ما سواه مخلوق مقهور له؛ ومن كان واحدًا قاهرًا لا يحتاج إلى ولد يعينه أو يخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص809، تحت عنوان «وجه مناسبة صفتي ﴿الواحد القهار﴾»","url":""}]},{"id":"s39-10","number":10,"surah":39,"verses":[5],"references":[{"surah":39,"verses":[5]}],"verseLabel":"الزمر: 5","question":"ما الصورة التي يرسمها قوله: ﴿يُكَوِّرُ اللَّيْلَ عَلَى النَّهَارِ وَيُكَوِّرُ النَّهَارَ عَلَى اللَّيْلِ﴾؟","answer":"يشبه تعاقبهما بلف عمامة يلتف بعضها فوق بعض؛ فيغشى أحدهما الآخر شيئًا فشيئًا، ويصور امتدادهما المتداخل وتجدد دورانهما في نظام لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص17–18، تحت عنوان «بلاغة الاستعارة في الفعل ﴿يكور﴾»","url":""}]},{"id":"s39-11","number":11,"surah":39,"verses":[5],"references":[{"surah":39,"verses":[5]}],"verseLabel":"الزمر: 5","question":"لماذا قيل عن الشمس والقمر: ﴿كُلٌّ يَجْرِي لِأَجَلٍ مُسَمًّى﴾ ولم يقل: لوقت أو زمن؟","answer":"لأن ﴿الأجل﴾ زمن ينتهي عنده الشيء، فتومئ الكلمة إلى أن هذا الجريان المنظم ليس أبديًا، بل له حد مقدر تنتهي إليه مسيرته بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص27، تحت عنوان «دلالة التعبير بـ(أجل) دون (وقت) أو (زمن)»","url":""}]},{"id":"s39-12","number":12,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا قيل: ﴿وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعَامِ﴾ باللام، لا: أنزل عليكم؟","answer":"لأن اللام تشعر بأن الأنعام مسخرة لمنفعة الناس ومهيأة لمصالحهم، أما ﴿على﴾ فتلائم مجرد وقوع الإنزال عليهم؛ فاختير ما يبرز نعمة الاختصاص والانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص45، تحت عنوان «نكتة تعدية فعل الإنزال باللام دون (على)»","url":""}]},{"id":"s39-13","number":13,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا أُخّر قوله: ﴿يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ﴾ إلى ما بعد ذكر الأنعام؟","answer":"ليجيء خلق الإنسان الخفي بعد ذكر أصل البشر وخلق الأنعام شاهدًا أقرب إلى كل سامع؛ فانتقل السياق من النعم المحيطة به إلى أطوار وجوده نفسه، وهو أدعى للتأمل والتأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص49، تحت عنوان «سر تأخير جملة: ﴿يخلقكم في بطون أمهاتكم﴾»","url":""}]},{"id":"s39-14","number":14,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"ماذا تضيف ﴿فِي﴾ في قوله: ﴿فِي ظُلُمَاتٍ ثَلَاثٍ﴾؟","answer":"تصور الجنين محاطًا بهذه الظلمات من كل جهة، مستقرًا داخل طبقات لا يصل إليها تدبير البشر؛ فيبرز حفظ الله له وقدرته على خلقه في ذلك الخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص53، تحت عنوان «دلالة الظرفية في قوله: ﴿في ظلمات ثلاث﴾»","url":""}]},{"id":"s39-117","number":117,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا نُكّرت ﴿ظُلُمَاتٍ﴾ في قوله: ﴿فِي ظُلُمَاتٍ ثَلَاثٍ﴾؟","answer":"لتفخيم شدتها وإبهام حقيقتها على السامع، فهي ظلمات متراكبة عجيبة لا يدرك تفاصيلها، ومع ذلك ينفذ فيها خلق الله وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص54، تحت عنوان «نكتة تنكير ﴿ظلمات﴾»","url":""}]},{"id":"s39-15","number":15,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا قُدّم ﴿لَهُ﴾ في قوله: ﴿لَهُ الْمُلْكُ﴾؟","answer":"لقصر الملك الحقيقي عليه وحده؛ فبعد إثبات الخلق والتدبير قرر أن السلطان كله له، ولا يملك من دونه استقلالًا شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص57، تحت عنوان «غرض تقديم شبه الجملة الخبرية ﴿له﴾»","url":""}]},{"id":"s39-16","number":16,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"إذا كان الله غنيًا عن الناس، فلماذا قال: ﴿وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ﴾؟","answer":"لئلا يُفهم من غناه أنه لا يبالي بأفعالهم؛ فهو لا ينتفع بإيمانهم ولا يتضرر بكفرهم، ومع ذلك يكره لهم الكفر رحمةً بهم لأنه سبب شقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص73، تحت عنوان «بلاغة جملة الاعتراض في قوله: ﴿ولا يرضى لعباده الكفر﴾»","url":""}]},{"id":"s39-17","number":17,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"ما مناسبة قوله: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾ بعد ذكر الكفر والشكر؟","answer":"ليقرر أن نتيجة الاختيار عائدة إلى صاحبه وحده: فلا يضر كفر الكافر ربَّه ولا غيره، ولا ينفع شكر الشاكر إلا نفسه، وكل إنسان يحمل تبعة عمله عند الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص79، تحت عنوان «غرض الجملة الخبرية ﴿ولا تزر وازرة وزر أخرى﴾»","url":""}]},{"id":"s39-18","number":18,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"ماذا يصور وصف الإنسان بأنه يدعو ربه ﴿مُنِيبًا إِلَيْهِ﴾ عند الضر؟","answer":"يصور رجوعه السريع بكليته إلى الله، منقطعًا عمن سواه؛ فالشدّة تكشف في لحظتها ما تعرفه الفطرة من أن الملجأ الحقيقي هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص95، تحت عنوان «دلالة التعبير بلفظ الإنابة»","url":""}]},{"id":"s39-118","number":118,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"ماذا تكشف ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ إِذَا خَوَّلَهُ نِعْمَةً مِنْهُ نَسِيَ﴾؟","answer":"تكشف بُعد ما فعله عما يُنتظر منه؛ فبعد دعاء صادق ونعمة من الله كان المنتظر الشكر، لكنه انتقل انتقالًا مستبعدًا إلى النسيان والشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص97، تحت عنوان «دلالة حرف ﴿ثم﴾»","url":""}]},{"id":"s39-119","number":119,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"لماذا قيل: ﴿وَجَعَلَ لِلَّهِ أَنْدَادًا﴾ ولم يقل: واتخذ؟","answer":"لأن ﴿جعل﴾ تصور أنه اخترع لله أمثالًا من عند نفسه وأقامها في وهمه مقام الأنداد، مع أنها لا تملك في الحقيقة شيئًا من صفات الندية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص103، تحت عنوان «نكتة التعبير بالجعل بدل الاتخاذ وغيره»","url":""}]},{"id":"s39-19","number":19,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"لماذا قيل: ﴿خَوَّلَهُ نِعْمَةً﴾ بدل: أعطاه نعمة؟","answer":"لأن التخويل عطاء واسع يجعله الله تحت تصرف الإنسان ويتمتع به مدة، فيذكّره اللفظ بأن النعمة منحة مفوضة إليه وليست ملكًا ذاتيًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص98، تحت عنوان «دلالة التعبير بالتخويل في قوله: ﴿خوله﴾»","url":""}]},{"id":"s39-20","number":20,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"لماذا وُصف القانت بأنه يعبد الله ﴿آنَاءَ اللَّيْلِ﴾؟","answer":"للدلالة على أنه يوزع عبادته على ساعات الليل المختلفة ويكررها، لا أنها لحظة عابرة؛ وفي الليل مزيد إخلاص وهدوء وبعد عن أعين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص120–121، تحت عنوان «فائدة ذكر الظرفية في ﴿آناء الليل﴾»","url":""}]},{"id":"s39-21","number":21,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"ما سر تقديم الحذر من الآخرة على رجاء رحمة الله؟","answer":"قدم الحذر لأنه يدفع ما تخشاه النفس، ودفع المضار مقدم على جلب المنافع. ثم جاء الرجاء ليكمل الباعث على العمل؛ فيجتمع اجتناب ما يوجب العقوبة وطلب ما يصلح العبد عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص127، تحت عنوان «نكتة تقديم الحذر على الرجاء»","url":""}]},{"id":"s39-22","number":22,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"لماذا قيل: ﴿الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾ في سياق مقارنة القانت بغيره؟","answer":"لأن العلم هنا يظهر أثره في الإيمان والطاعة؛ فسمّى العامل بعلمه عالمًا، ونزّل من لا يعمل منزلة من لا يعلم، وفي التعبير تعريض بمن عرف الحق ثم لم يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص132، تحت عنوان «بلاغة التعبير بقوله: ﴿الذين يعلمون والذين لا يعلمون﴾»","url":""}]},{"id":"s39-23","number":23,"surah":39,"verses":[10],"references":[{"surah":39,"verses":[10]}],"verseLabel":"الزمر: 10","question":"ماذا توحي عبارة ﴿وَأَرْضُ اللَّهِ وَاسِعَةٌ﴾ للمؤمن الذي لا يستطيع إقامة دينه؟","answer":"تكني عن فتح باب الهجرة وعدم الاستسلام لمكان يفتنه؛ فأرض الله ليست محصورة في موطن الأذى، وفي سعتها دعوة إلى طلب موضع يستطيع فيه طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص151، تحت عنوان «بلاغة الكناية في قوله: ﴿وأرض الله واسعة﴾»","url":""}]},{"id":"s39-24","number":24,"surah":39,"verses":[11,12],"references":[{"surah":39,"verses":[11,12]}],"verseLabel":"الزمر: 11–12","question":"لماذا تكرر ﴿وَأُمِرْتُ﴾ في قوله: ﴿وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ الْمُسْلِمِينَ﴾؟","answer":"لإبراز أن المبادرة إلى الإسلام مأمور بها استقلالًا، وليست مجرد نتيجة تابعة للأمر بإخلاص العبادة؛ فتكرر الفعل ليمنح كل تكليف عنايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص161–162، تحت عنوان «دلالة تكرار الفعل في ﴿وأمرت﴾»","url":""}]},{"id":"s39-120","number":120,"surah":39,"verses":[11,12],"references":[{"surah":39,"verses":[11,12]}],"verseLabel":"الزمر: 11–12","question":"لماذا وصف الرسول ﷺ بأنه ﴿أَوَّلَ الْمُسْلِمِينَ﴾؟","answer":"ليعلن تمام مبادرته إلى الامتثال، فهو أول أمته انقيادًا لما يدعوهم إليه؛ وبذلك يطابق فعله قوله ولا يأمر الناس بما يتأخر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص163، تحت عنوان «دلالة التعبير بالأولية والغرض من الإضافة»","url":""}]},{"id":"s39-26","number":26,"surah":39,"verses":[14],"references":[{"surah":39,"verses":[14]}],"verseLabel":"الزمر: 14","question":"ما دلالة تقديم اسم الجلالة في ﴿قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَهُ دِينِي﴾؟","answer":"تقديم المفعول ﴿الله﴾ يقصر العبادة عليه، فيعلن الرسول ﷺ اختصاصه بها في مواجهة دعوة الشرك. ويؤكد التعبير بالاسم الجامع لصفات الكمال أنه وحده المستحق لهذه العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص172، تحت عنوان «الغرض من تقديم المفعول به ونكتة التعبير بالاسم الجليل»","url":""}]},{"id":"s39-27","number":27,"surah":39,"verses":[2,14],"references":[{"surah":39,"verses":[2,14]}],"verseLabel":"الزمر: 2، 14","question":"لماذا قال أولًا: ﴿مُخْلِصًا لَهُ الدِّينَ﴾ ثم قال: ﴿مُخْلِصًا لَهُ دِينِي﴾؟","answer":"الأولى تقرر وجوب إخلاص جنس الدين لله، أما إضافة ﴿ديني﴾ إلى ياء المتكلم فتنقل المعنى من الحكم العام إلى إعلان الرسول تطبيقه في عبادته هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص173–174، تحت عنوان «الغرض من الإضافة لياء المتكلم في ﴿ديني﴾»","url":""}]},{"id":"s39-28","number":28,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا قيل للمشركين: ﴿فَاعْبُدُوا مَا شِئْتُمْ مِنْ دُونِهِ﴾ مع أن عبادة غير الله محرمة؟","answer":"ليس إذنًا لهم، بل أمر تهديد وتخلية بعد إقامة الحجة؛ أي امضوا فيما اخترتم وستلقون عاقبته، ولذلك أعقبه فورًا بيان الخسران المبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص175، تحت عنوان «الغرض من فعل الأمر ﴿فاعبدوا﴾»","url":""}]},{"id":"s39-29","number":29,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا عرّف القرآن الخاسرين بأنهم الذين خسروا أنفسهم يوم القيامة؟","answer":"لقصر الخسران الحقيقي الكامل عليهم؛ فالخسارات الدنيوية يمكن تداركها، أما من أضاع نفسه في الآخرة فقد فقد رأس ماله الذي لا يعوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص177–178، تحت عنوان «معنى اللام ودلالتها، والغرض من تعريف المسند إليه والمسند»","url":""}]},{"id":"s39-121","number":121,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا أضاف إلى خسارة النفس قوله: ﴿وَأَهْلِيهِمْ﴾؟","answer":"ليصور أن الخسارة لا تقف عند مصير الفرد، بل تشمل فوات اجتماعه بأهله المؤمنين أو إهلاك من تبعه منهم؛ فتجتمع عليه وحشة النفس ووحشة الفراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص179، تحت عنوان «الغرض من الإضافة في ﴿وأهليهم﴾»","url":""}]},{"id":"s39-30","number":30,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا سُمّيت النار المحيطة بالكافرين ﴿ظُلَلًا﴾؟","answer":"جاء اللفظ على استعارة تهكمية؛ فالظلة يتوقع منها الوقاية والراحة، فإذا بها طبقات من النار تغشاهم، فينقلب الاسم المطمئن إلى صورة أشد رعبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص188، تحت عنوان «الغرض من التعبير بالاستعارة التهكمية في قوله: ﴿ظلل﴾»","url":""}]},{"id":"s39-122","number":122,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا أعيدت كلمة ﴿ظُلَلٌ﴾ في قوله: ﴿وَمِنْ تَحْتِهِمْ ظُلَلٌ﴾؟","answer":"لتأكيد أن ما تحتهم نار كثيفة طبقات كالنار التي فوقهم، لا مجرد لهب عابر؛ فالتكرار يجسم إحاطة العذاب بهم من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص189–190، تحت عنوان «بلاغة الإطناب في قوله: ﴿ومن تحتهم ظلل﴾»","url":""}]},{"id":"s39-31","number":31,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا قُدّم النداء ﴿يَا عِبَادِ﴾ على الأمر ﴿فَاتَّقُونِ﴾ بعد مشهد النار؟","answer":"ليسبق التحذيرَ تذكيرٌ برابطة العبودية المشرِّفة ورحمة المنادي؛ فيستجيب القلب للأمر اتقاءً لمن يخوف عباده رحمةً بهم لا رغبةً في عذابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص194، تحت عنوان «سر تقديم النداء ﴿يا عباد﴾ على الأمر ﴿فاتقون﴾»","url":""}]},{"id":"s39-32","number":32,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"لماذا جُمع بين اجتناب الطاغوت والإنابة إلى الله؟","answer":"لأن ترك الباطل وحده لا يكمل الهداية حتى يصحبه إقبال على الحق؛ فجمع الوصف بين التخلي عن عبادة الطاغوت والتحلي بالرجوع إلى الله وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص202، تحت عنوان «دلالة العطف في قوله: ﴿وأنابوا إلى الله﴾»","url":""}]},{"id":"s39-33","number":33,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"ماذا تفيد الفاء في قوله: ﴿فَيَتَّبِعُونَ أَحْسَنَهُ﴾ بعد استماع القول؟","answer":"تفيد سرعة انتقالهم من حسن الاستماع والتمييز إلى العمل، فلا يقفون عند المعرفة ولا يؤخرون الاستجابة لما ظهر لهم أنه أحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص209، تحت عنوان «معنى الفاء ودلالتها في ﴿فيتبعون﴾»","url":""}]},{"id":"s39-123","number":123,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"لماذا قيل: ﴿فَيَتَّبِعُونَ أَحْسَنَهُ﴾؟","answer":"ليدل على أنهم لا يكتفون بأي قول، بل يزنون ما يسمعون ثم يختارون أهداه وأصوبه؛ وفي إضافة الأحسن إلى القول إشارة إلى قدرتهم على التمييز وحسن الاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص210، تحت عنوان «دلالة التعبير بأفعل التفضيل ﴿أحسنه﴾، والغرض من الإضافة»","url":""}]},{"id":"s39-34","number":34,"surah":39,"verses":[18],"references":[{"surah":6,"verses":[90]},{"surah":39,"verses":[18]}],"verseLabel":"الزمر: 18؛ الأنعام: 90","question":"ماذا يفيد قوله: ﴿أُولَئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ﴾ بعد وصف مستمعي القول؟","answer":"يقصر الهداية الكاملة على أصحاب هذا الوصف تنويهًا بهم: فهداية الله تظهر في عقل منصف يسمع ويميز ثم يتبع الأحسن، لا في مجرد سماع لا يثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص211، تحت عنوان «بلاغة القصر في قوله: ﴿أولئك الذين﴾»","url":""}]},{"id":"s39-35","number":35,"surah":39,"verses":[19],"references":[{"surah":39,"verses":[19]}],"verseLabel":"الزمر: 19","question":"كيف يبني ترتيب قوله: ﴿أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾ معنى استحالة إنقاذه؟","answer":"يبدأ بثبوت كلمة العذاب عليه، ثم يواجه الرسول بسؤال إنكاري عن إنقاذه، ثم يصوره كأنه داخل النار؛ فتتدرج العبارة من الحكم المحتوم إلى نفي قدرة البشر على دفعه ثم إلى مشاهدة مآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص224، تحت عنوان «بلاغة ترتيب الآية ونظمها»","url":""}]},{"id":"s39-36","number":36,"surah":39,"verses":[19],"references":[{"surah":39,"verses":[19]}],"verseLabel":"الزمر: 19","question":"ما غرض سؤال الرسول ﷺ: ﴿أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾؟","answer":"الاستفهام للإنكار والتسلية: من ثبتت عليه كلمة العذاب لا يملك الرسول إنقاذه قسرًا، وإنما عليه البلاغ؛ وفي توجيه السؤال إليه إبراز لعجز كل أحد عن تغيير حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص220–221، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أفأنت﴾ وتكرره»","url":""}]},{"id":"s39-37","number":37,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"لماذا وُصفت غرف الجنة بأنها ﴿مَبْنِيَّةٌ﴾؟","answer":"لتأكيد رسوخها وإحكامها ودوامها؛ فكون الغرف فوق غرف قد يوهم بناءً معلقًا غير ثابت، فجاء الوصف ليزيل الوهم ويصور مساكن آمنة لا تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص231–232، تحت عنوان «سر وصف الغرف بالوصف ﴿مبنية﴾ ومجيئه مفردًا»","url":""}]},{"id":"s39-38","number":38,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"ماذا يضيف قوله: ﴿وَعْدَ اللَّهِ﴾ بعد وصف غرف المتقين؟","answer":"جاء مصدرًا مؤكدًا لمضمون الوعد، ثم أضيف إلى الله ليبلغ اليقين غايته؛ فهذه الغرف ليست أمنية بل وعدًا صادرًا ممن لا يعجزه إنجازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص234–235، تحت عنوان «سر التعبير بالمفعول المطلق ﴿وعد﴾»","url":""}]},{"id":"s39-124","number":124,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"لماذا قيل: ﴿لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾ ولم يقل: لا يخلف الميعاد؟","answer":"لإعادة اسم الجلالة تصريحًا فتزداد الجملة استقلالًا وهيبةً وتوكيدًا؛ فالذي أسند إليه الوعد هو نفسه الكامل الذي يستحيل عليه إخلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص236، تحت عنوان «الغرض من التعبير عن الفاعل بالاسم الجليل ﴿الله﴾»","url":""}]},{"id":"s39-39","number":39,"surah":39,"verses":[21],"references":[{"surah":39,"verses":[21]}],"verseLabel":"الزمر: 21","question":"لماذا عرضت الآية دورة الماء والزرع حتى يصير حطامًا؟","answer":"لتضرب مشهدًا محسوسًا للحياة الدنيا: تبدأ بالنماء والبهجة ثم تذبل سريعًا وتنتهي فتاتًا، فيرى الإنسان في الزرع أمامه مصير الاغترار بالدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص240، تحت عنوان «دلالة الاستئناف وضرب المثل»","url":""}]},{"id":"s39-40","number":40,"surah":39,"verses":[21],"references":[{"surah":39,"verses":[21]}],"verseLabel":"الزمر: 21","question":"لماذا نُكرت ﴿يَنَابِيعَ﴾ في قوله: ﴿فَسَلَكَهُ يَنَابِيعَ فِي الْأَرْضِ﴾؟","answer":"للدلالة على كثرتها وتنوعها وخفاء مقاديرها؛ فالماء الواحد يسلكه الله عيونًا ومسالك لا يحصيها الناس في أنحاء الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص246، تحت عنوان «غرض تنكير ﴿ينابيع﴾»","url":""}]},{"id":"s39-41","number":41,"surah":39,"verses":[22],"references":[{"surah":39,"verses":[22]}],"verseLabel":"الزمر: 22","question":"ماذا يصور قوله عن المهتدي: ﴿فَهُوَ عَلَى نُورٍ مِنْ رَبِّهِ﴾؟","answer":"يصوّر الهداية نورًا يكشف له الحق ويبدد ظلمة الشك، وإضافة النور إلى ربه تبين أن مصدر بصيرته وهدايته هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص264، تحت عنوان «بلاغة الاستعارة التصريحية في مفردة النور»","url":""}]},{"id":"s39-42","number":42,"surah":39,"verses":[22],"references":[{"surah":39,"verses":[22]}],"verseLabel":"الزمر: 22","question":"لماذا قوبل شرح الصدر للإسلام بقسوة القلب؟","answer":"لأن انشراح الصدر يصور سعة النفس لقبول الحق، بينما القسوة تصور انغلاقها عن التأثر بالذكر؛ فجاء التقابل مختلف اللفظ متكامل الصورة ليكشف حال الهداية والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص267، تحت عنوان «علة اختلاف التقابل في الآية»","url":""}]},{"id":"s39-43","number":43,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا وُصف القرآن بأنه ﴿أَحْسَنَ الْحَدِيثِ﴾؟","answer":"لأنه بلغ الغاية في صدق أخباره وحكمة أحكامه وحسن نظمه وتأثيره، فلا حديث يجمع جمال اللفظ وكمال المعنى والهداية كما يجمعها كلام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص276، تحت عنوان «بلاغة التعبير باسم التفضيل»","url":""}]},{"id":"s39-125","number":125,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"ما دلالة وصف القرآن بأنه كتاب ﴿مُتَشَابِهًا﴾؟","answer":"أي يشبه بعضه بعضًا في الصدق والإحكام والجمال ويصدق بعضه بعضًا؛ فلا تناقض بين أجزائه ولا تفاوت يخرجه عن كماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص277، تحت عنوان «بلاغة وصف القرآن بالتشابه»","url":""}]},{"id":"s39-44","number":44,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا تقشعر جلود الذين يخشون ربهم عند سماع القرآن؟","answer":"لأن الوعيد والجلال يهزانهم حتى يظهر الخوف على ظاهر أجسادهم؛ فالاقشعرار صورة حسية لنفوذ كلام الله من السمع إلى أعماق النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص278، تحت عنوان «بلاغة التعبير بمفردة القشعريرة مادة وصيغة»","url":""}]},{"id":"s39-126","number":126,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا جمع بين الجلود والقلوب في قوله: ﴿ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ﴾؟","answer":"لأن أثر القرآن يشمل الظاهر والباطن: تسكن الجوارح بعد الوجل، وتطمئن القلوب بالرجاء والذكر؛ فجمعهما ليصور تحول الإنسان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص281–282، تحت عنوان «فائدة عطف القلوب على الجلود»","url":""}]},{"id":"s39-45","number":45,"surah":39,"verses":[24],"references":[{"surah":39,"verses":[24]}],"verseLabel":"الزمر: 24","question":"ما الصورة التي يرسمها قوله ﴿أَفَمَنْ يَتَّقِي بِوَجْهِهِ سُوءَ الْعَذَابِ﴾؟","answer":"الوجه أشرف ما يصونه الإنسان، فإذا اتقى به العذاب دل ذلك على نهاية العجز عن دفعه. وتوجه الصورة إلى غل اليدين أو إلى الكناية عن استحالة الوقاية، فتقلب المألوف: ما كان يحمى صار وسيلة اتقاء لا تغني شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص292، تحت عنوان «توجيه تخصيص الوجه بالذكر»","url":""}]},{"id":"s39-46","number":46,"surah":39,"verses":[24],"references":[{"surah":39,"verses":[24]}],"verseLabel":"الزمر: 24","question":"ما غرض الأمر ﴿ذُوقُوا﴾ في مواجهة أهل النار؟","answer":"ليس طلبًا حقيقيًا يملكون رده، بل أمر إهانة وتوبيخ يواجههم بأن العذاب صار واقعًا يباشرونه، وأن زمن الإنذار والاختيار قد انتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص297، تحت عنوان «غرض الأمر ودلالته»","url":""}]},{"id":"s39-47","number":47,"surah":39,"verses":[25,26],"references":[{"surah":39,"verses":[25,26]}],"verseLabel":"الزمر: 25–26","question":"لماذا وُصف عذاب الآخرة بأنه ﴿أَكْبَرُ﴾؟","answer":"لأن عذاب الدنيا محدود زمنًا وقدرًا، أما عذاب الآخرة فأعظم شدة وأبقى أثرًا؛ فاسم التفضيل ينقل السامع من الخزي المشاهد إلى ما هو أهول منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص307، تحت عنوان «لطيفة اسم التفضيل»","url":""}]},{"id":"s39-48","number":48,"surah":39,"verses":[27,28],"references":[{"surah":39,"verses":[27,28]}],"verseLabel":"الزمر: 27–28","question":"ماذا تفيد خاتمة ﴿لَعَلَّهُمْ يَتَّقُونَ﴾ بعد ضرب الأمثال ونفي العوج؟","answer":"تبين أن جمال البيان واستقامته ليسا غاية فنية مجردة، بل طريق إلى يقظة القلب واتقاء الضلال والعذاب؛ ففي الرجاء حث للسامع على الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص319، تحت عنوان «نكتة استعمال أداة الرجاء»","url":""}]},{"id":"s39-49","number":49,"surah":39,"verses":[28],"references":[{"surah":39,"verses":[28]}],"verseLabel":"الزمر: 28","question":"ما دلالة وصف القرآن بأنه ﴿غَيْرَ ذِي عِوَجٍ﴾ بعد وصفه بالعربية؟","answer":"ينفي عنه كل ميل أو تناقض أو اضطراب في ألفاظه ومعانيه؛ فجمع وضوح اللسان مع استقامة المضمون، فلا تبقى شبهة ناشئة من البيان أو المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص318، تحت عنوان «براعة نفي العوج بعد وصف القرآن بالعربي»","url":""}]},{"id":"s39-50","number":50,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"ماذا يصور وصف الشركاء بأنهم ﴿مُتَشَاكِسُونَ﴾؟","answer":"يصورهم شديدي التنازع وسوء الخلق، كل واحد يجذب عبده إلى جهة؛ فيعيش المشرك ممزق القلب لا يدري أي سيد يرضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص326، تحت عنوان «نكتة استعمال مفردة ﴿متشاكسون﴾ مادة وصيغة»","url":""}]},{"id":"s39-127","number":127,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"لماذا قوبل الرجل ذو الشركاء برجل ﴿سَلَمًا لِرَجُلٍ﴾؟","answer":"لأن ﴿سلمًا﴾ تصور عبدًا خالصًا لسيد واحد لا ينازعه فيه أحد؛ فاستقرت وجهته وأوامره، كما يستريح الموحد بإخلاص العبادة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص327، تحت عنوان «دلالة التعبير بـ﴿سلمًا﴾ مادة وصيغة»","url":""}]},{"id":"s39-51","number":51,"surah":39,"verses":[30,31],"references":[{"surah":39,"verses":[30,31]}],"verseLabel":"الزمر: 30–31","question":"ماذا تفيد ﴿ثُمَّ﴾ في الانتقال من موت الرسول ﷺ وموت قومه إلى اختصامهم عند الله؟","answer":"تطوي ما بين الموت والبعث ثم تنقل الجميع إلى موقف الحساب؛ فالموت لا ينهي النزاع بل يؤخر الفصل فيه حتى يقضي الله بينهم بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص335، تحت عنوان «نوع ﴿ثم﴾ ودلالتها»","url":""}]},{"id":"s39-128","number":128,"surah":39,"verses":[30,31],"references":[{"surah":39,"verses":[30,31]}],"verseLabel":"الزمر: 30–31","question":"لماذا قيل: ﴿عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ﴾؟","answer":"اختيرت الربوبية لتذكيرهم بأن الذي رباهم ودبر أمرهم هو الحكم بينهم؛ فلا يضيع عنده حق ولا يخفى عليه ما وقع بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص337، تحت عنوان «سر اختيار لفظ الربوبية»","url":""}]},{"id":"s39-52","number":52,"surah":39,"verses":[32],"references":[{"surah":39,"verses":[32]}],"verseLabel":"الزمر: 32","question":"ماذا يكشف قوله: ﴿وَكَذَّبَ بِالصِّدْقِ إِذْ جَاءَهُ﴾؟","answer":"يكشف أنه بادر إلى تكذيب الحق ساعة وصوله من غير تدبر ولا انتظار؛ فظرف ﴿إذ﴾ يستحضر لحظة المواجهة ويزيد جريمته قبحًا لأن البيان جاءه واضحًا فرده فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص352، تحت عنوان «دلالة التعبير بالظرف ﴿إذ﴾»","url":""}]},{"id":"s39-53","number":53,"surah":39,"verses":[32,33],"references":[{"surah":39,"verses":[32,33]}],"verseLabel":"الزمر: 32–33","question":"لماذا ختم وصف من جاء بالصدق وصدّق به بقوله: ﴿أُولَئِكَ هُمُ الْمُتَّقُونَ﴾؟","answer":"لأن التقوى تجمع الإتيان بالحق وقبوله والعمل بمقتضاه؛ فليس الفضل في حمل الصدق وحده ولا في تصديق بلا التزام، وإنما في موقف كامل يحجز صاحبه عن الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص366، تحت عنوان «سر التعبير بالتقوى دون غيرها في قوله: ﴿المتقون﴾»","url":""}]},{"id":"s39-54","number":54,"surah":39,"verses":[33],"references":[{"surah":39,"verses":[33]}],"verseLabel":"الزمر: 33","question":"لماذا قُدّم ﴿جَاءَ بِالصِّدْقِ﴾ على ﴿وَصَدَّقَ بِهِ﴾؟","answer":"لأن وصول الحق وبيانه سابق في الرتبة على الإيمان به؛ فبدأ بمن يحمله ويبلغه، ثم بمن يتلقاه بالتصديق، فجمع مصدر الهداية ومستجيبها بترتيب طبيعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص363، تحت عنوان «دلالة الترتيب في الآية»","url":""}]},{"id":"s39-55","number":55,"surah":39,"verses":[34,35],"references":[{"surah":39,"verses":[34,35]}],"verseLabel":"الزمر: 34–35","question":"لماذا ذُكر تكفير السيئات بعد قوله: ﴿ذَلِكَ جَزَاءُ الْمُحْسِنِينَ﴾؟","answer":"ليبين أن جزاء الإحسان يجمع دفع المكروه وجلب المحبوب: يمحو الله عنهم آثار السيئات ثم يمنحهم الثواب، فلا يقتصر إحسانه على أحد الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص378، تحت عنوان «دلالة ذكر قوله: ﴿ليكفر الله عنهم﴾ بعد قوله: ﴿ذلك جزاء المحسنين﴾»","url":""}]},{"id":"s39-129","number":129,"surah":39,"verses":[34,35],"references":[{"surah":39,"verses":[34,35]}],"verseLabel":"الزمر: 34–35","question":"ما دلالة المقابلة بين ﴿أَسْوَأَ الَّذِي عَمِلُوا﴾ و﴿بِأَحْسَنِ الَّذِي كَانُوا يَعْمَلُونَ﴾؟","answer":"تظهر سعة الفضل: يمحو أسوأ الذنوب، ثم يجعل معيار الجزاء أحسن الأعمال؛ فلا يعاملهم بالموازنة المجردة بل بالمغفرة والكرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص386، تحت عنوان «بلاغة الطباق بين ﴿أسوأ﴾ و(أحسن)»","url":""}]},{"id":"s39-56","number":56,"surah":39,"verses":[35],"references":[{"surah":39,"verses":[35]}],"verseLabel":"الزمر: 35","question":"لماذا عُبّر عن محو السيئات بقوله: ﴿لِيُكَفِّرَ اللَّهُ عَنْهُمْ﴾؟","answer":"التكفير أصله الستر، ثم استعمل في محو الذنب وإزالة أثره؛ فيصور السيئة وقد غطاها عفو الله فلم تعد تحيط بصاحبها أو تؤاخذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص378–379، تحت عنوان «دلالة التعبير بالتكفير في قوله: ﴿ليكفر﴾»","url":""}]},{"id":"s39-57","number":57,"surah":39,"verses":[36,37],"references":[{"surah":39,"verses":[36,37]}],"verseLabel":"الزمر: 36–37","question":"لماذا قيل: ﴿أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ﴾؟","answer":"اختير وصف الكفاية ليشمل كل ما يحتاج العبد إلى دفعه أو جلبه؛ فمن كفاه الله لم تضره تخويفات المشركين ولا احتاج إلى حماية معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص393، تحت عنوان «سر التعبير بـ (كاف) دون غيره»","url":""}]},{"id":"s39-130","number":130,"surah":39,"verses":[36,37],"references":[{"surah":39,"verses":[36,37]}],"verseLabel":"الزمر: 36–37","question":"ما دلالة المقابلة بين ﴿فَمَا لَهُ مِنْ هَادٍ﴾ و﴿فَمَا لَهُ مِنْ مُضِلٍّ﴾؟","answer":"تقرر انفراد الله بالهداية والإضلال: من خذله فلا أحد يوصله إلى الحق، ومن هداه فلا أحد يقدر أن يصرفه عنه؛ فتسقط أوهام النفع والضر من غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص414، تحت عنوان «بلاغة الطباق ﴿يضلل﴾ و﴿يهد﴾، و﴿هاد﴾، و﴿مضل﴾»","url":""}]},{"id":"s39-58","number":58,"surah":39,"verses":[36,37,38],"references":[{"surah":39,"verses":[36,37,38]}],"verseLabel":"الزمر: 36–38","question":"ما سر التعبير عن الأصنام بضمير الإناث في ﴿هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ﴾؟","answer":"يرد التأنيث إلى أسمائهم للأصنام كاللات والعزى ومناة، أو إلى زعمهم أنها صور ملائكة إناث. ويعيدهم هذا التعبير إلى حقيقة ما سموه وعبدوه، في سياق ينكر قدرتها على كشف الضر أو إمساك الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص441، تحت عنوان «سر التعبير عن الأصنام بالتذكير ثم بالتأنيث»","url":""}]},{"id":"s39-59","number":59,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"لماذا قُدّم دفع الضر على إمساك الرحمة في سؤال المشركين عن معبوداتهم؟","answer":"لأن الخوف من الضر أشد استنفارًا للنفس وأسبق في مقام التحدي، ثم أتبعه بما يطمع فيه الإنسان من الرحمة؛ فاستوعب حالتي الخوف والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص444–445، تحت عنوان «سر تقديم ما يتعلق بدفع الضر على ما يتعلق بإمساك الرحمة»","url":""}]},{"id":"s39-60","number":60,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"لماذا ذُيّل الاحتجاج بقوله: ﴿عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ﴾؟","answer":"ليحوّل نتيجة البرهان إلى قاعدة عامة: من عرف أن الله وحده يكشف الضر ويمسك الرحمة فحقه أن يعتمد عليه، وهذا شأن كل من صدق توكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص450، تحت عنوان «بلاغة التذييل بجملة: ﴿عليه يتوكل المتوكلون﴾»","url":""}]},{"id":"s39-61","number":61,"surah":39,"verses":[39],"references":[{"surah":11,"verses":[93]},{"surah":39,"verses":[39]}],"verseLabel":"الزمر: 39؛ هود: 93","question":"ما دلالة الفاء في قوله بالزمر ﴿فسوف تعلمون﴾؟","answer":"الفاء تفرع العلم بالعاقبة على العمل السابق؛ فاستمرارهم على حالهم سيكشف لهم مآلها. ويجوز ربطها بالأمر بالعمل: اعملوا فسوف تعلمون، فيشتد الوعيد مع تأكيد الرسول ﷺ ثقته بما وعده الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص461، تحت عنوان «دلالة التعبير بالفاء في قوله: ﴿فسوف﴾»","url":""}]},{"id":"s39-62","number":62,"surah":39,"verses":[39,40],"references":[{"surah":39,"verses":[39,40]}],"verseLabel":"الزمر: 39–40","question":"ما الصورة في قوله: ﴿اعْمَلُوا عَلَى مَكَانَتِكُمْ﴾؟","answer":"تصور حالهم الراسخة منزلة يقفون عليها ويعملون منها؛ وفي ذلك تعريض بتمكنهم من العناد مع تحديهم أن يستفرغوا ما يستطيعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص458، تحت عنوان «بلاغة الاستعارة في قوله: ﴿مكانتكم﴾»","url":""}]},{"id":"s39-63","number":63,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"لماذا قيل في وصف القرآن: ﴿نَزَّلَ أَحْسَنَ الْحَدِيثِ﴾ دون: أنزل؟","answer":"صيغة ﴿نزّل﴾ تشعر بالتدرج والتكرار، فتوافق نزول القرآن مفرقًا بحسب الوقائع والحكمة، مع تجدد أثره في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص275، تحت عنوان «دلالة التعبير بـ﴿نزل﴾ دون (أنزل)»","url":""}]},{"id":"s39-131","number":131,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"كيف سُمّي الوحي ﴿الْكِتَابَ﴾ في قوله: ﴿إِنَّا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ﴾؟","answer":"أطلق اسم الكتاب الكامل على ما نزل منه باعتبار ما سيؤول إليه من تمام واجتماع، أو أريد به الجنس؛ فيؤكد أن كل ما يتنزل جزء من كتاب واحد محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص474، تحت عنوان «بلاغة المجاز المرسل في إطلاق: ﴿الكتاب﴾»","url":""}]},{"id":"s39-64","number":64,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"لماذا قيل: ﴿فَمَنِ اهْتَدَى فَلِنَفْسِهِ﴾ بلا ﴿إنما﴾، ثم قيل: ﴿فَإِنَّمَا يَضِلُّ عَلَيْهَا﴾؟","answer":"حُذفت أداة القصر في جانب الهداية لأن اختصاص نفعها بصاحبها مفهوم من مقابلة الضلال، وأُبرز القصر في جانب الضلال لتبرئة الرسول من تبعته وقطع اعتذار من يلقي وزره على غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص481، تحت عنوان «بلاغة الحذف التقابلي في القصر»","url":""}]},{"id":"s39-65","number":65,"surah":39,"verses":[42],"references":[{"surah":39,"verses":[42]}],"verseLabel":"الزمر: 42","question":"لماذا عُبّر عن الموت والنوم معًا بتوفي الأنفس؟","answer":"لأن التوفي هو أخذ الشيء وافيًا؛ فالله يقبض النفس عند الموت قبضًا تامًا، ويقبضها في النوم قبضًا مؤقتًا، فيجمع اللفظ الحالتين ويكشف صلتهما مع اختلاف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص489–490، تحت عنوان «فائدة التعبير ﴿يتوفى﴾ مادة وصيغة»","url":""}]},{"id":"s39-66","number":66,"surah":39,"verses":[42],"references":[{"surah":39,"verses":[42]}],"verseLabel":"الزمر: 42","question":"ماذا تصور المقابلة بين ﴿فَيُمْسِكُ الَّتِي قَضَى عَلَيْهَا الْمَوْتَ﴾ و﴿وَيُرْسِلُ الْأُخْرَى﴾؟","answer":"تصور الأنفس كلها في قبضة الله عند النوم؛ فيحتفظ بما انتهى أجله فلا يعود إلى الجسد، ويطلق الأخرى لتستأنف حياتها، فيظهر سلطان واحد على الموت والبعث اليومي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص497–498، تحت عنوان «بلاغة الطباق بين ﴿فيمسك﴾، و﴿ويرسل﴾»","url":""}]},{"id":"s39-67","number":67,"surah":39,"verses":[43,44],"references":[{"surah":39,"verses":[43,44]}],"verseLabel":"الزمر: 43–44","question":"لماذا قُدّم ﴿لِلَّهِ﴾ في قوله: ﴿قُلْ لِلَّهِ الشَّفَاعَةُ﴾؟","answer":"لقصر ملك الشفاعة وإذنها على الله وحده، فلا يملكها شفيع استقلالًا ولا تقع إلا لمن أذن له ورضي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص520، تحت عنوان «دلالة تقديم شبه الجملة ﴿لله﴾»","url":""}]},{"id":"s39-132","number":132,"surah":39,"verses":[43,44],"references":[{"surah":39,"verses":[43,44]}],"verseLabel":"الزمر: 43–44","question":"ماذا يضيف قوله: ﴿الشَّفَاعَةُ جَمِيعًا﴾؟","answer":"يزيل كل احتمال لاستثناء نوع أو قدر منها؛ فكل شفاعة بلا استثناء داخلة في ملك الله وإذنه، لا بعض الشفاعة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص521، تحت عنوان «موقع قوله: ﴿جميعًا﴾ وأثره في البيان»","url":""}]},{"id":"s39-68","number":68,"surah":39,"verses":[43],"references":[{"surah":39,"verses":[43]}],"verseLabel":"الزمر: 43","question":"لماذا احتج على بطلان شفاعة الأصنام بأنها لا تملك شيئًا ولا تعقل؟","answer":"لأن الشفيع لا بد أن يملك قدرة على النفع ووعيًا بمن يشفع له وما يطلبه؛ فإذا انتفى عن الأصنام الملك والعقل انتفى أصل صلاحيتها للشفاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص518، تحت عنوان «بلاغة الكناية في نفي الملك والعقل خاصة»","url":""}]},{"id":"s39-69","number":69,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ماذا يصوّر اختيار ﴿اشْمَأَزَّتْ﴾ لنفور غير المؤمنين عند ذكر الله وحده؟","answer":"يصور نفورًا شديدًا يصحبه انقباض واضطراب، لا مجرد كراهية عابرة؛ فمادة الكلمة وصيغتها تستحضران حركة نفسية عنيفة تكشف شدة بغضهم للتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص529–530، تحت عنوان «دلالة التعبير ﴿اشمأزت﴾ مادة وصيغة»","url":""}]},{"id":"s39-70","number":70,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ما الذي تضيفه ﴿إِذَا﴾ في قوله: ﴿إِذَا هُمْ يَسْتَبْشِرُونَ﴾؟","answer":"تفيد المفاجأة وسرعة ظهور فرحهم بمجرد ذكر معبوداتهم؛ فكأن الانتقال من الذكر إلى الاستبشار يقع فورًا، مما يكشف شدة تعلقهم بها وغرابة انقلاب حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص537، تحت عنوان «معنى (إذا)»","url":""}]},{"id":"s39-133","number":133,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ماذا تكشف مقابلة ﴿اشْمَأَزَّتْ﴾ بـ﴿يَسْتَبْشِرُونَ﴾؟","answer":"تضع غاية النفور من ذكر الله وحده بإزاء غاية الفرح بذكر من دونه؛ فيبرز الطباق انقلاب فطرتهم وتمام التباعد بين الحالتين: انقباض القلب هناك وامتلاؤه سرورًا هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص539، تحت عنوان «بلاغة الطباق بين الحالتين»","url":""}]},{"id":"s39-71","number":71,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا انتقل السياق من مجادلة المشركين إلى الدعاء: ﴿اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"ليقطع الجدال العقيم بالتضرع إلى المرجع الأعلى الذي خلق الكون ويعلم السر والعلن ويحكم بين المختلفين؛ فالفصل ينقل المقام من الاحتجاج على عنادهم إلى تفويض الفصل لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص543، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s39-134","number":134,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا جاء قوله: ﴿أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ﴾ بصيغة الخبر مع أنه في سياق الدعاء؟","answer":"لإظهار اليقين بأن حكم الله واقع لا محالة، حتى صيغ المطلوب في صورة حقيقة ثابتة؛ وفيه تفويض كامل واعتراف بأن الفصل بين المختلفين إليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص549، تحت عنوان «نكتة مجيء: ﴿أنت تحكم﴾ بصيغة الخبر لا الإنشاء»","url":""}]},{"id":"s39-72","number":72,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا قُدّم وصف الله بـ﴿فَاطِرِ﴾ على وصفه بـ﴿عَالِمِ﴾؟","answer":"لأن آثار القدرة في الخلق أظهر للمخاطبين وأسبق إلى إدراكهم، ولأن مقام الفصل بين المختلفين يقتضي أولًا القدرة التامة على إنفاذ الحكم؛ ثم جاء العلم ليقرر إحاطته بما يحكم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص547–548، تحت عنوان «نكتة تقديم صفة ﴿فاطر﴾ على ﴿عالم﴾»","url":""}]},{"id":"s39-73","number":73,"surah":39,"verses":[47,48],"references":[{"surah":39,"verses":[47,48]}],"verseLabel":"الزمر: 47–48","question":"لماذا تكرر قوله: ﴿وَبَدَا لَهُمْ﴾ في مشهد الحساب؟","answer":"لأن الظهور الثاني ليس تكرارًا خاليًا من الزيادة؛ فالأول يكشف لهم من الله ما لم يحتسبوا، والثاني يصرح بظهور سيئات أعمالهم وآثارها، فيتجدد التهويل مع كل حقيقة تنكشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص570، تحت عنوان «سر تكرير فعل (بدا)»","url":""}]},{"id":"s39-74","number":74,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"لماذا قيل: ﴿مَا فِي الْأَرْضِ جَمِيعًا﴾ في فداء الظالمين؟","answer":"لتستغرق الصورة كل ما في الأرض بلا استثناء؛ فيتخيل السامع أن الظالم يملك ثرواتها كلها ثم يبذلها للنجاة، ومع ذلك لا تنفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص559، تحت عنوان «سر التوكيد بالحال ﴿جميعًا﴾»","url":""}]},{"id":"s39-135","number":135,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"لماذا زيد على ما في الأرض قوله: ﴿وَمِثْلَهُ مَعَهُ﴾؟","answer":"لمضاعفة الفداء المفروض إلى أبعد ما يتصوره الإنسان؛ فحتى لو اجتمع له كل ما في الأرض ومثله معه لبذله، ومع هذا يبقى عاجزًا عن دفع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص559، تحت عنوان «نكتة التعبير بالمثلية: ﴿ومثله﴾»","url":""}]},{"id":"s39-136","number":136,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"ما الصورة التي يرسمها شرط افتداء الظالم بكل ما في الأرض؟","answer":"يمثل حالهم بحال أسير رأى الهلاك فقدم أعظم فدية ممكنة طلبًا للنجاة، ثم لم تقبل منه؛ فتجسد الشرطية شدة الفزع واليأس من كل وسيلة خلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص562، تحت عنوان «بلاغة الاستعارة التمثيلية في مضمون الشرطية»","url":""}]},{"id":"s39-75","number":75,"surah":39,"verses":[49,50,51],"references":[{"surah":39,"verses":[49,50,51]}],"verseLabel":"الزمر: 49–51","question":"لماذا قيل: ﴿مَسَّ الْإِنْسَانَ ضُرٌّ﴾؟","answer":"لأن المس يوحي بأدنى إصابة؛ فإذا كان مجرد مس الضر يدفع الإنسان إلى دعاء الله، كان نسيانه بعد كشفه أشد كشفًا لتقلبه وجحوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص580، تحت عنوان «بلاغة التعبير بالمس دون غيره»","url":""}]},{"id":"s39-137","number":137,"surah":39,"verses":[49,50,51],"references":[{"surah":39,"verses":[49,50,51]}],"verseLabel":"الزمر: 49–51","question":"لماذا قيل عن دعوى الإنسان: ﴿قَدْ قَالَهَا الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"ليرد غروره إلى شبهة قديمة كررها الهالكون قبله؛ فليست مقالته دليل تفوق ولا اكتشافًا، وقد شهد مصير السابقين بأن ما كسبوه لم يغن عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص595، تحت عنوان «نكتة فصل ﴿قد قالها﴾»","url":""}]},{"id":"s39-76","number":76,"surah":39,"verses":[49],"references":[{"surah":39,"verses":[49]}],"verseLabel":"الزمر: 49","question":"ماذا يفيد وصف النعمة بأنها ﴿مِنَّا﴾؟","answer":"يصرح بأن مصدرها تفضل الله لا استحقاق الإنسان، فيمهد لكشف جحوده حين ينسبها بعد ذلك إلى علمه؛ فالكلمة ترد النعمة إلى واهبها الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص584، تحت عنوان «بلاغة الوصف بقوله ﴿منا﴾»","url":""}]},{"id":"s39-77","number":77,"surah":39,"verses":[51],"references":[{"surah":39,"verses":[51]}],"verseLabel":"الزمر: 51","question":"لماذا أشار إلى الظالمين المعاصرين بقوله: ﴿وَالَّذِينَ ظَلَمُوا مِنْ هَؤُلَاءِ﴾؟","answer":"لتعيين المخاطبين الحاضرين وتوجيه الوعيد إليهم مباشرة؛ فلا يظنوا أن قصة السابقين بعيدة عنهم، فهم يسلكون طريقهم ومهددون بمصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص603، تحت عنوان «نكتة التعبير باسم الإشارة»","url":""}]},{"id":"s39-138","number":138,"surah":39,"verses":[51],"references":[{"surah":39,"verses":[51]}],"verseLabel":"الزمر: 51","question":"ماذا تفيد السين في قوله: ﴿سَيُصِيبُهُمْ سَيِّئَاتُ مَا كَسَبُوا﴾؟","answer":"تجعل جزاءهم الآتي قريب الوقوع محققًا، وتصل حاضرهم بمصير من قبلهم؛ فتأخر العقوبة لا يعني الإفلات منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص604، تحت عنوان «فائدة السين في ﴿سيصيبهم﴾»","url":""}]},{"id":"s39-78","number":78,"surah":39,"verses":[52],"references":[{"surah":39,"verses":[52]}],"verseLabel":"الزمر: 52","question":"ما سر ذكر الرزق مع البسط وحذفه مع التقدير في ﴿يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ﴾؟","answer":"حذف متعلق ﴿ويقدر﴾ لدلالة ما قبله عليه؛ أي يقدر الرزق لمن يشاء. ففيه إيجاز يجمع البسط والتضييق في تدبير واحد، ويترك السياق يغني عن إعادة لفظ الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص613، تحت عنوان «بلاغة حذف متعلق ﴿ويقدر﴾»","url":""}]},{"id":"s39-79","number":79,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"لماذا قيل عن المسرفين: ﴿أَسْرَفُوا عَلَى أَنْفُسِهِمْ﴾؟","answer":"لأن وبال المعصية راجع إليهم لا إلى غيرهم؛ فالتعبير يوقظهم إلى أنهم تجاوزوا الحد بما يضر أنفسهم، وفي الوقت نفسه يدعوهم إلى إنقاذها بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص622–623، تحت عنوان «سر تخصيص ضرر الإسراف ﴿على أنفسهم﴾»","url":""}]},{"id":"s39-80","number":80,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ماذا يصنع النهي ﴿لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ﴾ في نفس المذنب؟","answer":"يقطع طريق اليأس الذي يمنعه من التوبة، ويحوّل اعترافه بالإسراف إلى رجاء وعمل؛ فليس المقصود تهوين الذنب بل فتح باب العودة إلى رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص623، تحت عنوان «دلالة النهي في ﴿لا تقنطوا﴾»","url":""}]},{"id":"s39-139","number":139,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ماذا تضيف ﴿جَمِيعًا﴾ في قوله: ﴿إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا﴾؟","answer":"تؤكد استغراق المغفرة للذنوب عند تحقق التوبة، فلا يستعظم العائد ذنبًا على عفو الله؛ وبذلك تبلغ آية الرجاء غايتها من غير أن تكون ترخيصًا في الإصرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص626، تحت عنوان «بلاغة الحال بلفظ ﴿جميعًا﴾»","url":""}]},{"id":"s39-81","number":81,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ما مناسبة تقديم ﴿الْغَفُورُ﴾ على ﴿الرَّحِيمُ﴾ في آية الرجاء؟","answer":"المغفرة تزيل موجب العقاب، والرحمة تحصل بها أسباب الثواب؛ فقدم ما يدفع الضرر على ما يجلب النفع. والمغفرة نفسها من آثار الرحمة، فجاء ترتيب الوصفين ملائمًا لمقام المذنب المدعو إلى الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص627، تحت عنوان «علة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s39-82","number":82,"surah":39,"verses":[54,55],"references":[{"surah":39,"verses":[54,55]}],"verseLabel":"الزمر: 54–55","question":"لماذا جاء الأمر بالإسلام بعد الأمر بالإنابة؟","answer":"لأن الإنابة رجوع القلب عن المعصية، ثم يترجم الإسلام هذا الرجوع خضوعًا وإخلاصًا لله؛ فانتقل من توجه الباطن إلى استسلام العبد في اعتقاده وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص631، تحت عنوان «دلالة الأمر بالإسلام في السياق»","url":""}]},{"id":"s39-140","number":140,"surah":39,"verses":[54,55],"references":[{"surah":39,"verses":[54,55]}],"verseLabel":"الزمر: 54–55","question":"لماذا قيل بعد الإنابة والإسلام: ﴿وَاتَّبِعُوا أَحْسَنَ مَا أُنْزِلَ إِلَيْكُمْ﴾؟","answer":"لأن صدق الرجوع لا يقف عند الشعور والإقرار، بل يظهر في اتباع الوحي والعمل به؛ فعطف الاتباع يستكمل طريق التوبة بالطاعة العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص636، تحت عنوان «بلاغة عطف جملة ﴿واتبعوا﴾»","url":""}]},{"id":"s39-83","number":83,"surah":39,"verses":[56],"references":[{"surah":39,"verses":[56]}],"verseLabel":"الزمر: 56","question":"ماذا يكشف قول النفس: ﴿فَرَّطْتُ﴾؟","answer":"يكشف أنها قصرت وضيعت ما كان في قدرتها فعله، لا أنها عجزت عنه؛ فلفظ التفريط يحمل اعترافًا بالمسؤولية عن الفرصة المهدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص647، تحت عنوان «دلالة التعبير بلفظ (التفريط) ﴿فرطت﴾»","url":""}]},{"id":"s39-84","number":84,"surah":39,"verses":[56],"references":[{"surah":39,"verses":[56]}],"verseLabel":"الزمر: 56","question":"لماذا عُبّر عن حق الله وطاعته بقوله: ﴿فِي جَنْبِ اللَّهِ﴾؟","answer":"لأن الجنب استُعمل كناية عن جهة الحق والطاعة والقرب؛ فتصور النفس نفسها وقد أهملت الجانب الذي كان ينبغي أن تلزمه، وإضافته إلى الله تعظم مقدار ما ضيعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص648، تحت عنوان «سر التعبير بلفظ (الجنب)»","url":""}]},{"id":"s39-85","number":85,"surah":39,"verses":[56,57,58],"references":[{"surah":39,"verses":[56,57,58]}],"verseLabel":"الزمر: 56–58","question":"ما دلالة ترتيب أعذار النفس من الحسرة على التفريط إلى تمني الهداية ثم تمني الرجعة؟","answer":"تبدأ النفس بالتحسر على تقصيرها، ثم تنتقل إلى التعلل بفقد الهداية، ثم تطلب الرجوع للعمل الصالح. ويربط هذا الترتيب أقوالها بما يتتابع عليها من انكشاف الحق ومشاهدة العذاب، فتتنقل بين الاعتراف والاعتذار والتمني حين لا ينفعها ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص657، تحت عنوان «نكتة التقديم بين الأقوال»","url":""}]},{"id":"s39-86","number":86,"surah":39,"verses":[58],"references":[{"surah":39,"verses":[58]}],"verseLabel":"الزمر: 58","question":"لماذا قُيّد تمني الرجعة وحده بقوله: ﴿حِينَ تَرَى الْعَذَابَ﴾ دون القولين السابقين؟","answer":"لأن الحسرة على التفريط والتعلل بفقد الهداية يبدآن قبل المعاينة، أما طلب الرجعة فلا ينفجر إلا حين ترى النفس العذاب وتدرك أن زمن العمل انتهى؛ فالقيد يوضح تدرج أقوالها بحسب انكشاف المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص659، تحت عنوان «سر الاختصاص بالقيد»","url":""}]},{"id":"s39-87","number":87,"surah":39,"verses":[59],"references":[{"surah":39,"verses":[59]}],"verseLabel":"الزمر: 59","question":"لماذا خُصّ قول النفس الثاني بالرد: ﴿بَلَى قَدْ جَاءَتْكَ آيَاتِي﴾؟","answer":"لأن قولها: لو أن الله هداني، يتضمن إلقاء تبعة الضلال على غيرها؛ فجاء الرد ليبطل هذه الدعوى ويثبت أن آيات الهداية بلغتها فكذبت واستكبرت.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص665–666، تحت عنوان «سر تخصيص القول الثاني للنفس بالرد»","url":""}]},{"id":"s39-141","number":141,"surah":39,"verses":[59],"references":[{"surah":39,"verses":[59]}],"verseLabel":"الزمر: 59","question":"لماذا قيل: ﴿وَكُنْتَ مِنَ الْكَافِرِينَ﴾ بدل: وكنت كافرًا؟","answer":"لإدخالها في جماعة رسخت فيهم صفة الكفر واتخذته طريقًا، لا وصف حال عابر؛ فينكشف أن مصيرها ثمرة اختيار متكرر وانتماء إلى أهل التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص674، تحت عنوان «سر العدول عن الإفراد إلى الجمع»","url":""}]},{"id":"s39-88","number":88,"surah":39,"verses":[60],"references":[{"surah":39,"verses":[60]}],"verseLabel":"الزمر: 60","question":"ماذا يصوّر اسوداد وجوه المكذبين يوم القيامة؟","answer":"يصور الذلة والكآبة والفضيحة التي تغشاهم، سواء حمل السواد على تغير حقيقي في اللون أو على الكناية عن شدة الخزي؛ وفي الحالين يتحول الباطن المظلم إلى أثر مشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص682، تحت عنوان «اسوداد الوجوه بين الحقيقة والكناية»","url":""}]},{"id":"s39-89","number":89,"surah":39,"verses":[60],"references":[{"surah":39,"verses":[60]}],"verseLabel":"الزمر: 60","question":"لماذا عُيّن مأوى المتكبرين باسم ﴿جَهَنَّمَ﴾؟","answer":"لأن الاسم يستحضر النار المحيطة الشديدة، ويلائم جرمهم: قابلوا آيات الله بالكذب والتكبر، فقوبل استعلاؤهم بمأوى يحيط بهم ويذلهم؛ فالجزاء من جنس العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص683، تحت عنوان «علة التعبير بـ: ﴿جهنم﴾»","url":""}]},{"id":"s39-90","number":90,"surah":39,"verses":[61],"references":[{"surah":39,"verses":[61]}],"verseLabel":"الزمر: 61","question":"لماذا لم يذكر ما الذي يُنَجَّى منه المتقون في قوله: ﴿وَيُنَجِّي اللَّهُ الَّذِينَ اتَّقَوْا﴾؟","answer":"لأن جهنم حاضرة بقوة في الآية السابقة، ففهم منها المحذوف من غير تصريح؛ كما يوسع الحذف الوعد ليشمل إنجاءهم من جهنم ومن كل ما يقود إليها من الكذب والتكبر والشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص690، تحت عنوان «سر حذف معمولي التنجية والتقوى»","url":""}]},{"id":"s39-91","number":91,"surah":39,"verses":[61],"references":[{"surah":39,"verses":[61]}],"verseLabel":"الزمر: 61","question":"لماذا قُدّم ﴿لَا يَمَسُّهُمُ السُّوءُ﴾ على ﴿وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"لأن انتفاء السوء أصل في انتفاء الحزن الناشئ عنه، فقدم السبب ثم أتبعه بأثره النفسي؛ وبذلك جمع الوعد بين السلامة من المكروه في الخارج وطمأنينة القلب في الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص695–696، تحت عنوان «نكتة تقديم جملة: ﴿لا يمسهم السوء﴾»","url":""}]},{"id":"s39-92","number":92,"surah":39,"verses":[62,63],"references":[{"surah":39,"verses":[62,63]}],"verseLabel":"الزمر: 62–63","question":"لماذا قُدِّم قوله ﴿اللَّهُ خَالِقُ كُلِّ شَيْءٍ﴾ على ﴿وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ﴾؟","answer":"لأن الخلق أصل ما بعده؛ فالله أوجد الأشياء أولًا ثم تولى حفظها وتدبيرها. كما أن تقديم انفراده بالخلق أنسب بمقام الرد على المشركين وإقامة الحجة على إفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص701–702، تحت عنوان «نكتة تقديم جملة: ﴿الله خالق كل شيء﴾»","url":""}]},{"id":"s39-93","number":93,"surah":39,"verses":[63],"references":[{"surah":39,"verses":[63]}],"verseLabel":"الزمر: 63","question":"ما الصورة التي يرسمها قوله ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"يصور خزائن السماوات والأرض ومفاتيحها بيده وحده؛ فما فيها من أرزاق وتدبير وتصرف داخل في ملكه وقدرته، ولا يملك أحد سواه فتح شيء منها أو منعه استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص708–709، تحت عنوان «علة التعبير بـ: ﴿مقاليد﴾»","url":""}]},{"id":"s39-94","number":94,"surah":39,"verses":[64],"references":[{"surah":39,"verses":[64]}],"verseLabel":"الزمر: 64","question":"لماذا قال ﴿أَفَغَيْرَ اللَّهِ﴾ ولم يسمِّ معبودات المشركين؟","answer":"ليعم الإنكار كل ما سوى الله بلا استثناء؛ فبعد ثبوت انفراده بالخلق والتدبير تصبح عبادة أي موجود غيره باطلة، مهما اختلف اسمه أو صورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص720، تحت عنوان «سر العدول عن ذكر معبودات الكفار»","url":""}]},{"id":"s39-95","number":95,"surah":39,"verses":[64],"references":[{"surah":39,"verses":[64]}],"verseLabel":"الزمر: 64","question":"لماذا وُصف الداعون إلى عبادة غير الله بأنهم ﴿الْجَاهِلُونَ﴾؟","answer":"لأن دعوتهم تناقض أوضح دلائل التوحيد؛ فقد جهلوا عظمة الله واستحقاقه العبادة وحده، وجهلوا قبح ما يدعون إليه، فجاء الوصف توبيخًا لهم على هذا العمى بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص724–725، تحت عنوان «علة التعبير بالجهل»","url":""}]},{"id":"s39-96","number":96,"surah":39,"verses":[65],"references":[{"surah":39,"verses":[65]}],"verseLabel":"الزمر: 65","question":"كيف يُوجَّه التحذير من الشرك إلى النبي ﷺ وهو معصوم منه؟","answer":"الشرط يفرض الممتنع لبيان فداحة الشرك وأنه يحبط العمل مهما عظم صاحبه، لا ليدل على إمكان وقوعه من النبي ﷺ. وفي توجيه الخطاب إليه تغليظ للإنذار وتعريض بمن يشرك من أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص733، تحت عنوان «بلاغة أسلوب الشرط»","url":""}]},{"id":"s39-97","number":97,"surah":39,"verses":[65],"references":[{"surah":39,"verses":[65]}],"verseLabel":"الزمر: 65","question":"ما الذي يصوره لفظ ﴿لَيَحْبَطَنَّ عَمَلُكَ﴾ عن أثر الشرك؟","answer":"يصور بطلان العمل وذهاب أثره وثوابه حتى يصير كأنه لم يكن؛ فالشرك لا ينقص قيمة العمل فحسب، بل يهدم أساس قبوله كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص735، تحت عنوان «علة التعبير بالحبط مادة وصيغة»","url":""}]},{"id":"s39-98","number":98,"surah":39,"verses":[66],"references":[{"surah":39,"verses":[66]}],"verseLabel":"الزمر: 66","question":"لماذا قُدِّم الأمر بعبادة الله على الأمر بشكره في ﴿بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ﴾؟","answer":"لأن إفراد الله بالعبادة هو المقصود الأول في مقام إبطال الشرك، ثم يأتي الشكر ثمرةً لذلك واعترافًا بنعمة الهداية إلى التوحيد والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص744، تحت عنوان «نكتة تقديم الأمر بالعبادة على الأمر بالشكر»","url":""}]},{"id":"s39-99","number":99,"surah":39,"verses":[67],"references":[{"surah":39,"verses":[67]}],"verseLabel":"الزمر: 67","question":"لماذا جاء مشهد الأرض في قبضته والسماوات مطويات بيمينه عقب قوله ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾؟","answer":"ليجعل عظمة قدرة الله مشهدًا كاشفًا لسوء تقديرهم؛ فمن كانت الأرض كلها في قبضته والسماوات مطويات بيمينه لا يليق أن يُجعل له شريك، فيتضاعف التوبيخ على شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص751–752، تحت عنوان «بلاغة جملة الحال»","url":""}]},{"id":"s39-100","number":100,"surah":39,"verses":[67],"references":[{"surah":39,"verses":[67]}],"verseLabel":"الزمر: 67","question":"لماذا قيل ﴿وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ﴾ مع أن لفظ الأرض يشملها؟","answer":"لإزالة أي توهم بأن شيئًا من الأرض يخرج عن سلطان الله؛ فكل أجزائها وأقطارها مجتمعة في قبضته يوم القيامة، لا يستعصي منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص752، تحت عنوان «علة التعبير بـ: ﴿جميعًا﴾»","url":""}]},{"id":"s39-101","number":101,"surah":39,"verses":[68],"references":[{"surah":39,"verses":[68]}],"verseLabel":"الزمر: 68","question":"لماذا أُعيد فعل ﴿نُفِخَ﴾ عند النفخة الثانية؟","answer":"لتمييز النفختين وإبراز استقلال أثر كل واحدة: الأولى نفخة الصعق، والثانية نفخة البعث والقيام. فإعادة الفعل تمنع توهم أن المذكور أثر واحد لنفخة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص766، تحت عنوان «فائدة إعادة فعل ﴿نفخ﴾ مرة ثانية»","url":""}]},{"id":"s39-102","number":102,"surah":39,"verses":[68],"references":[{"surah":39,"verses":[68]}],"verseLabel":"الزمر: 68","question":"ما دلالة ﴿ثم نفخ فيه أخرى﴾، وما أثر حذف موصوف ﴿أخرى﴾؟","answer":"﴿أخرى﴾ صفة لمصدر محذوف، أي نفخة أخرى. وحذف الموصوف إيجاز يدل عليه فعل النفخ، وذكر الصفة يبرز مغايرة هذه النفخة للأولى في أثرها: فبعد الصعق يكون القيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص766، تحت عنوان «بلاغة استعمال مفردة ﴿أخرى﴾»","url":""}]},{"id":"s39-103","number":103,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"ما الذي تضيفه كلمة ﴿أَشْرَقَتِ﴾ إلى مشهد أرض القيامة؟","answer":"تصور نورًا قويًا منتشرًا يملأ أرض المحشر كلها، لا مجرد ضوء محدود؛ فتفتتح مشهد القضاء بانكشاف تام يليق بظهور الحق والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص774–775، تحت عنوان «بلاغة استعمال مفردة الإشراق»","url":""}]},{"id":"s39-142","number":142,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"لماذا رُتبت أحداث القضاء من وضع الكتاب إلى مجيء النبيين والشهداء ثم الحكم؟","answer":"ليجري المشهد على ترتيب المحاكمة الكاملة: تُعرض السجلات، وتقام الشهادة، ثم يصدر الحكم بالحق؛ فيظهر أن الجزاء قائم على حجة ظاهرة وعدل تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص784، تحت عنوان «براعة ترتيب الأحداث في مشهد القضاء»","url":""}]},{"id":"s39-143","number":143,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"لماذا ذُكرت توفية كل نفس بعد القضاء بين العباد بالحق؟","answer":"لأن التوفية ثمرة القضاء ومرحلته التنفيذية؛ فبعد ثبوت الحكم يأخذ كل إنسان جزاء عمله كاملًا، فيظهر اتصال الحكم العادل بتحققه من غير نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص787، تحت عنوان «نكتة عطف التوفية على القضاء بين العباد»","url":""}]},{"id":"s39-104","number":104,"surah":39,"verses":[69],"references":[{"surah":39,"verses":[69]}],"verseLabel":"الزمر: 69","question":"ما سر تقديم وضع الكتاب على الإتيان بالنبيين والشهداء؟","answer":"قدم الكتاب لأنه يجمع ما ضبط من الأعمال، فيعرض الأصل الذي تتعلق به الشهادة. ثم يحضر النبيون والشهداء فتظهر الحجة على العباد على أكمل وجه، مع أن الله غني بعلمه عن شهادة الشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص780–781، تحت عنوان «نكتة تقديم وضع الكتاب على الإتيان بالنبيين»","url":""}]},{"id":"s39-105","number":105,"surah":39,"verses":[19,71],"references":[{"surah":39,"verses":[19,71]}],"verseLabel":"الزمر: 19، 71","question":"لماذا قيل ﴿حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ﴾ ولم يقل «صدق عليه»؟","answer":"لأن ﴿حق﴾ تدل على ثبوت الحكم ووجوبه ولزومه بعد قيام أسبابه، وهو الأنسب لعذاب استقر استحقاق صاحبه له؛ أما الصدق فيتجه أساسًا إلى مطابقة الخبر للواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص218–219، تحت عنوان «نكتة التعبير بلفظ ﴿حق﴾ دون (صدق)»","url":""}]},{"id":"s39-144","number":144,"surah":39,"verses":[19,71],"references":[{"surah":39,"verses":[19,71]}],"verseLabel":"الزمر: 19، 71","question":"لماذا سُمِّي العذاب في قوله ﴿حَقَّتْ كَلِمَةُ الْعَذَابِ﴾ كلمةً؟","answer":"لأن العذاب ثبت وتقرر بكلمة الله وقضائه، فأُطلق اسم الكلمة على ما نتج عنها من حكم وعقوبة؛ وفي ذلك تصوير لسرعة نفاذ قضائه وارتباط المصير بوعده الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص813، تحت عنوان «فصاحة التعبير المجازي في لفظ ﴿كلمة﴾»","url":""}]},{"id":"s39-106","number":106,"surah":39,"verses":[71,73],"references":[{"surah":39,"verses":[71,73]}],"verseLabel":"الزمر: 71، 73","question":"لماذا استُعمل الفعل نفسه ﴿سِيقَ﴾ للكافرين إلى النار وللمتقين إلى الجنة؟","answer":"جاء في المتقين على سبيل المشاكلة اللفظية بين المشهدين، لا لتساوي الحالين؛ فسوق الكافرين إهانة ودفع، أما المتقون فيتقدمون إلى الجنة مكرمين، وباتحاد اللفظ يبرز اختلاف المصيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص12، تحت عنوان «بلاغة المشاكلة في مفردة (سيق)»","url":""}]},{"id":"s39-107","number":107,"surah":39,"verses":[71,73],"references":[{"surah":39,"verses":[71,73]}],"verseLabel":"الزمر: 71، 73","question":"ما الذي توحي به الواو في ﴿وَفُتِحَتْ أَبْوَابُهَا﴾ عند وصول المتقين إلى الجنة؟","answer":"من أوجهها أنها واو الحال؛ أي جاء المتقون وقد فُتحت الأبواب لاستقبالهم، بخلاف فتح أبواب النار عند وصول أهلها. ويورد المبحث أوجهًا أخرى، فلا تُحصر دلالتها في تفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص14–15، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s39-108","number":108,"surah":39,"verses":[71,72],"references":[{"surah":39,"verses":[71,72]}],"verseLabel":"الزمر: 71–72","question":"لماذا قيل للكافرين ﴿ادْخُلُوا أَبْوَابَ جَهَنَّمَ﴾ بعد اعترافهم بمجيء الرسل؟","answer":"ليأتي الحكم عقب الإقرار بالحجة؛ والأمر هنا للإهانة والتقريع لا للتكليف، فيدخلونها عالمين أن مصيرهم نتيجة تكذيبهم بعد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص815، تحت عنوان «غرض الأمر ﴿ادخلوا﴾»","url":""}]},{"id":"s39-109","number":109,"surah":39,"verses":[72],"references":[{"surah":39,"verses":[72]}],"verseLabel":"الزمر: 72","question":"ما مناسبة وصف أهل النار بالمتكبرين في ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾؟","answer":"اختير وصف المتكبرين لأنه يبين الدافع إلى كفرهم: استعلاؤهم عن توحيد الله وإفراده بالعبادة وقبول آياته. فبعد ذكر كفرهم صرح بعلته، وجاء ذم المثوى ملائمًا لهذا الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص817–818، تحت عنوان «نكتة اختيار لفظ ﴿المتكبرين﴾ دون (الكافرين)»","url":""}]},{"id":"s39-110","number":110,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"ماذا تتضمن تحية خزنة الجنة للمتقين بقولهم ﴿طِبْتُمْ﴾؟","answer":"تتضمن الثناء والتكريم: طابت نفوسهم بالإيمان وأعمالهم بالطاعة، وطاب لهم الآن مقامهم ونعيمهم؛ فهي كلمة تجمع طهارة الطريق وطيب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص18، تحت عنوان «بلاغة استعمال مفردة ﴿طبتم﴾»","url":""}]},{"id":"s39-145","number":145,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"لماذا قيل لأهل الجنة عند دخولها ﴿خَالِدِينَ﴾؟","answer":"ليكتمل الترحيب بإزالة آخر ما قد ينغص الفرح: فالنعيم ليس إقامة مؤقتة يخشى انقطاعها، بل خلود دائم يطمئنون معه إلى بقاء ما نالوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص19، تحت عنوان «فائدة الحال ﴿خالدين﴾»","url":""}]},{"id":"s39-111","number":111,"surah":39,"verses":[74],"references":[{"surah":39,"verses":[74]}],"verseLabel":"الزمر: 74","question":"لماذا بدأ أهل الجنة بحمد الله على صدق وعده قبل ذكر توريث الأرض؟","answer":"لأن صدق الوعد هو الأصل الجامع لكل ما نالوه، ثم جاء توريث الأرض وحرية التبوؤ تفصيلًا لتحقق ذلك الوعد؛ فبدأوا بالنعمة الكبرى قبل آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص24، تحت عنوان «نكتة تقديم صدق الوعد على توريث الأرض»","url":""}]},{"id":"s39-112","number":112,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"ما سر التعبير بـ﴿حَافِّينَ مِنْ حَوْلِ الْعَرْشِ﴾ دون «حافين حول العرش»؟","answer":"يعرض المبحث في ﴿من﴾ توجيهات: الزيادة للتوكيد، أو التبعيض، أو ابتداء الغاية، ويرجح في عرضه الأخير ابتداء الحف من جوانب العرش. وعلى هذا يبرز اللفظ منشأ الإحاطة وامتدادها، دون أن يلزم منه تقرير هيئة تفصيلية لصفوف الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص34–35، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من حول﴾»","url":""}]},{"id":"s39-113","number":113,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"لماذا قُدِّم التسبيح على الحمد في وصف الملائكة ﴿يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ﴾؟","answer":"لأن تنزيه الله عن النقص يسبق إثبات صفات الكمال له؛ فالتسبيح تخليَة من كل عيب، والحمد تحليَة بكل جميل، وباجتماعهما يكتمل الثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص37، تحت عنوان «غرض تقديم التسبيح على الحمد»","url":""}]},{"id":"s39-114","number":114,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"من القائل ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ في ختام مشهد القيامة؟","answer":"حُذف القائل ليشيع الحمد كأنه نطق به الكون كله بعد ظهور عدل الله، ويجوز أن يكون من قول الملائكة والمؤمنين؛ فالمقصود تعميم الثناء لا تعيين صوت واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص41–42، تحت عنوان «نكتة بناء ﴿وقيل﴾ للمفعول»","url":""}]},{"id":"s39-115","number":115,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"ما مناسبة ختم السورة بقوله ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾؟","answer":"يختم الحمد مشهد القضاء بالحق وإيصال كل فريق إلى جزائه، فيشهد بكمال عدل الله وحكمه. ويتصل آخر السورة بأولها؛ فقد افتتحت بإنزال الكتاب والدعوة إلى إخلاص الدين، واختتمت بالتسبيح والحمد عند تمام الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص44–45، تحت عنوان «بلاغة رد عجز السورة على صدرها»","url":""}]},{"id":"s40-1","number":1,"surah":40,"verses":[1],"references":[{"surah":40,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا سُمّيت سورة غافر بهذا الاسم؟","answer":"لأن مطلعها وصف الله بأنه ﴿غافر الذنب﴾، فصار الاسم تذكيرًا بباب المغفرة ودعوة إلى التوبة، وهو من أبرز مقاصد السورة في دعوة المجادلين إلى الرجوع للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص49–50، تحت عنوان «اسم السورة ومناسبة تسميتها»","url":""}]},{"id":"s40-2","number":2,"surah":40,"verses":[1],"references":[{"surah":40,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا تُسمّى سورة غافر أيضًا «سورة المؤمن»؟","answer":"لأنها انفردت بالتفصيل في قصة مؤمن آل فرعون الذي كتم إيمانه ثم جهر بالحجة مدافعًا عن موسى عليه السلام؛ فصار هذا المشهد المميز علمًا على السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص49، تحت عنوان «اسم السورة ومناسبة تسميتها»","url":""}]},{"id":"s40-3","number":3,"surah":40,"verses":[1,2,3],"references":[{"surah":40,"verses":[1,2,3]}],"verseLabel":"غافر: 1–3","question":"ما دلالة افتتاح سورة غافر بـ﴿حم﴾؟","answer":"تنبه الحروف المقطعة إلى أن القرآن مؤلف من الحروف العربية التي يعرفها المخاطبون، ومع ذلك عجزوا عن الإتيان بمثله؛ فهي تستثير الانتباه إلى إعجازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص60، تحت عنوان «دلالة التعبير بالحروف المقطعة في بداية السورة»","url":""}]},{"id":"s40-137","number":137,"surah":40,"verses":[1,2,3],"references":[{"surah":40,"verses":[1,2,3]}],"verseLabel":"غافر: 1–3","question":"لماذا وُصف مُنزِّل القرآن هنا بأنه ﴿الْعَزِيزِ الْعَلِيمِ﴾؟","answer":"لأن عزة الله تؤكد أن تنزيله لا يُغالب، وعلمه يؤكد إحاطة الكتاب بالحكمة والحق؛ فاجتماعهما يلائم مصدر القرآن المعجز المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص63–64، تحت عنوان «نكتة الوصف بالعزيز العليم دون غيرهما»","url":""}]},{"id":"s40-4","number":4,"surah":40,"verses":[2],"references":[{"surah":40,"verses":[2]}],"verseLabel":"غافر: 2","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْعَلِيمِ﴾ في مصدر التنزيل؟","answer":"قدم العزيز لأن ترتيب الحكم وإقامته يحتاجان إلى قوة تنفذهما، ثم جاء العليم ليدل على العلم الذي يكون به الإحكام. فيلائم ترتيب الوصفين كون الكتاب صادرًا عمن ينفذ أمره ويعلم مواضع حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص64، تحت عنوان «نكتة تقديم ﴿العزيز﴾ على ﴿العليم﴾»","url":""}]},{"id":"s40-5","number":5,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قيل ﴿غَافِرِ الذَّنْبِ﴾ بدل وصف آخر للمغفرة؟","answer":"اختير الغفران لما فيه من معنى الستر والوقاية؛ فالله يستر ذنب عبده ويقيه تبعته وعقوبته، وفي الوصف فتح لباب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص66، تحت عنوان «نكتة التعبير بالغفران»","url":""}]},{"id":"s40-138","number":138,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"ما سر عطف ﴿قَابِلِ التَّوْبِ﴾ بالواو بعد ﴿غَافِرِ الذَّنْبِ﴾؟","answer":"ليظهر أن قبول رجوع العبد ومغفرة ذنبه فضلَان متلازمان غير متطابقين؛ فإذا تاب قُبل رجوعه وغُفر ذنبه، فتقوى الدعوة إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص68، تحت عنوان «سر العطف بالواو في قوله: ﴿وقابل التوب﴾»","url":""}]},{"id":"s40-6","number":6,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا أُخّر وصف ﴿شَدِيدِ الْعِقَابِ﴾ عن المغفرة وقبول التوبة؟","answer":"ليبدأ الخطاب بما يفتح الرجاء ويستميل إلى التوبة، ثم يردع عن الإصرار بذكر العقاب؛ فالتقديم يؤكد سعة الرحمة من غير أن يفتح باب الاغترار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص70–71، تحت عنوان «نكتة تأخير الوعيد عن الوعد»","url":""}]},{"id":"s40-139","number":139,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قيل ﴿ذِي الطَّوْلِ﴾ بعد ﴿شَدِيدِ الْعِقَابِ﴾؟","answer":"لأن الطَّول هو الفضل والإنعام؛ فجاء بعد الوعيد ليفتح باب الإحسان والرجاء، ويبين أن شدة العقاب لا تنافي سعة الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص71، تحت عنوان «نكتة التعبير بقوله تعالى: ﴿ذي الطول﴾»","url":""}]},{"id":"s40-7","number":7,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قُدّم ﴿إِلَيْهِ﴾ في قوله ﴿إِلَيْهِ الْمَصِيرُ﴾؟","answer":"لقصر المصير على الله وحده؛ فإليه المرجع النهائي، ولا يملك أحد من دونه الحكم في ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص76، تحت عنوان «غرض تقديم ﴿إليه﴾»","url":""}]},{"id":"s40-8","number":8,"surah":40,"verses":[4],"references":[{"surah":40,"verses":[4]}],"verseLabel":"غافر: 4","question":"لماذا قُصرت المجادلة في آيات الله على الكافرين؟","answer":"لأن المراد مجادلة المكابر الذي يريد رد الآيات بعد ظهور حجتها، لا النظر الصادق طلبًا للفهم؛ فجعلها القصر علامة على الكفر حين تكون لإبطال الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص81، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s40-9","number":9,"surah":40,"verses":[4],"references":[{"surah":40,"verses":[4]}],"verseLabel":"غافر: 4","question":"لماذا قيل ﴿فَلَا يَغْرُرْكَ﴾ عند الحديث عن تقلب الكافرين في البلاد؟","answer":"لأن ما يظهر عليهم من سعة ورواج قد يخدع الناظر فيحسبه دليل سلامة ونجاة؛ فنُهي الرسول ﷺ وكل سامع عن الاغترار بالإمهال الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص84، تحت عنوان «نكتة التعبير بالغرور»","url":""}]},{"id":"s40-10","number":10,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"لماذا عُطف ﴿الْأَحْزَابُ﴾ على قوم نوح؟","answer":"ليجمع الأمم المختلفة التي تحزبت على رسلها بعد قوم نوح في صف واحد من التكذيب، على اختلاف أزمانها وأوطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص91، تحت عنوان «بلاغة عطف ﴿والأحزاب﴾»","url":""}]},{"id":"s40-140","number":140,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"ماذا يضيف قوله ﴿وَهَمَّتْ كُلُّ أُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ﴾ بعد ذكر التكذيب؟","answer":"يكشف أن المعارضة لم تقف عند إنكار اللسان، بل تحولت إلى عزم على البطش بالرسل؛ فتتدرج الصورة من التكذيب إلى العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص92–93، تحت عنوان «نكتة العطف في قوله: ﴿وهمت﴾»","url":""}]},{"id":"s40-11","number":11,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"ما أثر مقابلة ﴿الْبَاطِلِ﴾ بـ﴿الْحَقَّ﴾ في قوله ﴿وَجَادَلُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"تبرز المفارقة بين وسيلتهم وغايتهم: يريدون إسقاط الثابت بما لا ثبات له، فتفضح المقابلة فساد مجادلتهم قبل بيان نتيجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص98، تحت عنوان «بلاغة الطباق بين الحق والباطل»","url":""}]},{"id":"s40-12","number":12,"surah":40,"verses":[5,6],"references":[{"surah":40,"verses":[5,6]}],"verseLabel":"غافر: 5–6","question":"ما دلالة قوله ﴿فَأَخَذْتُهُمْ﴾ في عقوبة الأمم المكذبة؟","answer":"صوّر إهلاكهم بالأخذ المحكم الذي لا انفلات منه، ليشعر بأن القوة التي أمهلتهم أحاطت بهم حين جاء موعد العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص99، تحت عنوان «بلاغة المجاز في فعل الأخذ»","url":""}]},{"id":"s40-141","number":141,"surah":40,"verses":[5,6],"references":[{"surah":40,"verses":[5,6]}],"verseLabel":"غافر: 5–6","question":"بِمَ يشبَّه ثبوت العذاب على الكافرين في قوله ﴿وَكَذَلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ﴾؟","answer":"شُبّه استحقاق الكافرين الحاضرين للعذاب باستحقاق الأمم السابقة التي كذبت فأُخذت؛ فيوصل وعيد الآخرة بالمثال التاريخي المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص104، تحت عنوان «بلاغة التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s40-13","number":13,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا ذُكر إيمان حملة العرش مع أن إيمان الملائكة معلوم؟","answer":"لإبراز جامع الإيمان بينهم وبين المؤمنين الذين يستغفرون لهم؛ فذكر الصفة يبين سر عنايتهم بإخوانهم في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص114، تحت عنوان «فائدة ذكر الإيمان مع أنه مسلم به»","url":""}]},{"id":"s40-142","number":142,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا قدّم حملة العرش التسبيح والإيمان على الاستغفار للمؤمنين؟","answer":"لأنهم بدؤوا بتعظيم الله والثناء عليه قبل طلب حاجتهم، فقدموا حق الرب ثم دعاءهم لعباده؛ وذلك من أدب الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص115، تحت عنوان «دلالة الترتيب بين الأفعال الثلاثة»","url":""}]},{"id":"s40-14","number":14,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا قُدمت الرحمة على العلم في قول الملائكة ﴿وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾؟","answer":"لأن الرحمة هي المقصودة في مقام طلب المغفرة، ثم جاء العلم ليؤكد إحاطة الله بحال المؤمنين وصدق توبتهم؛ فترتب الوصفان على مقصد الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص118–119، تحت عنوان «نكتة تقديم الرحمة على العلم»","url":""}]},{"id":"s40-15","number":15,"surah":40,"verses":[7,8],"references":[{"surah":40,"verses":[7,8]}],"verseLabel":"غافر: 7–8","question":"لماذا دعا الملائكة للمؤمنين بدخول الجنة بعد أن دعوا لهم بالوقاية من الجحيم؟","answer":"ليجمع الدعاء بين دفع الضرر ونيل النعيم؛ فالوقاية وحدها نجاة، ثم جاء طلب الجنة ليتم الفوز بالإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص127، تحت عنوان «فائدة عطف الدعاء بدخول الجنة على الوقاية من النار»","url":""}]},{"id":"s40-143","number":143,"surah":40,"verses":[7,8],"references":[{"surah":40,"verses":[7,8]}],"verseLabel":"غافر: 7–8","question":"لماذا شمل دعاء الملائكة أهل المؤمن وذريته؟","answer":"لأن نعيم الجنة يتم باجتماع الأحبة؛ فوسّعوا الدعاء ليشمل من يرتبط بالمؤمن من أهله، فيجتمع لهم النعيم والأنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص131، تحت عنوان «دلالة العطف وفائدته»","url":""}]},{"id":"s40-16","number":16,"surah":40,"verses":[8],"references":[{"surah":40,"verses":[8]}],"verseLabel":"غافر: 8","question":"ماذا تضيف كلمة ﴿عَدْنٍ﴾ إلى وصف الجنات؟","answer":"العدن هو الإقامة والثبات؛ فتدل الكلمة على أن دخولها استقرار دائم لا يعقبه خروج ولا تحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص129، تحت عنوان «براعة استعمال مفردة ﴿عدن﴾»","url":""}]},{"id":"s40-17","number":17,"surah":40,"verses":[9],"references":[{"surah":40,"verses":[9]}],"verseLabel":"غافر: 9","question":"لماذا قال الملائكة ﴿وَقِهِمُ السَّيِّئَاتِ﴾ مع أن السيئات أعمال وقعت بالفعل؟","answer":"أطلقت السيئات وأريد ما يترتب عليها من العقوبات والأهوال؛ فالدعاء أن يقيهم الله تبعات الذنوب، وجاء التعبير بالسبب لاستحضار الصلة بين العمل وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص139–140، تحت عنوان «لفظ ﴿السيئات﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s40-144","number":144,"surah":40,"verses":[9],"references":[{"surah":40,"verses":[9]}],"verseLabel":"غافر: 9","question":"ماذا تضيف الجملة الشرطية ﴿وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ﴾؟","answer":"تجعل الوقاية من تبعات الذنب علامة محققة على الرحمة، وتؤكد أن السلامة يوم القيامة لا تكون إلا برحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص141، تحت عنوان «بلاغة التذييل بالجملة الشرطية»","url":""}]},{"id":"s40-18","number":18,"surah":40,"verses":[10],"references":[{"surah":40,"verses":[10]}],"verseLabel":"غافر: 10","question":"ما سر بناء ﴿يُنَادَوْنَ﴾ للمجهول في توبيخ أهل النار؟","answer":"لم يسم المنادي لأن المقصود إبراز النداء وما يحمله من التوبيخ، وإبهامه يزيد هوله على المنادين. ويتجه السامع بذلك إلى مضمون الحكم الذي يواجه أهل النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص149، تحت عنوان «نكتة التعبير بصيغة المبني للمفعول»","url":""}]},{"id":"s40-19","number":19,"surah":40,"verses":[10],"references":[{"surah":40,"verses":[10]}],"verseLabel":"غافر: 10","question":"لماذا قيل للكافرين إن مقت الله لهم ﴿أَكْبَرُ﴾ من مقتهم أنفسهم؟","answer":"لأنهم حين يرون الخسران يمقتون أنفسهم، فيقال لهم إن بغض الله لهم وقت كفرهم أعظم وأشد؛ فيتضاعف توبيخهم ولا يبقى الندم وصفًا كافيًا لحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص151–152، تحت عنوان «بلاغة استعمال مفردة ﴿أكبر﴾ مادة وصيغة»","url":""}]},{"id":"s40-20","number":20,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"لماذا فرّع أهل النار سؤال الخروج على اعترافهم بالذنوب؟","answer":"ظنوا أن اعترافهم قد يفتح لهم طريق النجاة، فجاءت الفاء لتكشف تعلقهم بأن يجعلوا الإقرار سببًا للخروج بعد فوات زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص166–167، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s40-145","number":145,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"ماذا يفيد تنكير ﴿خُرُوجٍ﴾ في قولهم ﴿فَهَلْ إِلَى خُرُوجٍ مِنْ سَبِيلٍ﴾؟","answer":"يصور أنهم لا يطلبون خروجًا مخصوصًا، بل يتعلقون بأي نوع من الخروج مهما كان، من شدة ما هم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص168، تحت عنوان «نكتة تنكير لفظ ﴿خروج﴾»","url":""}]},{"id":"s40-146","number":146,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"لماذا نُكرت ﴿سَبِيلٍ﴾ في سؤال أهل النار عن الخروج؟","answer":"للدلالة على أنهم يبحثون عن أدنى وسيلة ممكنة، أيًّا كانت؛ فالتنكير يصور اليأس الذي يدفعهم إلى التعلق بأي طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص169، تحت عنوان «نكتة تنكير ﴿سبيل﴾»","url":""}]},{"id":"s40-21","number":21,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"ما وجه الأسلوب الحكيم في جواب طلب الخروج ببيان موقفهم من التوحيد والشرك؟","answer":"صرف الجواب نظرهم عن مجرد طلب الخروج إلى سبب ما حل بهم: كانوا يكفرون إذا أفرد الله بالدعاء، ويؤمنون إذا أشرك به. ففيه إفهامهم أن موطن النجاة كان قبول التوحيد، وقطع الرجاء الذي بنوه على مجرد الاعتراف المتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص174، تحت عنوان «بلاغة الأسلوب الحكيم»","url":""}]},{"id":"s40-22","number":22,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا قيل ﴿إِذَا دُعِيَ اللَّهُ وَحْدَهُ كَفَرْتُمْ﴾ ثم ﴿وَإِنْ يُشْرَكْ بِهِ تُؤْمِنُوا﴾؟","answer":"جاءت ﴿إذا﴾ لتحقيق وقوع دعوتهم إلى التوحيد ورفضهم لها، وجاءت ﴿إن﴾ في الشرك على صورة الفرض لأن الشرك بعد وضوح الأدلة مما لا ينبغي أن يقع أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص177–178، تحت عنوان «سر المخالفة بين أداتي الشرط»","url":""}]},{"id":"s40-147","number":147,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا جاء جواب الإشراك بصيغة المضارع ﴿تُؤْمِنُوا﴾؟","answer":"ليستحضر تجدد قبولهم للشرك واستعدادهم المتكرر له؛ فكلما عُرض عليهم باطل سارعوا إلى تصديقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص179، تحت عنوان «نكتة مجيء جواب الشرط بصيغة المضارع»","url":""}]},{"id":"s40-23","number":23,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا وُصف الله بـ﴿الْعَلِيِّ﴾ بعد قوله ﴿فَالْحُكْمُ لِلَّهِ﴾؟","answer":"لأن علوه يقرر أنه فوق كل منازع، فلا يعلو حكمٌ على حكمه ولا يرد قضاؤه؛ فناسب الوصف انفراده بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص181، تحت عنوان «اختيار صفة ﴿العلي﴾»","url":""}]},{"id":"s40-148","number":148,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا أُتبع ﴿الْعَلِيِّ﴾ بوصف ﴿الْكَبِيرِ﴾؟","answer":"لأن الكبرياء تجمع معنى العظمة والجلال، فتؤكد أن من انفرد بالحكم أعظم من كل ما عبدوه من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص182، تحت عنوان «اختيار صفة ﴿الكبير﴾»","url":""}]},{"id":"s40-149","number":149,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا قُدّم ﴿الْعَلِيِّ﴾ على ﴿الْكَبِيرِ﴾ في غافر، وعُكس الترتيب في قوله ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ﴾؟","answer":"في غافر سبق الحديث عن اختصاص الله بالحكم فناسب البدء بالعلو الذي يقهر كل منازع، ثم الكبرياء. وفي الموضع الآخر جاء الكبرياء بعد إحاطة العلم لتقرير عظمة الذات، ثم ختم بالتعالي عن الشركاء والنقائص.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص183، تحت عنوان «نكتة التقديم والتأخير بين الوصفين»","url":""}]},{"id":"s40-24","number":24,"surah":40,"verses":[13],"references":[{"surah":40,"verses":[13]}],"verseLabel":"غافر: 13","question":"ما سر الجمع بين إراءة الله آياته وإنزال الرزق من السماء؟","answer":"إراءة الآيات تقيم دلائل الهداية، وإنزال الرزق يحفظ حياة الأبدان. فاجتمع ما يصلح الدين وما تقوم به الحياة، ليكون البرهان والامتنان داعيين إلى توحيد المنعم وإخلاص العبادة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص189–190، تحت عنوان «مناسبة العطف بين الجملتين»","url":""}]},{"id":"s40-25","number":25,"surah":40,"verses":[13],"references":[{"surah":40,"verses":[13]}],"verseLabel":"غافر: 13","question":"ما دلالة تسمية المطر النازل من السماء ﴿رِزْقًا﴾؟","answer":"المطر سبب لما يرزق به الناس من نبات وأقوات، فسمي باسم نتيجته على المجاز المرسل. وبذلك يبرز التعبير النعمة المقصودة من نزوله، فيدعو إلى شكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص191–192، تحت عنوان «بلاغة المجاز المرسل»","url":""}]},{"id":"s40-26","number":26,"surah":40,"verses":[14],"references":[{"surah":40,"verses":[14]}],"verseLabel":"غافر: 14","question":"ماذا يفيد قوله ﴿وَلَوْ كَرِهَ الْكَافِرُونَ﴾ بعد الأمر بإخلاص الدين لله؟","answer":"يفيد أن إخلاص العبادة لله واجب ثابت في كل حال، لا يوقفه كره الكافرين ولا يعطل حكمه؛ فجاءت ﴿لو﴾ لتقرير المضي في التوحيد حتى مع تحقق أشد الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص201، تحت عنوان «نوع (لو) ومعناها»","url":""}]},{"id":"s40-27","number":27,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"ما دلالة تتابع الأوصاف ﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ﴾؟","answer":"يجري الوصفان في نسق تعداد يكشف رفعة الله وعظمة ملكه مع وحدة الموصوف؛ فكل خبر يضيف وجهًا من الجلال من غير حاجة إلى تكرار اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص208، تحت عنوان «بلاغة نمط التعديد»","url":""}]},{"id":"s40-150","number":150,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"لماذا تأخر قوله ﴿يُلْقِي الرُّوحَ مِنْ أَمْرِهِ﴾ بعد ﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ﴾؟","answer":"لأن ذكر العزة والملك يمهد لأعظم نعمه على العباد: الوحي؛ فتأخير إلقاء الروح ينقل السياق من صفات الجلال إلى أثر الرحمة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص210، تحت عنوان «نكتة تأخير الخبر الثالث ﴿يلقي الروح﴾»","url":""}]},{"id":"s40-28","number":28,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"لماذا عُدّي إلقاء الوحي بـ﴿عَلَى﴾ في قوله ﴿يُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَى مَنْ يَشَاءُ﴾؟","answer":"لتصوير الوحي نازلًا من العلو بقوة وثبات على من اصطفاه الله، وفيه تشريف للمتلقي وإيحاء بثقل الأمانة الملقاة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص213–214، تحت عنوان «نكتة تعدية فعل الإلقاء بحرف الاستعلاء»","url":""}]},{"id":"s40-29","number":29,"surah":40,"verses":[15,16],"references":[{"surah":40,"verses":[15,16]}],"verseLabel":"غافر: 15–16","question":"لماذا سُمّيت القيامة ﴿يَوْمَ التَّلَاقِ﴾؟","answer":"لأنه اليوم الذي يلتقي فيه الخلق جميعًا، ويلتقي العامل بعمله والظالم بالمظلوم؛ فالإضافة تختصر مشاهد الاجتماع والحساب في اسم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص216، تحت عنوان «فائدة الإضافة»","url":""}]},{"id":"s40-151","number":151,"surah":40,"verses":[15,16],"references":[{"surah":40,"verses":[15,16]}],"verseLabel":"غافر: 15–16","question":"ما الصورة في وصف الخلق يوم القيامة بأنهم ﴿بَارِزُونَ﴾؟","answer":"تصورهم خارجين مكشوفين في فضاء لا يسترهم شيء، ظاهرة أجسادهم وأعمالهم وأسرارهم أمام الله؛ فلا ملجأ ولا خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص218–219، تحت عنوان «بلاغة استعمال مفردة ﴿بارزون﴾ بين الحقيقة والكناية»","url":""}]},{"id":"s40-30","number":30,"surah":40,"verses":[16],"references":[{"surah":40,"verses":[16]}],"verseLabel":"غافر: 16","question":"ما غرض السؤال ﴿لِمَنِ الْمُلْكُ الْيَوْمَ﴾؟","answer":"هو استفهام تقريري يعلن ظهور سلطان الله وانقطاع دعاوى الملك كلها؛ فالمشهد نفسه يحمل الخلق على الإقرار بأنه لا ملك إلا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص224–225، تحت عنوان «بلاغة الاستفهام المجازي وغرضه»","url":""}]},{"id":"s40-152","number":152,"surah":40,"verses":[16],"references":[{"surah":40,"verses":[16]}],"verseLabel":"غافر: 16","question":"لماذا ذُكر جواب السؤال ﴿لِلَّهِ﴾ مع أن الجواب معلوم؟","answer":"ليحسم التقرير ويعين الحقيقة التي لا جواب سواها، ويزيد توبيخ من نازعوا الله ملكه في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص226، تحت عنوان «نكتة ذكر جواب الاستفهام التقريري»","url":""}]},{"id":"s40-31","number":31,"surah":40,"verses":[17],"references":[{"surah":36,"verses":[54]},{"surah":40,"verses":[17]}],"verseLabel":"غافر: 17؛ يس: 54","question":"لماذا قيل ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ﴾؟","answer":"تفيد ﴿كل﴾ شمول الجزاء لجميع النفوس بلا استثناء ولا إهمال؛ مؤمنة أو كافرة، مطيعة أو عاصية، على قدر ما كسبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص231، تحت عنوان «نكتة دخول ﴿كل﴾»","url":""}]},{"id":"s40-32","number":32,"surah":40,"verses":[17],"references":[{"surah":40,"verses":[17]}],"verseLabel":"غافر: 17","question":"لماذا تكرر لفظ ﴿الْيَوْمَ﴾ في ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ﴾ و﴿لَا ظُلْمَ الْيَوْمَ﴾؟","answer":"الأول يعيّن يوم الجزاء الموعود ويستحضره كأنه حاضر، والثاني يثبت اختصاص ذلك المقام بظهور العدل التام ونفي الظلم؛ فالتكرار يرسخ رهبة اليوم وأمن عدله معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص230–235، تحت عنوان «معنى (أل) في ﴿اليوم﴾»","url":""}]},{"id":"s40-33","number":33,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا عُدل عن «يوم القيامة» إلى وصفه بـ﴿الْآزِفَةِ﴾؟","answer":"لإبراز قرب الساعة وشدة دنوها؛ حُذف الموصوف وأقيمت صفته مقامه حتى تبدو القيامة وكأن حقيقتها الملازمة هي الاقتراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص244، تحت عنوان «سر العدول عن ذكر الموصوف»","url":""}]},{"id":"s40-34","number":34,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا قُدّم نفي الحميم على نفي الشفيع؟","answer":"لأن الحميم قريب يبادر إلى النصرة من غير طلب، أما الشفيع فلا يتحرك غالبًا إلا بعد سؤال؛ فنُفي الأقرب والأسرع أولًا ثم ما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص250، تحت عنوان «نكتة تقديم الحميم على الشفيع»","url":""}]},{"id":"s40-153","number":153,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا قيل ﴿وَلَا شَفِيعٍ يُطَاعُ﴾؟","answer":"لنفي الشفاعة النافعة من أصلها؛ ليس لهم شفيع مقبول القول، والوصف يزيد اليأس من كل واسطة يرجونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص250–251، تحت عنوان «نكتة وصف الشفيع»","url":""}]},{"id":"s40-35","number":35,"surah":40,"verses":[19],"references":[{"surah":40,"verses":[19]}],"verseLabel":"غافر: 19","question":"ما وجه فرادة التعبير في ﴿يَعْلَمُ خَائِنَةَ الْأَعْيُنِ﴾؟","answer":"تجمع إضافة الخيانة إلى الأعين بين دقة اللفظ وقوة التصوير؛ فهي تستحضر النظرة الخفية التي يحاول صاحبها إخفاءها عمن حوله. وإحاطة العلم بها تقطع توهم أن خفاء الحركة على الناس يجعلها خافية على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص259–260، تحت عنوان «فن الفرائد في قوله: ﴿يعلم خائنة الأعين﴾»","url":""}]},{"id":"s40-36","number":36,"surah":40,"verses":[19],"references":[{"surah":40,"verses":[19]}],"verseLabel":"غافر: 19","question":"ما سر الجمع بين ﴿خَائِنَةَ الْأَعْيُنِ﴾ و﴿مَا تُخْفِي الصُّدُورُ﴾؟","answer":"ليجمع علم الله أخفى عمل ظاهر وأخفى سر باطن؛ فالنظرة المختلسة لا تفوته، وما يستره القلب لا يخفى عليه، وبذلك يستوي الظاهر والباطن أمام علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص261، تحت عنوان «معنى الواو في قوله: ﴿وما تخفي الصدور﴾»","url":""}]},{"id":"s40-37","number":37,"surah":40,"verses":[20],"references":[{"surah":40,"verses":[20]}],"verseLabel":"غافر: 20","question":"ما دلالة مقابلة ﴿وَاللَّهُ يَقْضِي بِالْحَقِّ﴾ بـ﴿لَا يَقْضُونَ بِشَيْءٍ﴾؟","answer":"تجمع المقابلة كمال حكم الله وعلمه وقدرته، وعجز المعبودات من دونه عن أي حكم أو أثر مهما صغر؛ فتقيم برهان التوحيد بين طرفين واضحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص271، تحت عنوان «بلاغة المقابلة في الآية»","url":""}]},{"id":"s40-38","number":38,"surah":40,"verses":[20],"references":[{"surah":40,"verses":[20]}],"verseLabel":"غافر: 20","question":"لماذا خُتمت الآية بقوله ﴿إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"لأن من يقضي بالحق لا بد أن يحيط بالأقوال والأعمال؛ فالسميع يعلم ما يقولون والبصير يرى ما يفعلون، بخلاف معبوداتهم التي لا تسمع ولا تبصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص273، تحت عنوان «نكتة ختم الآية الكريمة بالاسمين الجليلين»","url":""}]},{"id":"s40-39","number":39,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا نُكّرت ﴿قُوَّةً﴾ في وصف الأمم السابقة؟","answer":"للتعظيم والتفخيم؛ كانت لهم قوة ضخمة متنوعة في الأبدان والأموال والعمران، ومع ذلك لم تغن عنهم حين جاء عذاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص283، تحت عنوان «نكتة تنكير ﴿قوة﴾»","url":""}]},{"id":"s40-154","number":154,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا نُكّرت ﴿آثَارًا﴾ في قوله ﴿وَآثَارًا فِي الْأَرْضِ﴾؟","answer":"للدلالة على كثرة آثارهم وعظمتها وتنوعها من حصون ومدائن ومصانع، فبقي بعضها شاهدًا على قوة زالت ولم تدفع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص284، تحت عنوان «نكتة تنكير ﴿آثارًا﴾»","url":""}]},{"id":"s40-40","number":40,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"ماذا يفيد ضمير ﴿هُمْ﴾ في قوله ﴿كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً﴾؟","answer":"يؤكد أن الأمم السابقة نفسها ـ لا غيرها ـ كانت أشد من المخاطبين، فيقوي التحذير: من هم أعظم قوة أُخذوا ولم يعجزوا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص282، تحت عنوان «نكتة دخول ضمير الفصل ﴿هم﴾»","url":""}]},{"id":"s40-155","number":155,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا تكرر وصف الأمم السابقة بالقوة والآثار في موضعين من سورة غافر؟","answer":"ليجعل آثارهم الباقية برهانًا محسوسًا على قوة أصحابها ثم على هلاكهم؛ اختلف تركيب الموضعين بحسب السياق، واتفقا في كسر غرور المكذبين بقوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص76–77، تحت عنوان «بلاغة التشابه اللفظي مع الآية (21) من هذه السورة»","url":""}]},{"id":"s40-41","number":41,"surah":40,"verses":[22],"references":[{"surah":40,"verses":[22]},{"surah":64,"verses":[6]}],"verseLabel":"غافر: 22؛ التغابن: 6","question":"لماذا أُكِّد سبب هلاك الأمم بقوله ﴿ذَلِكَ بِأَنَّهُمْ كَانَتْ تَأْتِيهِمْ رُسُلُهُمْ بِالْبَيِّنَاتِ﴾؟","answer":"ليثبت أن أخذهم لم يكن بلا حجة؛ فقد تكرر مجيء الرسل بالبينات، ثم قابلوا ذلك بالكفر، فكان العذاب نتيجة إصرارهم بعد وضوح الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص290، تحت عنوان «نكتة التوكيد في قوله: ﴿بأنهم﴾»","url":""}]},{"id":"s40-42","number":42,"surah":40,"verses":[22],"references":[{"surah":40,"verses":[22]}],"verseLabel":"غافر: 22","question":"لماذا خُتم أخذ المكذبين بقوله ﴿إِنَّهُ قَوِيٌّ شَدِيدُ الْعِقَابِ﴾؟","answer":"لأن قوته تثبت أنه لا يعجزه أحد، وشدة عقابه تناسب من كفر وأصر بعد مجيء الرسل؛ فالوصفان يعللان سرعة الأخذ وحسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص294، تحت عنوان «نكتة ختم الآية بالاسمين الجليلين»","url":""}]},{"id":"s40-43","number":43,"surah":40,"verses":[23,24],"references":[{"surah":40,"verses":[23,24]}],"verseLabel":"غافر: 23–24","question":"لماذا ذُكر هامان وقارون مع فرعون في مواجهة موسى؟","answer":"لأنهم أبرز أعوان منظومة الكفر: فرعون رأس السلطة، وهامان شريكه في التدبير، وقارون صاحب المال المؤثر؛ فاجتمع الملك والتخطيط والثروة في مقاومة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302، تحت عنوان «نكتة ذكر (هامان) و(قارون) مع ﴿فرعون﴾»","url":""}]},{"id":"s40-156","number":156,"surah":40,"verses":[23,24],"references":[{"surah":40,"verses":[23,24]}],"verseLabel":"غافر: 23–24","question":"ما دلالة ترتيب ﴿فِرْعَوْنَ وَهَامَانَ وَقَارُونَ﴾؟","answer":"بدأ بفرعون لأنه صاحب الأمر والملك، ثم هامان لقربه منه وتأثيره في القرار، ثم قارون لكونه حليفًا بالمال والمكانة؛ فجاء الترتيب بحسب قوة الموقع في المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302، تحت عنوان «دلالة الترتيب بين هذه الأسماء»","url":""}]},{"id":"s40-44","number":44,"surah":40,"verses":[24],"references":[{"surah":40,"verses":[24]}],"verseLabel":"غافر: 24","question":"لماذا نكّروا ﴿سَاحِرٌ﴾ في اتهام موسى؟","answer":"للتقليل من شأنه وجعله واحدًا من السحرة، وصرف الأنظار عن المعجزة الظاهرة التي لا يقدر عليها السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302–303، تحت عنوان «نكتة الاتهام بالسحر، وتنكير ﴿ساحر﴾»","url":""}]},{"id":"s40-157","number":157,"surah":40,"verses":[24],"references":[{"surah":40,"verses":[24]}],"verseLabel":"غافر: 24","question":"لماذا وصفوه بـ﴿كَذَّابٌ﴾ بصيغة المبالغة؟","answer":"ليصوروا ـ زورًا ـ أن الكذب عادته المتكررة، لا خبرًا واحدًا؛ فبالغوا في التشويه لأنهم عجزوا عن مواجهة حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص303، تحت عنوان «نكتة المبالغة في قولهم: ﴿كذاب﴾»","url":""}]},{"id":"s40-45","number":45,"surah":40,"verses":[25],"references":[{"surah":40,"verses":[25]}],"verseLabel":"غافر: 25","question":"لماذا قُيِّد قتل الأبناء بأنهم أبناء ﴿الَّذِينَ آمَنُوا مَعَهُ﴾؟","answer":"لبيان أن المقصود معاقبة المؤمنين بموسى والانتقام منهم في أبنائهم؛ فالقتل صار أداة لترهيب الآباء ومحاربة الدعوة، لا إجراءً عامًا منفصلًا عن إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص309، تحت عنوان «غرض التعبير بالاسم الموصول وصلته ﴿الذين آمنوا معه﴾»","url":""}]},{"id":"s40-46","number":46,"surah":40,"verses":[26],"references":[{"surah":40,"verses":[26]}],"verseLabel":"غافر: 26","question":"لماذا قال فرعون لقومه ﴿أَنْ يُبَدِّلَ دِينَكُمْ﴾ فأضاف الدين إليهم؟","answer":"تظاهر بالغيرة على عقيدتهم واستثار خوفهم من زوال مألوفهم ليكسب موافقتهم على قتل موسى؛ فجعل نفسه حارسًا لدينهم وهو المستبد بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص323، تحت عنوان «نكتة إضافة الدين إلى ضمير المخاطبين»","url":""}]},{"id":"s40-47","number":47,"surah":40,"verses":[26],"references":[{"surah":40,"verses":[26]}],"verseLabel":"غافر: 26","question":"ما دلالة تقديم تبديل الدين على إظهار الفساد في حجة فرعون؟","answer":"قدم أمر الدين لأنه أساس اجتماع القوم وما يرونه صلاحًا لنظامهم، ثم ذكر فساد الأرض ليضم إليه الخوف على حياتهم. بهذا الترتيب يصوغ فرعون حجته بما يستميلهم، مع أن دعواه الحرص على الدين تخدم بقاء سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص327، تحت عنوان «نكتة تقديم خوفه من تبديله الدين على إظهاره الفساد»","url":""}]},{"id":"s40-48","number":48,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"ما سر الجمع بين ﴿بِرَبِّي وَرَبِّكُمْ﴾ في استعاذة موسى؟","answer":"إضافة الرب إلى موسى تستحضر رعايته وحفظه، ثم إضافته إلى المخاطبين تقرر أنه ربهم أيضًا وإن أنكروه؛ فمن اعتصم برب الجميع لا تخرجه قدرة فرعون من حمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص334، تحت عنوان «معنى الواو في قوله: ﴿وربكم﴾ ونكتة الإضافة فيه»","url":""}]},{"id":"s40-49","number":49,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"لماذا استعاذ موسى من ﴿كُلِّ مُتَكَبِّرٍ﴾ ولم يخص فرعون بالذكر؟","answer":"لتعم الاستعاذة كل من اتصف بالتكبر وأراد الشر، فيظهر أن الخطر صفة وطريق لا شخص واحد، ويدخل فيها فرعون وهامان وغيرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص335، تحت عنوان «نكتة دخول ﴿كل﴾»","url":""}]},{"id":"s40-158","number":158,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"لماذا خُصّ المتكبر بأنه ﴿لَا يُؤْمِنُ بِيَوْمِ الْحِسَابِ﴾؟","answer":"لأن الإيمان بالحساب أقوى ما يردع عن البطش؛ فإذا جحده المتكبر زال عنه خوف الجزاء، فتمادى في الظلم والعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص338، تحت عنوان «نكتة الاقتصار على عدم الإيمان بيوم الحساب»","url":""}]},{"id":"s40-50","number":50,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا عُرِّف مؤمن آل فرعون بأنه ﴿رَجُلٌ﴾ من غير ذكر اسمه؟","answer":"لإبراز رجولته وشجاعته في الموقف، فالعبرة بما قام به من نصرة الحق لا باسمه؛ وتنكير اللفظ يعظم قدر هذا الموقف المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص342، تحت عنوان «دلالة التعبير بلفظ ﴿رجل﴾ ونكتة تنكيره»","url":""}]},{"id":"s40-159","number":159,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قُدِّم وصفه بأنه ﴿مِنْ آلِ فِرْعَوْنَ﴾ على قوله ﴿يَكْتُمُ إِيمَانَهُ﴾؟","answer":"لتثبت نسبته إلى آل فرعون قبل بيان إيمانه الخفي، فيعظم أثر شهادته عليهم؛ فهو رجل من داخل جماعتهم لا وافد من خصومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص343–344، تحت عنوان «نكتة تقديم الوصف ﴿من آل فرعون﴾ على قوله: ﴿يكتم إيمانه﴾»","url":""}]},{"id":"s40-160","number":160,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قيل عن مؤمن آل فرعون ﴿يَكْتُمُ إِيمَانَهُ﴾ بالفعل المضارع؟","answer":"لتصوير كتمان يتجدد ويستمر تحت ضغط الخوف، حتى جاءت اللحظة الحاسمة فتكلم؛ فالمضارع يحضر حاله وهو يوازن بين إخفاء إيمانه وإعلان النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص345، تحت عنوان «نكتة العدول عن الوصف بالمفرد إلى الوصف بالجملة الفعلية»","url":""}]},{"id":"s40-51","number":51,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا بنى مؤمن آل فرعون حجته على احتمالين: ﴿إِنْ يَكُ كَاذِبًا﴾ و﴿إِنْ يَكُ صَادِقًا﴾؟","answer":"ليخاطب قومه بإنصاف يفتح لهم باب التفكير: إن كذب فعليه كذبه، وإن صدق نالهم بعض ما يتوعدهم به. وقدّم ما يوافق ظنهم ليطمئنوا إلى عدله ثم ينتبهوا إلى الخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص354–355، تحت عنوان «بلاغة التعبير بالجمل الشرطية»","url":""}]},{"id":"s40-161","number":161,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قال ﴿يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ﴾ ولم يقل «كل»؟","answer":"لأن وقوع بعض الوعيد وحده يكفي لإبطال اطمئنانهم ودعوتهم إلى الحذر، وفي اللفظ إنصاف ولطف في المحاورة يبعدانه عن التحيز لموسى في ظاهر خطابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص360، تحت عنوان «نكتة ذكر لفظة ﴿بعض﴾»","url":""}]},{"id":"s40-52","number":52,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"ما سر تقديم احتمال كذب موسى على احتمال صدقه؟","answer":"قدم فرض الكذب ليبعد عنهم ظن أنه يريد الانتصار لموسى، ويظهر بمظهر المهتم بأمر قومه. وهذا التلطف يهيئهم لسماع فرض الصدق وما يترتب عليه من خطر عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص357، تحت عنوان «علة تقديم فرضية الكذب على الصدق»","url":""}]},{"id":"s40-53","number":53,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا ذُيِّلت حجة مؤمن آل فرعون بقوله ﴿إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ﴾؟","answer":"لتقرر قاعدة تحسم الاحتمال: صاحب الإسراف والكذب لا يؤيده الله بالبينات ولا يهديه إلى هذا البيان؛ وفيها تقوية ضمنية لصدق موسى بعد ظهور حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص362–363، تحت عنوان «بلاغة التذييل في جملة الفاصلة، ونكتة فصلها»","url":""}]},{"id":"s40-162","number":162,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"بمن عرّض مؤمن آل فرعون في قوله ﴿مُسْرِفٌ كَذَّابٌ﴾؟","answer":"عرّض بفرعون من غير مواجهة مباشرة؛ فإسرافه في القتل والفساد، وكذبه في دعوى الربوبية، يجعلان الوصفين ألصق به من موسى الذي جاء بالبينات.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص368، تحت عنوان «بلاغة التعريض في التعبير بالوصفين»","url":""}]},{"id":"s40-54","number":54,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"لماذا كرر مؤمن آل فرعون نداء ﴿يَا قَوْمِ﴾ في خطابه؟","answer":"ليجدد تنبيههم كلما انتقل إلى حجة أو تحذير جديد، ويؤكد قربه منهم وإخلاص نصحه، ولا سيما بعد مقاطعة فرعون له ومحاولة صرفهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص391، تحت عنوان «غرض تكرار النداء بـ﴿يا قوم﴾»","url":""}]},{"id":"s40-55","number":55,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"ما غرض سؤال المؤمن ﴿فَمَنْ يَنْصُرُنَا مِنْ بَأْسِ اللَّهِ إِنْ جَاءَنَا﴾؟","answer":"هو إنكار أن يقدر أحد على دفع عذاب الله؛ ساقه في صورة سؤال يهز ثقتهم بالملك والقوة ويفتح لهم فرصة النجاة بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص377، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s40-163","number":163,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"لماذا قال المؤمن ﴿يَنْصُرُنَا﴾ و﴿جَاءَنَا﴾ فأدخل نفسه مع قومه؟","answer":"ليبعد عنهم التهمة ويطمئن قلوبهم بأنه شريكهم في المصير، وأن تحذيره نصيحة لنفسه ولهم لا شماتة أو تعاليًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص379–380، تحت عنوان «بلاغة استعمال ضمير المتكلمين في ﴿ينصرنا﴾ و﴿جاءنا﴾»","url":""}]},{"id":"s40-56","number":56,"surah":40,"verses":[30,31],"references":[{"surah":40,"verses":[30,31]}],"verseLabel":"غافر: 30–31","question":"لماذا عبّر المؤمن عن سيرة المكذبين السابقة بلفظ ﴿دَأْبِ﴾؟","answer":"لأن الدأب عادة تتكرر وتستمر؛ فتكذيب الأمم وعنادها لم يكونا حادثة عابرة، ولذلك استحقوا جزاءً من جنس الطريق الذي لزموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص394، تحت عنوان «دلالة التعبير بالدأب ونوع الإضافة فيه»","url":""}]},{"id":"s40-57","number":57,"surah":40,"verses":[31],"references":[{"surah":40,"verses":[31]}],"verseLabel":"غافر: 31","question":"لماذا قيل ﴿قَوْمِ نُوحٍ﴾ ثم ذُكرت عاد وثمود من غير لفظ «قوم»؟","answer":"لأن عادًا وثمود اسمان لقبيلتين مشهورتين، أما نوح فهو اسم النبي فاحتاج إلى لفظ ﴿قوم﴾ لتعريف أمته به؛ فدل التعبير على المقصود بأوجز طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص395–396، تحت عنوان «نكتة ذكر ﴿قوم﴾ مع ﴿نوح﴾ دون البقية»","url":""}]},{"id":"s40-164","number":164,"surah":40,"verses":[31],"references":[{"surah":40,"verses":[31]}],"verseLabel":"غافر: 31","question":"لماذا رُتِّب ذكر قوم نوح ثم عاد ثم ثمود؟","answer":"لترتيبهم بحسب تعاقبهم في التاريخ: بدأ بأقدم الأمم المذكورة ثم بمن تلاها، فتتابعت أمام السامع أمثلة سنة واحدة في المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص396، تحت عنوان «دلالة الترتيب بين الأقوام المذكورين»","url":""}]},{"id":"s40-58","number":58,"surah":40,"verses":[32,33],"references":[{"surah":40,"verses":[32,33]}],"verseLabel":"غافر: 32–33","question":"لماذا سُمّيت القيامة ﴿يَوْمَ التَّنَادِ﴾؟","answer":"لما يمتلئ به ذلك اليوم من نداءات الفزع والاستغاثة والتلاوم بين أهل النار؛ فالاسم يسمع القارئ صخب المشهد قبل أن يراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص408، تحت عنوان «نكتة التعبير بـ﴿يوم التناد﴾»","url":""}]},{"id":"s40-165","number":165,"surah":40,"verses":[32,33],"references":[{"surah":40,"verses":[32,33]}],"verseLabel":"غافر: 32–33","question":"لماذا أعقب ﴿يَوْمَ التَّنَادِ﴾ بقوله ﴿يَوْمَ تُوَلُّونَ مُدْبِرِينَ﴾؟","answer":"لينتقل من اسم اليوم الذي يوحي بالصياح إلى صورة حالهم فيه وهم يفرون مذعورين، ثم يرتدون إلى الجهة التي فروا منها؛ فتتدرج الصورة من الصوت إلى الحركة والعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص409–410، تحت عنوان «بلاغة التدرج في البيان بـ﴿يوم تولون مدبرين﴾»","url":""}]},{"id":"s40-59","number":59,"surah":40,"verses":[33],"references":[{"surah":40,"verses":[33]}],"verseLabel":"غافر: 33","question":"لماذا جُمع بين نفي العاصم من الله ونفي الهادي لمن أضله الله؟","answer":"ليربط التحذير بالدعوة: لا أحد يحمي من بأس الله إذا جاء، ولا أحد يرد إلى الهدى من أعرض عنه حتى أضله الله؛ فبادروا إلى قبول الهدى قبل فوات الحماية والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص414، تحت عنوان «توجيه العطف بالواو في جملة الفاصلة»","url":""}]},{"id":"s40-60","number":60,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"لماذا ذكّر مؤمن آل فرعون قومه بيوسف تحديدًا؟","answer":"لأن يوسف معروف في تاريخ مصر، وارتبط اسمه بالبينات والرخاء والنجاة من القحط؛ فذكّرهم برسول عرفوا أثره ليحتج عليهم من تاريخهم القريب منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص425، تحت عنوان «نكتة تذكيره لهم بيوسف عليه السلام»","url":""}]},{"id":"s40-166","number":166,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"لماذا حكى عنهم قولهم بعد يوسف ﴿لَنْ يَبْعَثَ اللَّهُ مِنْ بَعْدِهِ رَسُولًا﴾ بتنكير ﴿رَسُولًا﴾؟","answer":"لإظهار أنهم أنكروا بعثة أي رسول بعد يوسف، لا رسولًا بعينه؛ فالتنكير في سياق النفي يكشف عموم إنكارهم واستمرار شكهم في أصل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص431، تحت عنوان «نكتة تنكير ﴿رسولًا﴾»","url":""}]},{"id":"s40-61","number":61,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"ما سر التعبير بـ﴿حَتَّى إِذَا هَلَكَ﴾ عن وفاة يوسف؟","answer":"يحكي المؤمن الوفاة بلفظ الهلاك ليوهم قومه أنه لا يعظم يوسف تعظيمًا يحجب عنه النظر، فيبعد عن نصحه تهمة الانحياز لشخص النبي. وبذلك يقرب كلامه من صورة النصح المجرد والنظر في العاقبة، لا الانتقاص من حقيقة مقام يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص430، تحت عنوان «نكتة التعبير بالهلاك»","url":""}]},{"id":"s40-62","number":62,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"ما دلالة وصف المرتاب بأنه ﴿مُسْرِفٌ مُرْتَابٌ﴾؟","answer":"يجمع الوصفان مجاوزة الحد والارتياب في الحق، ويقدم الإسراف لأنه يفضي إلى الشك ويغذيه. فليس الارتياب هنا نظرًا منصفًا مجردًا، بل ثمرة موقف يتجاوز صاحبه حد الاعتدال والإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص433–434، تحت عنوان «نكتة تقديم ﴿مسرف﴾ على ﴿مرتاب﴾، مع تنكيرهما»","url":""}]},{"id":"s40-63","number":63,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا قيل إن جدالهم ممقوت ﴿عِنْدَ اللَّهِ وَعِنْدَ الَّذِينَ آمَنُوا﴾؟","answer":"ليبين أن المؤمنين وافقوا بحكم إيمانهم ما يحبه الله ويبغضه، وأن بصيرتهم جعلتهم ينكرون الجدال الباطل كما هو ممقوت عنده سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص439، تحت عنوان «نكتة عطف ﴿الذين آمنوا﴾»","url":""}]},{"id":"s40-64","number":64,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا جُمع في وصف القلب بين ﴿مُتَكَبِّرٍ﴾ و﴿جَبَّارٍ﴾؟","answer":"لأن التكبر استعلاء يمنع قبول الحق، والتجبر قهر يحمل الناس على الباطل؛ فاجتمع فساد صاحبه في نفسه وفساده في معاملته للخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص442–443، تحت عنوان «نكتة وصفهم بهذين الوصفين»","url":""}]},{"id":"s40-167","number":167,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا قُدِّم وصف ﴿مُتَكَبِّرٍ﴾ على ﴿جَبَّارٍ﴾؟","answer":"لأن التكبر الباطن عن قبول الحق هو السبب، والتجبر الظاهر على الناس أثره ونتيجته؛ فقدم الأصل على ما ينشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص443، تحت عنوان «نكتة تقديم صفة التكبر على التجبر»","url":""}]},{"id":"s40-65","number":65,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"لماذا سمّى فرعون أبواب السماوات ﴿الْأَسْبَابَ﴾؟","answer":"لأن السبب ما يُتوصّل به إلى غاية، فصوّر أبواب السماوات طرقًا يريد بلوغها، مبالغًا في إيهام قومه بأنه يملك وسائل التحقق مما قاله موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص452، تحت عنوان «دلالة التعبير بـ﴿الأسباب﴾ مادة وصيغة»","url":""}]},{"id":"s40-168","number":168,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"ما الذي يصوره اختيار فرعون فعل ﴿أَطَّلِعَ﴾؟","answer":"يصوره متكلفًا الصعود والظهور على أمر غيبي، فيوهم قومه ببحث جاد، مع أن صيغة الفعل تكشف مبالغته في ادعاء القدرة على كشف ما وراء الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص453، تحت عنوان «دلالة التعبير بـ(أطلع) مادة وصيغة»","url":""}]},{"id":"s40-169","number":169,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"لماذا قال فرعون ﴿إِلَهِ مُوسَى﴾ فأضاف الإله إلى موسى؟","answer":"استهزاءً وإنكارًا أن يكون إله موسى إلهًا له وللناس؛ حصر النسبة في موسى ليبقي لنفسه دعوى الربوبية ويصور رسالة التوحيد كأنها اعتقاد خاص بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص454، تحت عنوان «نكتة إضافة الـ﴿إله﴾ إلى ﴿موسى﴾»","url":""}]},{"id":"s40-66","number":66,"surah":40,"verses":[37],"references":[{"surah":40,"verses":[37]}],"verseLabel":"غافر: 37","question":"لماذا كثّف فرعون المؤكدات في قوله ﴿وَإِنِّي لَأَظُنُّهُ كَاذِبًا﴾؟","answer":"ليبالغ في إقناع قومه بكذبة يريد تثبيتها، ويزيل ما قد يثيره طلب بناء الصرح من توهم أنه صدق موسى أو صار يشك في موقفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص455، تحت عنوان «فائدة تتابع المؤكدات في ﴿وإني لأظنه كاذبًا﴾»","url":""}]},{"id":"s40-170","number":170,"surah":40,"verses":[37],"references":[{"surah":40,"verses":[37]}],"verseLabel":"غافر: 37","question":"ما وجه الاحتراس في قوله ﴿وَإِنِّي لَأَظُنُّهُ كَاذِبًا﴾؟","answer":"لأن طلبه بلوغ أسباب السماوات قد يوحي بأنه يريد التحقق من صدق موسى؛ فاحترس بإعلان ظنه الكذب حتى يبقي قومه على الجحود ولا يفهموا من مشروعه ميلًا إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص456، تحت عنوان «بلاغة الاحتراس في قوله: ﴿وإني لأظنه كاذبًا﴾»","url":""}]},{"id":"s40-67","number":67,"surah":40,"verses":[29,38],"references":[{"surah":40,"verses":[29,38]}],"verseLabel":"غافر: 29؛ غافر: 38","question":"بماذا عرّض المؤمن حين قال ﴿أَهْدِكُمْ سَبِيلَ الرَّشَادِ﴾؟","answer":"عرّض بأن سبيل فرعون هو طريق الغي والضلال؛ قابل دعواه باللفظ نفسه، ثم أقام على رشاده دليلًا من حقيقة الدنيا والآخرة، من غير مواجهة فظة تصد قومه عن سماعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص470، تحت عنوان «بلاغة التعريض في الآية»","url":""}]},{"id":"s40-68","number":68,"surah":40,"verses":[39],"references":[{"surah":40,"verses":[39]}],"verseLabel":"غافر: 39","question":"لماذا سُمّيت الآخرة ﴿دَارُ الْقَرَارِ﴾؟","answer":"لأنها وحدها موطن الاستقرار الذي لا يزول ولا يضطرب؛ وإضافة الدار إلى القرار تخصها بالثبات الدائم في مقابل متاع الدنيا العابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص474، تحت عنوان «نكتة إضافة ﴿دار﴾ إلى ﴿القرار﴾»","url":""}]},{"id":"s40-69","number":69,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"لماذا قُيد جزاء السيئة بقوله ﴿إِلَّا مِثْلَهَا﴾؟","answer":"ليقرر كمال العدل؛ فلا يزاد في عقوبة السيئة على قدرها، ولا يتجاوز الجزاء حد الفعل الذي استوجبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص477، تحت عنوان «دلالة التعبير بالمثلية في ﴿إلا مثلها﴾»","url":""}]},{"id":"s40-171","number":171,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"ما الذي تصوره عبارة ﴿يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ﴾؟","answer":"تصور سعة نعيم الجنة واستمراره بلا نفاد ولا تضييق، فتقابل عدل العقوبة المحدودة بفضل المثوبة غير المحدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص484، تحت عنوان «بلاغة الكناية في قوله: ﴿بغير حساب﴾»","url":""}]},{"id":"s40-70","number":70,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"لماذا صُرِّح بالذكر والأنثى في وعد العامل الصالح؟","answer":"يدفع التصريح توهم اختصاص الوعد بأحد الجنسين، ويؤكد أن الذكر والأنثى سواء في أصل قبول العمل الصالح وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص479، تحت عنوان «فائدة قوله: ﴿من ذكر أو أنثى﴾»","url":""}]},{"id":"s40-71","number":71,"surah":40,"verses":[41],"references":[{"surah":40,"verses":[41]}],"verseLabel":"غافر: 41","question":"لماذا قال مؤمن آل فرعون ﴿أَدْعُوكُمْ إِلَى النَّجَاةِ﴾ ولم يقل «إلى الجنة»؟","answer":"لأن النجاة تستثير غريزة الخلاص من الهلاك، وتشمل الفوز بالجنة والسلامة من النار، فهي أبلغ في تحريك قومه إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص491–492، تحت عنوان «سر العدول عن (الجنة) إلى ﴿النجاة﴾»","url":""}]},{"id":"s40-172","number":172,"surah":40,"verses":[41],"references":[{"surah":40,"verses":[41]}],"verseLabel":"غافر: 41","question":"كيف كانت دعوة قومه له ﴿إِلَى النَّارِ﴾ وهم لم يسموها كذلك؟","answer":"عبّر بمآل دعوتهم؛ فدعوتهم إلى الشرك طريق يفضي إلى النار، فكشف النتيجة المخيفة الكامنة وراء ما يعرضونه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص493، تحت عنوان «بلاغة المجاز في ﴿النار﴾»","url":""}]},{"id":"s40-72","number":72,"surah":40,"verses":[42],"references":[{"surah":40,"verses":[42]}],"verseLabel":"غافر: 42","question":"لماذا نفى المؤمن علمه بما يدعونه إلى الشرك به؟","answer":"لأن نفي العلم هنا نفي لأي حجة يمكن أن تثبت لذلك الشريك وجودًا أو استحقاقًا للعبادة؛ فالعقيدة لا تقوم بغير برهان، وغياب البرهان يكشف بطلان دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص498، تحت عنوان «سر التعبير بنفي العلم دون غيره»","url":""}]},{"id":"s40-73","number":73,"surah":40,"verses":[42],"references":[{"surah":40,"verses":[42]}],"verseLabel":"غافر: 42","question":"لماذا ختم المؤمن دعوته إلى الله باسمي ﴿الْعَزِيزِ الْغَفَّارِ﴾؟","answer":"ليجمع التخويف والترغيب: العزيز قادر على قهر الشرك وأهله، والغفار يفتح للمقلع عنه باب المغفرة؛ فاجتماعهما أليق بمقام الدعوة والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص500، تحت عنوان «بلاغة التعبير بـ﴿العزيز الغفار﴾ دون غيرهما»","url":""}]},{"id":"s40-74","number":74,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا قال المؤمن ﴿تَدْعُونَنِي إِلَيْهِ﴾ بحرف ﴿إِلَى﴾؟","answer":"لأن دعوتهم غايتها حمله على الوصول إلى عبادة الشريك؛ فصور الشرك كوجهة يريدون سوقه إليها، مقابل دعوته إياهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص504، تحت عنوان «سر التعبير بـ (إلى) دون اللام»","url":""}]},{"id":"s40-173","number":173,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا نُفيت عن الشريك ﴿دَعْوَةٌ﴾ لا مجرد الاستجابة؟","answer":"للمبالغة في نفي كل نفع يرجى منه؛ فليس له دعاء مستجاب في الدنيا ولا في الآخرة، ولا يستحق أصلًا أن يُدعى أو يُقصد بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص505، تحت عنوان «سر التعبير بالدعوة دون الاستجابة»","url":""}]},{"id":"s40-75","number":75,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا عُطف ﴿وَأَنَّ مَرَدَّنَا إِلَى اللَّهِ﴾ بعد نفي دعوة الشركاء؟","answer":"لينتقل من إبطال ما يرجى من الشركاء إلى إثبات المرجع الحقيقي للحساب والجزاء؛ فيظهر الفرق بين عاجز لا يستجيب ورب يملك المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص507، تحت عنوان «بلاغة عطف ﴿وأن مردنا إلى الله﴾»","url":""}]},{"id":"s40-174","number":174,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا قال المؤمن ﴿مَرَدَّنَا﴾ بالجمع ولم يقل «مردي»؟","answer":"ليشمل نفسه وقومه جميعًا في الرجوع إلى الله، فيشعرهم أن التحذير نصح مشترك لا خصومة أو تشفٍ، وأن الحساب ينتظر الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص508، تحت عنوان «سر التعبير بالجمع ﴿مردنا﴾ دون الإفراد (مردي)»","url":""}]},{"id":"s40-76","number":76,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"متى سيتذكر قوم المؤمن قوله في ﴿فَسَتَذْكُرُونَ مَا أَقُولُ لَكُمْ﴾؟","answer":"سيتذكرونه حين يعاينون العذاب الذي حذرهم منه، فلا يعود التذكر نافعًا؛ وصيغة المستقبل تقرب الوعيد وتؤكد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص514–515، تحت عنوان «غرض الإخبار بـ﴿فستذكرون﴾»","url":""}]},{"id":"s40-175","number":175,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"لماذا أتبع المؤمن إنذار قومه بتفويض أمره إلى الله؟","answer":"لأنه أقام الحجة ثم أعرضوا، فانتقل من مجادلتهم إلى الاعتصام بالله وحمايته، جامعًا تهديدهم بالعاقبة وثقته بمن يحفظه من مكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص517، تحت عنوان «بلاغة عطف التفويض على ما قبله»","url":""}]},{"id":"s40-77","number":77,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"لماذا قال المؤمن ﴿أُفَوِّضُ أَمْرِي إِلَى اللَّهِ﴾ ولم يقل «أتوكل»؟","answer":"لأن التفويض يدل على تسليم الأمر كله لله والرضا بما يقضيه بعد وقوع الأسباب، فيبلغ غاية الخضوع والاستسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص518، تحت عنوان «سر التعبير بالتفويض دون التوكل»","url":""}]},{"id":"s40-176","number":176,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"كيف يعلل قوله ﴿إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ﴾ ثقة المؤمن في التفويض؟","answer":"لأن الله يرى حال عبده وحاجته ومكر خصومه، ويعلم ما يصلحه ويحفظه؛ فبصره الشامل هو سند الثقة بتدبيره ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص519–520، تحت عنوان «فائدة تذييل الآية بصفة ﴿بصير﴾ مادة وصيغة»","url":""}]},{"id":"s40-78","number":78,"surah":40,"verses":[45,46],"references":[{"surah":40,"verses":[45,46]}],"verseLabel":"غافر: 45–46","question":"كيف قابل السياق نجاة المؤمن بعقوبة آل فرعون؟","answer":"جاءت وقاية المؤمن ثمرة تفويضه، وجاء إحاطة العذاب بآل فرعون مصداقًا لتحذيره؛ فعاد كل جزاء إلى العمل الذي يناسبه في لف ونشر محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص526، تحت عنوان «بلاغة اللف والنشر»","url":""}]},{"id":"s40-177","number":177,"surah":40,"verses":[45,46],"references":[{"surah":40,"verses":[45,46]}],"verseLabel":"غافر: 45–46","question":"لماذا قيل ﴿وَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ الْعَذَابِ﴾ ولم يقل «نزل»؟","answer":"لأن حاق يصور العذاب محيطًا بهم ملازمًا لا مهرب منه، فيقابل حفظ المؤمن إحاطة العقوبة بأعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص527، تحت عنوان «سر التعبير بـ (حاق) دون نزل»","url":""}]},{"id":"s40-79","number":79,"surah":40,"verses":[46],"references":[{"surah":40,"verses":[46]}],"verseLabel":"غافر: 46","question":"ماذا يفيد ذكر ﴿غُدُوًّا وَعَشِيًّا﴾ في عرض آل فرعون على النار؟","answer":"يفيد تكرر عرضهم على النار واستمرار عذابهم في البرزخ؛ فذكر طرفي اليوم كناية عن الدوام قبل قيام الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص531، تحت عنوان «بلاغة ذكر الغدو والعشي»","url":""}]},{"id":"s40-178","number":178,"surah":40,"verses":[46],"references":[{"surah":40,"verses":[46]}],"verseLabel":"غافر: 46","question":"كيف تدل جملة ﴿النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا﴾ على عذاب قبل القيامة؟","answer":"لأن العرض جعل واقعًا قبل الأمر يوم تقوم الساعة بإدخالهم أشد العذاب؛ فميز السياق عذاب البرزخ عن عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص534، تحت عنوان «دلالة جملة: ﴿النار يعرضون عليها غدوًا وعشيًا﴾»","url":""}]},{"id":"s40-80","number":80,"surah":40,"verses":[47,48],"references":[{"surah":40,"verses":[47,48]}],"verseLabel":"غافر: 47–48","question":"لماذا ذكّر الضعفاء المستكبرين بتبعيتهم قبل طلب تخفيف النار؟","answer":"ليجعلوا طاعتهم لهم وسيلة تلزمهم بالنصرة، وفي ذلك توبيخ للرؤساء الذين أضلوهم ووعدوهم بالحماية في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص541، تحت عنوان «سر تقديم التبعية على طلب التخفيف»","url":""}]},{"id":"s40-179","number":179,"surah":40,"verses":[47,48],"references":[{"surah":40,"verses":[47,48]}],"verseLabel":"غافر: 47–48","question":"ماذا يكشف جواب المستكبرين ﴿إِنَّا كُلٌّ فِيهَا﴾؟","answer":"يكشف سقوط سلطانهم؛ فالجميع محبوس في النار، ولا يملك المستكبرون دفع شيء عن أنفسهم ولا عن أتباعهم، وقد حكم الله بين العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص546، تحت عنوان «غرض الإخبار بـ﴿إنا كل فيها﴾»","url":""}]},{"id":"s40-81","number":81,"surah":40,"verses":[49],"references":[{"surah":40,"verses":[49]}],"verseLabel":"غافر: 49","question":"لماذا طلب أهل النار من الخزنة أن يدعوا ﴿رَبَّكُمْ﴾؟","answer":"لشعورهم بالبعد والحرمان من الإجابة، فطلبوا وساطة من ظنوهم أقرب إلى الله، وفي إضافة الرب إلى الخزنة إظهار لانكسارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص553–554، تحت عنوان «نكتة تخصيص الخزنة بالخطاب»","url":""}]},{"id":"s40-180","number":180,"surah":40,"verses":[49],"references":[{"surah":40,"verses":[49]}],"verseLabel":"غافر: 49","question":"لماذا اقتصر أهل النار على طلب تخفيف يوم واحد؟","answer":"لشدة يأسهم من الخلاص، فغاية أملهم هدنة قصيرة من العذاب، وهذا يكشف هوله واستمراره فوق احتمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص555، تحت عنوان «سر اقتصارهم على طلب تخفيف يوم من العذاب»","url":""}]},{"id":"s40-82","number":82,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"لماذا ذكّر الخزنة أهل النار بمجيء الرسل بالبينات؟","answer":"ليقرروا قيام الحجة عليهم وانتفاء العذر؛ فقد رفضوا أسباب النجاة حين كانت متاحة، ثم اعترفوا بذلك بقولهم بلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص559–563، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s40-181","number":181,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"ما دلالة قول الخزنة لأهل النار ﴿فَادْعُوا﴾؟","answer":"هو أمر تهكم وتيئيس، لا وعد باستجابة؛ أي ادعوا بأنفسكم وقد فات زمن العمل، فلن يغير الدعاء حكمًا استحقوه بعد رد الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص564، تحت عنوان «دلالة الأمر في ﴿فادعوا﴾»","url":""}]},{"id":"s40-83","number":83,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"لماذا ذُيل أمر أهل النار بالدعاء بقوله ﴿وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ﴾؟","answer":"لدفع توهم أن قول الخزنة ﴿فادعوا﴾ يفتح باب الإجابة؛ فالختام يقرر أن دعاءهم ضائع لا يبلغ غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص565، تحت عنوان «بلاغة الاحتراس أو التذييل في الآية»","url":""}]},{"id":"s40-84","number":84,"surah":40,"verses":[51,52],"references":[{"surah":40,"verses":[51,52]}],"verseLabel":"غافر: 51–52","question":"لماذا جاء وعد النصر مؤكدًا في ﴿إِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا﴾؟","answer":"لتثبيت الرسول والمؤمنين بعد عرض مصارع المكذبين، وإزالة ما قد يداخل القلب من بطء النصر؛ فوعد الله حق لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص572–573، تحت عنوان «فائدة تتابع المؤكدات في قوله: ﴿إنا لننصر﴾»","url":""}]},{"id":"s40-182","number":182,"surah":40,"verses":[51,52],"references":[{"surah":40,"verses":[51,52]}],"verseLabel":"غافر: 51–52","question":"كيف يجمع وعد النصر بين الدنيا ويوم يقوم الأشهاد؟","answer":"نصر الدنيا يشمل ظهور الحجة ووجوه التأييد بحسب الحكمة، ثم يكتمل في الآخرة حين يشهد الخلق ظهور الحق وعقوبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص574–576، تحت عنوان «دلالة الظرفية وفائدتها في قوله: ﴿في الحياة الدنيا﴾»","url":""}]},{"id":"s40-85","number":85,"surah":40,"verses":[51],"references":[{"surah":40,"verses":[51]}],"verseLabel":"غافر: 51","question":"ما سر تسمية القيامة ﴿يَوْمَ يَقُومُ الْأَشْهَادُ﴾؟","answer":"يسمى اليوم بما يبرز الشهادة العلنية للرسل والمؤمنين وظهور صدقهم. فتكون نصرتهم تشريفًا ظاهرًا أمام الخلائق، وفي المقابل فضيحة للمكذبين؛ وهذا أنسب بمقام الوعد بالنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص576–577، تحت عنوان «غرض التعبير عن اليوم الآخر بهذا الوصف»","url":""}]},{"id":"s40-86","number":86,"surah":40,"verses":[52],"references":[{"surah":40,"verses":[52]}],"verseLabel":"غافر: 52","question":"لماذا سميت النار ﴿سُوءَ الدَّارِ﴾؟","answer":"لأنها أسوأ مأوى يستقر فيه الإنسان؛ فإضافة السوء إلى الدار تجعل القبح ملازمًا لكل ما فيها ولا تترك موضعًا للطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص583، تحت عنوان «نوع الإضافة في قوله: ﴿سوء الدار﴾»","url":""}]},{"id":"s40-183","number":183,"surah":40,"verses":[52],"references":[{"surah":40,"verses":[52]}],"verseLabel":"غافر: 52","question":"لماذا قُدمت اللعنة على ﴿سُوءُ الدَّارِ﴾؟","answer":"ليرتقي الوعيد من الطرد من رحمة الله إلى الاستقرار في أشد العذاب؛ فجمع الحرمان من الرحمة وسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص583، تحت عنوان «نكتة تقديم ﴿اللعنة﴾ على ﴿سوء الدار﴾»","url":""}]},{"id":"s40-87","number":87,"surah":40,"verses":[53,54],"references":[{"surah":40,"verses":[53,54]}],"verseLabel":"غافر: 53–54","question":"لماذا قُدم إيتاء موسى الهدى على توريث بني إسرائيل الكتاب؟","answer":"لأن إيتاء موسى النبوة والكتاب سابق في الوجود، وهو الأصل الذي نشأ عنه انتقال الهداية إلى بني إسرائيل؛ فقدم السبب على نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص590، تحت عنوان «نكتة تقديم الإيتاء على التوريث»","url":""}]},{"id":"s40-184","number":184,"surah":40,"verses":[53,54],"references":[{"surah":40,"verses":[53,54]}],"verseLabel":"غافر: 53–54","question":"ما الصورة في قوله ﴿وَأَوْرَثْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ﴾؟","answer":"صوّر بقاء الكتاب بينهم وانتقاله من جيل إلى جيل بالميراث الذي يستقر في يد الوارث، وفيه امتنان بتمكينهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص590، تحت عنوان «بلاغة الاستعارة في قوله: ﴿وأورثنا﴾»","url":""}]},{"id":"s40-88","number":88,"surah":40,"verses":[54],"references":[{"surah":40,"verses":[54]}],"verseLabel":"غافر: 54","question":"ماذا يجمع وصف الكتاب بأنه ﴿هُدًى وَذِكْرَى﴾؟","answer":"يجمع الإرشاد إلى الحق والتذكير الذي يحفظه حيًا في النفوس، وتنكير الوصفين يعظم قدر هذا الهدى والتذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص592، تحت عنوان «الموقع النحوي لقوله: ﴿هدى وذكرى﴾ ودلالة تنكيرهما»","url":""}]},{"id":"s40-89","number":89,"surah":40,"verses":[55],"references":[{"surah":40,"verses":[55]}],"verseLabel":"غافر: 55","question":"لماذا قُدِّم الصبر على الاستغفار والتسبيح في توجيه النبي ﷺ؟","answer":"لأن الصبر هو الحاجة الأولى أمام أذى المكذبين وانتظار النصر، ثم جاء الاستغفار والتسبيح زادًا يثبت القلب ويستدعي معونة الله حتى يتحقق وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص601–602، تحت عنوان «نكتة تقديم الأمر بالصبر على الأمر بالاستغفار والتسبيح»","url":""}]},{"id":"s40-90","number":90,"surah":40,"verses":[55],"references":[{"surah":40,"verses":[55]}],"verseLabel":"غافر: 55","question":"لماذا قُدِّم العشي على الإبكار في قوله ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالْإِبْكَارِ﴾؟","answer":"لأن المقام جاء بعد الاستغفار؛ والعشي ختام أعمال النهار فيناسب مراجعة النفس وطلب المغفرة، ثم يأتي الإبكار بدايةً ليوم جديد بالطاعة، فيحيط الذكر بطرفي اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص605–606، تحت عنوان «نكتة تقديم العشي على الإبكار»","url":""}]},{"id":"s40-91","number":91,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"ما الباعث الحقيقي لجدال الذين يجادلون في آيات الله بغير حجة؟","answer":"ليس معهم برهان يطلبون به الحق، وإنما يدفعهم كبر داخلي إلى منازعة الهدى وطلب التعاظم؛ فالقصر يفضح الدافع المستتر وراء جدالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص612، تحت عنوان «بلاغة القصر ونوعه وغرضه»","url":""}]},{"id":"s40-185","number":185,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"لماذا صُوِّر الكبر كأنه مستقر ﴿فِي صُدُورِهِمْ﴾؟","answer":"للدلالة على تمكنه في باطنهم ورسوخه في نفوسهم، حتى صار منشأ أفكارهم وجدالهم؛ فليست المشكلة شبهة عابرة بل داء داخلي يحجبهم عن قبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص613، تحت عنوان «دلالة الظرفية المجازية ﴿في صدورهم﴾»","url":""}]},{"id":"s40-92","number":92,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"لماذا خُتم الأمر بالاستعاذة باسمي الله ﴿السَّمِيعُ الْبَصِيرُ﴾؟","answer":"لأن المستعيذ يلجأ إلى من يسمع أقوال خصومه ويرى أفعالهم ولا يخفى عليه خطرهم؛ فختم الآية بالاسمين يطمئنه إلى كمال الحفظ والنصر والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص617، تحت عنوان «نكتة تذييل الآية الكريمة بهذين الاسمين الجليلين»","url":""}]},{"id":"s40-93","number":93,"surah":40,"verses":[57],"references":[{"surah":40,"verses":[57]}],"verseLabel":"غافر: 57","question":"ما دلالة الاحتجاج بأن خلق السماوات والأرض أكبر من خلق الناس؟","answer":"يلزم المنكرين بما يقرون به: من خلق السماوات والأرض، وهما أعظم من الناس، لا يعجز عن إعادتهم. فتقام الحجة على الأصل الذي يسلمونه، ويكشف إنكار البعث بعده أنهم لم يعملوا نظرهم فيما اعترفوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص627، تحت عنوان «فن الإلجاء في الآية»","url":""}]},{"id":"s40-94","number":94,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"لماذا قُدِّم ﴿الْأَعْمَى﴾ أولًا، ثم قُدِّم المؤمنون على المسيء؟","answer":"بدأ بالأعمى لمناسبة السياق الذي يعرض حال الكافر، ثم قدم المؤمنين في المقابلة الثانية تشريفًا واهتمامًا بهم؛ فتغير الترتيب تبعًا لمقصد كل موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص632، تحت عنوان «نكتة تقديم كل من الأعمى والذين آمنوا على مقابلهما»","url":""}]},{"id":"s40-196","number":196,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"لماذا جُدِّد النفي في ﴿وَلَا الْمُسِيءُ﴾ بعد قوله ﴿وَمَا يَسْتَوِي﴾؟","answer":"لتوكيد انتفاء المساواة وتنبيه السامع إلى المقابلة الثانية استقلالًا؛ فلا يتوهم أن نفي المساواة اقتصر على الأعمى والبصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص635، تحت عنوان «نكتة النفي بـ (لا) بعد سبق النفي بـ﴿ما﴾»","url":""}]},{"id":"s40-95","number":95,"surah":40,"verses":[57,58,59],"references":[{"surah":40,"verses":[57,58,59]}],"verseLabel":"غافر: 57–59","question":"ما سر تكرار ﴿أَكْثَرَ النَّاسِ﴾ مع اختلاف نفي العلم في الأولى ونفي الإيمان في الثانية؟","answer":"ورد نفي العلم بعد الاحتجاج بعظم خلق السماوات والأرض؛ فالمقام يقتضي معرفة قدرة الخالق على الإعادة. وورد نفي الإيمان بعد التصريح بمجيء الساعة؛ فالمطلوب هناك التصديق بما دل عليه البرهان. وبذلك يناسب كل ختام القضية التي قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص680–681، تحت عنوان «بيان المتشابه في استعمال الفعل المضارع المنفي»","url":""}]},{"id":"s40-96","number":96,"surah":40,"verses":[59],"references":[{"surah":20,"verses":[15]},{"surah":40,"verses":[59]}],"verseLabel":"غافر: 59؛ طه: 15","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّ السَّاعَةَ لَآتِيَةٌ لَا رَيْبَ فِيهَا﴾؟","answer":"لأن الخطاب يواجه من ينكرون البعث، فاحتاج الخبر إلى توكيد متتابع بـ﴿إن﴾ واللام ونفي الريب، حتى يواجه جحودهم ويثبت حتمية الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص642، تحت عنوان «فائدة تتابع المؤكدات في صدر الآية»","url":""}]},{"id":"s40-97","number":97,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"لماذا قيل ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ بدل «إن تدعوني أستجب لكم»؟","answer":"لأن صيغة الطلب تدعو العباد مباشرة إلى ما ينفعهم وتعدهم بالاستجابة في عبارة موجزة مشوقة، بدل تعليق الوعد على شرط بارد؛ فهي أبلغ في الحث وإظهار اللطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص658، تحت عنوان «دلالة استعمال أسلوب الطلب دون أسلوب الشرط»","url":""}]},{"id":"s40-98","number":98,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"كيف جمعت آية ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ بين الترغيب والوعيد من غير تكرار؟","answer":"ذكر الدعاء والاستجابة أولًا، ثم العبادة ودخول جهنم، فدل كل طرف على ما حذف من الآخر: للدعاء والعبادة قبول وثواب، ولتركهما واستكبار صاحبه وعيد؛ فجمع الإيجاز الترغيب والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص662، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s40-99","number":99,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"لماذا اختير وصف المستكبرين عن العبادة بأنهم سيدخلون جهنم ﴿دَاخِرِينَ﴾؟","answer":"لأن الدخور ذل وصغار؛ فينقلب استكبارهم في الدنيا هوانًا ظاهرًا في الآخرة، ويكشف الجزاء بطلان الكبر الذي منعهم من الخضوع لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص662، تحت عنوان «دلالة التعبير بـ﴿داخرين﴾ مادة وصيغة»","url":""}]},{"id":"s40-100","number":100,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"لماذا قُدِّم الليل على النهار في تعداد نعم الله؟","answer":"لأن الظلام هو الحالة الأصلية العامة، والنور حالة تطرأ عليه، ولأن السكون في الليل يهيئ الإنسان لما يعقبه من حركة النهار؛ فناسب أن يبدأ بما يمهد لما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص674، تحت عنوان «نكتة تقديم ذكر الليل على النهار»","url":""}]},{"id":"s40-101","number":101,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"ما دلالة وصف النهار بأنه ﴿مُبْصِرًا﴾؟","answer":"أسند الإبصار إلى النهار مع أن المبصرين هم الناس فيه، فهو مجاز عقلي لعلاقة الزمان. ويبرز هذا الإسناد شدة صلاحية النهار للإبصار والعمل، حتى كأنه هو الذي يبصر، فيعظم الامتنان بهذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص672، تحت عنوان «بلاغة المجاز في إسناد الإبصار إلى النهار»","url":""}]},{"id":"s40-102","number":102,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"لماذا عُمِّم فضل الله على الناس بعد ذكر نعمتي الليل والنهار؟","answer":"ليجعل الليل والنهار مثالين لفيض أوسع من النعم التي تقوم عليها حياة الناس، فينتقل الذهن من نعمتين مشهودتين إلى استحضار عموم فضل الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص676، تحت عنوان «بلاغة التذييل في جملة ﴿إن الله لذو فضل على الناس﴾»","url":""}]},{"id":"s40-103","number":103,"surah":40,"verses":[62,63],"references":[{"surah":40,"verses":[62,63]}],"verseLabel":"غافر: 62–63","question":"لماذا قيل بعد إنكار انصرافهم عن التوحيد ﴿كَذَلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بِآيَاتِ اللَّهِ يَجْحَدُونَ﴾؟","answer":"لبيان أن انصرافهم ليس ناشئًا عن خفاء الدليل، بل هو شأن كل من يجحد آيات الله؛ فالتشبيه يلحقهم بسلسلة المكذبين ويكشف أن الجحود هو الذي صرفهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص692، تحت عنوان «بلاغة التشبيه بالكاف في ﴿كذلك﴾»","url":""}]},{"id":"s40-104","number":104,"surah":40,"verses":[62],"references":[{"surah":40,"verses":[62]}],"verseLabel":"غافر: 62","question":"كيف تتدرج الأخبار من الربوبية والخلق إلى توحيد الله؟","answer":"تبدأ بأنه رب المخاطبين، ثم تعمم أنه خالق كل شيء، فتفضي المقدمتان إلى النتيجة: من انفرد بالتدبير والخلق انفرد باستحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص685، تحت عنوان «بلاغة الترقي في سرد الأخبار»","url":""}]},{"id":"s40-197","number":197,"surah":40,"verses":[62],"references":[{"surah":40,"verses":[62]}],"verseLabel":"غافر: 62","question":"لماذا فُصلت كلمة التوحيد ﴿لَا إِلَهَ إِلَّا هُوَ﴾ عما قبلها؟","answer":"لأنها نتيجة مستقلة مستأنفة لما سبق من إثبات الربوبية والخلق؛ فجاء الفصل ليبرز الحكم الحاسم الذي تثمره تلك الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص688، تحت عنوان «نكتة فصل كلمة التوحيد»","url":""}]},{"id":"s40-105","number":105,"surah":40,"verses":[61,64],"references":[{"surah":40,"verses":[61,64]}],"verseLabel":"غافر: 61، 64","question":"لماذا استقلت آية ﴿اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا﴾ عن سابقتها؟","answer":"لأنها تستأنف دليلًا وامتنانًا جديدًا بتهيئة المكان بعد تهيئة الزمان، فتأخذ نعمتا الأرض والسماء عناية مستقلة مع اتصال الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص698، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s40-106","number":106,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"ما أثر المقابلة بين الأرض والسماء في تعداد النعم؟","answer":"تجمع ما تحت الإنسان وما فوقه في صورة مكان كامل مهيأ لحياته؛ أرض تحمل وتستقر، وسماء تظل وتحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص700، تحت عنوان «بلاغة الطباق بين لفظتي ﴿الأرض﴾ و(السماء)»","url":""}]},{"id":"s40-198","number":198,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"ما الصورة في وصف السماء بأنها ﴿بِنَاءً﴾؟","answer":"تشبهها بسقف محكم مرفوع فوق الناس، فيوحي اللفظ بالنظام والحماية وإحكام الصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص702، تحت عنوان «بلاغة التشبيه في حال السماء»","url":""}]},{"id":"s40-107","number":107,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"لماذا ذُكر إحسان صورة الإنسان بعد جعل الأرض قرارًا والسماء بناء؟","answer":"لينتقل الامتنان من تهيئة المكان إلى تهيئة ساكنه؛ فكما أحسن الله بيئة الإنسان أحسن خلقه وهيئته، فاجتمع جمال المسكن وإتقان الساكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص703–704، تحت عنوان «نكتة عطف تصوير الخلقة على جعل السماء والأرض»","url":""}]},{"id":"s40-186","number":186,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"لماذا ذُكر رزق الإنسان من الطيبات بعد إحسان صورته؟","answer":"ليكتمل الامتنان: خلقه الله في أحسن هيئة ثم أمده بما يحفظ حياته ويلائم فطرته من الرزق الطيب، فجمع له حسن الخلقة وكمال الإمداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص705، تحت عنوان «فائدة عطف قوله: ﴿ورزقكم من الطيبات﴾ على ما تقدمها»","url":""}]},{"id":"s40-108","number":108,"surah":40,"verses":[65],"references":[{"surah":40,"verses":[65]}],"verseLabel":"غافر: 65","question":"لماذا جاء الأمر ﴿فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ﴾ بعد قوله ﴿هُوَ الْحَيُّ لَا إِلَهَ إِلَّا هُوَ﴾؟","answer":"لأن من له الحياة الكاملة الدائمة وينفرد بالألوهية هو وحده المستحق للدعاء والعبادة؛ فالأمر نتيجة لما قبله، والإخلاص يمنع إشراك غيره فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص714، تحت عنوان «معنى الفاء في قوله: ﴿فادعوه﴾»","url":""}]},{"id":"s40-109","number":109,"surah":40,"verses":[66],"references":[{"surah":40,"verses":[66]}],"verseLabel":"غافر: 66","question":"لماذا جمع الرسول ﷺ بين قوله ﴿نُهِيتُ﴾ وقوله ﴿وَأُمِرْتُ﴾؟","answer":"ليبين أن الدين لا يكتمل بمجرد ترك الشرك، بل لا بد معه من الانقياد لرب العالمين؛ فاجتمع في الإعلان براءة من الباطل واستسلام للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص730، تحت عنوان «بلاغة الطباق بين ﴿نهيت﴾ و(أمرت)»","url":""}]},{"id":"s40-110","number":110,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا اختير لفظ ﴿تراب﴾ عند بدء الحديث عن خلق الإنسان؟","answer":"لأن التراب يذكّر الإنسان بضعف أصله وهوان مادته؛ فهو هشّ تذروه الرياح، فيوقظه ذلك إلى معرفة قدره والتواضع والانقياد لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص738، تحت عنوان «نكتة اختيار مفردة ﴿تراب﴾»","url":""}]},{"id":"s40-187","number":187,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما دلالة تكرار ﴿ثم﴾ بين أطوار خلق الإنسان؟","answer":"تصوّر ﴿ثم﴾ كلَّ طور مرحلةً مستقلة يعقبها غيرها بعد زمن، فتستحضر تدرّج الخلق من الأصل الأول إلى اكتمال الإنسان وشيخوخته. وفي تكرارها تنبيه إلى عناية الله بالإنسان عبر مراحله ودعوة إلى شكر هذه النعم والخضوع لخالقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص738–739، تحت عنوان «براعة استعمال حرف التراخي وتكراره»","url":""}]},{"id":"s40-188","number":188,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا خُتم عرض أطوار الإنسان بقوله ﴿ولعلكم تعقلون﴾؟","answer":"لأن تعاقب تلك الأطوار دليل ظاهر على قدرة الله ووحدانيته وعلى إمكان البعث؛ فجاء الختام ليدعو الإنسان إلى إعمال العقل في خلقه، حتى يقوده النظر السليم إلى توحيد الله وعبادته لا إلى الأوهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص751–752، تحت عنوان «دلالة التعبير بمفردة العقل»","url":""}]},{"id":"s40-111","number":111,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما سر إفراد ﴿طِفْلًا﴾ مع جمع المخاطبين؟","answer":"يجوز حمل الإفراد على إرادة كل واحد من المخاطبين: يخرج كل واحد طفلًا. ويجوز أن يكون ﴿طفلًا﴾ اسم جنس يشمل الجمع؛ فيؤدي اللفظ المفرد معنى المرحلة المشتركة التي يمر بها الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص741، تحت عنوان «نكتة إفراد لفظ ﴿طفلًا﴾»","url":""}]},{"id":"s40-112","number":112,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا جاء قوله ﴿ومنكم من يتوفى من قبل﴾ وسط ذكر أطوار العمر؟","answer":"جاء احتراسًا من توهّم أن كل إنسان يبلغ الشيخوخة أو الأجل المسمّى؛ فبعض الناس يُتوفّى قبل تلك المراحل، وبذلك يظل تمام العمر خاضعًا للأجل الذي قدّره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص748، تحت عنوان «بلاغة الاحتراس»","url":""}]},{"id":"s40-113","number":113,"surah":40,"verses":[68],"references":[{"surah":36,"verses":[82]},{"surah":40,"verses":[68]}],"verseLabel":"غافر: 68؛ يس: 82","question":"ماذا تقصر ﴿إِنَّمَا﴾ في قوله ﴿فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"تقصر طريق تحقق المقضي على نفاذ أمر الله بلا معالجة ولا عجز ولا تأخر؛ فمتى تعلقت إرادته بشيء وجد على الفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص761، تحت عنوان «معنى (إنما) في جملة القصر»","url":""}]},{"id":"s40-114","number":114,"surah":40,"verses":[68],"references":[{"surah":40,"verses":[68]}],"verseLabel":"غافر: 68","question":"لماذا فُصل قوله ﴿هو الذي يحيي ويميت﴾ عما قبله؟","answer":"لأنه استئناف يقرر حقيقة عامة بعد تفصيل خلق الإنسان؛ فالذي أنشأ أطواره هو المتصرف في حياته وأجله، فينتقل السياق من عرض المراحل إلى أصل القدرة على الإحياء والإماتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص756، تحت عنوان «علة فصل الجملة عما قبلها»","url":""}]},{"id":"s40-115","number":115,"surah":40,"verses":[69,70],"references":[{"surah":40,"verses":[69,70]}],"verseLabel":"غافر: 69–70","question":"ما غرض قوله ﴿ألم تر إلى الذين يجادلون في آيات الله﴾؟","answer":"الاستفهام للتعجيب من حالهم وإنكار انصرافهم عن آيات الله الواضحة ومحاولتهم طمسها؛ وفيه تقرير لشناعة جدالهم وتحذير ووعيد لمن يجادل في الحق بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص769، تحت عنوان «معنى الهمزة في جملة ﴿ألم تر﴾، وغرضها»","url":""}]},{"id":"s40-189","number":189,"surah":40,"verses":[69,70],"references":[{"surah":40,"verses":[69,70]}],"verseLabel":"غافر: 69–70","question":"لماذا انتقل السياق من ذكر جدالهم في آيات الله إلى تكذيبهم بالكتاب؟","answer":"لأن التكذيب هو منشأ ذلك الجدال؛ فذكره يكشف أنهم لم يطلبوا الحق، بل ردّوا القرآن وما جاءت به الرسل مع أن الكتب المنزلة دلائل تقود إلى الإيمان، فكان جحودهم بها أصل انصرافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص775–776، تحت عنوان «براعة الانتقال من ذكر الجدال إلى ذكر التكذيب»","url":""}]},{"id":"s40-116","number":116,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"ما الذي يصوره قوله ﴿يُسْحَبُونَ فِي الْحَمِيمِ﴾ من حال المكذبين؟","answer":"يصور جرَّهم بعنف في حال من الهوان؛ فالسحب يجمع الإيلام بالإهانة، ويعاملهم معاملة من سقطت كرامته. وجاء الفعل مضارعًا ليستحضر المشهد ويصور تجدد السحب أمام الناظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص784، تحت عنوان «بلاغة استعمال مفردة ﴿يسحبون﴾ مادة وصيغة»","url":""}]},{"id":"s40-190","number":190,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"لماذا جاء ﴿ثُمَّ فِي النَّارِ يُسْجَرُونَ﴾ بعد سحبهم في الحميم؟","answer":"تفيد ﴿ثم﴾ انتقالهم بعد الحميم إلى مرحلة أخرى من العذاب، كما تفيد الارتقاء إلى ما هو أشد؛ فالإحراق بالنار فوق ما سبق من السحب والتعذيب بالماء الحار. وفي هذا التتابع تصوير لطول مراحل العذاب وتنوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص785، تحت عنوان «نوع التراخي ودلالته في قوله: ﴿ثم في النار يسجرون﴾»","url":""}]},{"id":"s40-191","number":191,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"ما الذي يصوره لفظ ﴿يُسْجَرُونَ﴾ في عذاب المكذبين؟","answer":"السجر يدل على الإيقاد والاشتعال والتأجج؛ فيصور طرحهم في النار وإحراقهم بها، حتى تصير أجسامهم وقودًا يزيدها اشتعالًا. فاللفظ يجمع بين كونهم محروقين وكونهم مادة لإيقاد النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص787، تحت عنوان «دلالة استعمال مفردة السجر»","url":""}]},{"id":"s40-117","number":117,"surah":40,"verses":[71],"references":[{"surah":40,"verses":[71]}],"verseLabel":"غافر: 71","question":"ما سر تخصيص الأعناق بذكر الأغلال؟","answer":"التصريح بالأعناق، مع أن الغل يكون فيها عادة، يزيد تصوير الإذلال؛ فقد كانت موضع رفع الرؤوس والإعراض عن الحق، فتصير موضع القيد والجر. وبذلك تقابل هيئة العقوبة هيئة التكبر التي كانوا عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص782، تحت عنوان «نكتة التصريح بالقيد»","url":""}]},{"id":"s40-118","number":118,"surah":40,"verses":[73,74],"references":[{"surah":40,"verses":[73,74]}],"verseLabel":"غافر: 73–74","question":"ماذا يضيف قيد ﴿مِنْ دُونِ اللَّهِ﴾ إلى سؤال المشركين عن آلهتهم؟","answer":"يحدد أن المسؤول عنهم معبوداتهم التي اتخذوها بديلًا من الله، فيسبق إقرارهم بضياعها تقريع صريح على أصل شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص797، تحت عنوان «نكتة التقييد بالجار والمجرور ﴿من دون﴾ ودلالتهما»","url":""}]},{"id":"s40-119","number":119,"surah":40,"verses":[73,74],"references":[{"surah":40,"verses":[73,74]}],"verseLabel":"غافر: 73–74","question":"لماذا قالوا بعد ﴿ضَلُّوا عَنَّا﴾: ﴿بَلْ لَمْ نَكُنْ نَدْعُو مِنْ قَبْلُ شَيْئًا﴾؟","answer":"يحتمل كلامهم أنهم ارتدوا إلى الكذب فأنكروا شركهم بعد أن اعترفوا بغياب آلهتهم، فلم تمنعهم أهوال الآخرة من المكابرة. ويحتمل أنهم انتقلوا إلى الاعتراف بأن عبادتهم ضاعت، وأن ما عبدوه لم يكن شيئًا يُعتد به ولا يملك نفعًا؛ وهو ندم جاء بعد فوات زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص799–800، تحت عنوان «نوع ﴿بل﴾ ودلالتها»","url":""}]},{"id":"s40-120","number":120,"surah":40,"verses":[75],"references":[{"surah":40,"verses":[75]}],"verseLabel":"غافر: 75","question":"لماذا قُيِّد الفرح في قوله ﴿تَفْرَحُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ﴾؟","answer":"لأن الفرح ليس مذمومًا كله؛ فمنه فرح مشروع بفضل الله ورحمته. فجاء قيد ﴿بغير الحق﴾ ليحدد أن سبب العقوبة هو الفرح بالباطل الذي يصرف عن الحق، ويدفع توهّم أن الفرح محرم على المؤمنين بإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص809، تحت عنوان «نكتة تقييد الأفعال»","url":""}]},{"id":"s40-121","number":121,"surah":40,"verses":[76],"references":[{"surah":40,"verses":[76]}],"verseLabel":"غافر: 76","question":"لماذا قيل ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾ ولم يقل «فبئس مدخلهم»؟","answer":"لأن المثوى هو محل الإقامة والاستقرار، فهو أدل على دوام العذاب من مجرد المدخل الذي لا يستلزم البقاء. ولذلك ناسب ذكر الخلود، وكان أشد في التهديد؛ فالنار ليست بابًا يعبرونه بل مقامًا يستقرون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص815–816، تحت عنوان «بلاغة استعمال مفردة ﴿مثوى﴾ دون (مدخل)»","url":""}]},{"id":"s40-122","number":122,"surah":40,"verses":[77],"references":[{"surah":40,"verses":[77]}],"verseLabel":"غافر: 77","question":"هل يقتصر ﴿وَعْدَ اللَّهِ﴾ هنا على نصر المؤمنين؟","answer":"لا؛ فاللفظ يشمل ما وعد الله به المؤمنين من النصر والتمكين، وما أوعد به الكافرين من الإذلال والجزاء، فيحمل للنبي ﷺ التثبيت والتسلية من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص14، تحت عنوان «نكتة استعمال مفردة (الوعد)»","url":""}]},{"id":"s40-123","number":123,"surah":40,"verses":[77],"references":[{"surah":40,"verses":[77]}],"verseLabel":"غافر: 77","question":"هل يتوقف تحقق وعيد المكذبين على أن يراه النبي ﷺ في حياته؟","answer":"لا؛ فصيغة ﴿فَإِمَّا نُرِيَنَّكَ﴾ تفتح احتمال أن يرى النبي ﷺ بعض ما وُعدوا به، واحتمال أن يتوفاه الله قبل ذلك، لكن الانتقام منهم واقع في الحالين؛ فلا تتوقف صدقية الوعيد على مشاهدته في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص16، تحت عنوان «بلاغة التعبير بالجملة الشرطية باستعمال (إما)»","url":""}]},{"id":"s40-124","number":124,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"لماذا قُدِّم الرسل الذين قصَّهم الله على الذين لم يقصصهم؟","answer":"لأن المثبت يُقدَّم على المنفي، ولأن تعريف النبي ﷺ ببعض الرسل كان تسليةً له وتثبيتًا، أما عدم تعريفه بالباقين فله حكمة ربانية؛ إذ لا كمال في كشف ما لا حاجة إلى معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص33، تحت عنوان «نكتة تقديم ﴿قصصنا﴾ على ﴿لم نقصص﴾»","url":""}]},{"id":"s40-125","number":125,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"لماذا انتقل التعبير من ﴿بِإِذْنِ اللَّهِ﴾ إلى ﴿فَإِذَا جَاءَ أَمْرُ اللَّهِ﴾؟","answer":"لأن ما سيُظهره الله بإذنه ليس استجابةً لاقتراح المعاندين، بل آيات عقاب يقضي بها على تكذيبهم؛ فسُمّي ﴿أَمْرُ اللَّهِ﴾ تعريضًا بحتمية الجزاء وتحذيرًا من عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص38–39، تحت عنوان «نكتة العدول عن مجيء الإذن إلى الأمر»","url":""}]},{"id":"s40-192","number":192,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"ما الذي يبرزه قوله ﴿قُضِيَ بِالْحَقِّ﴾ عند مجيء أمر الله؟","answer":"يبرز أن الفصل سيُظهر صدق الرسول وبطلان مكذبيه، وأن الجزاء قائم على العدل؛ وفي تخصيص الحق تعريض بالمبطلين وإنذار بأن خصومتهم ستنتهي بحكم يخسرون عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص39–40، تحت عنوان «بلاغة ذكر ﴿قضي بالحق﴾ دون غيره»","url":""}]},{"id":"s40-126","number":126,"surah":40,"verses":[79,80],"references":[{"surah":40,"verses":[79,80]}],"verseLabel":"غافر: 79–80","question":"ما سر تقديم الركوب على الأكل في تعداد منافع الأنعام؟","answer":"قدم الركوب لأنه من أهم منافع الأنعام في قطع المسافات الواسعة، وهو المقصود الأبرز في سياق ذكر الحمل وبلوغ الحاجات. ثم جاء الأكل ضمن وجوه الانتفاع المتنوعة، فناسب الترتيب الغرض الذي يمهد له السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص51، تحت عنوان «نكتة تقديم الركوب على الأكل»","url":""}]},{"id":"s40-127","number":127,"surah":40,"verses":[80],"references":[{"surah":40,"verses":[80]}],"verseLabel":"غافر: 80","question":"هل تدل ﴿حَاجَةً﴾ على غرض واحد من الأنعام؟","answer":"لا؛ فتَنكيرها يشمل أي حاجة دنيوية تتحقق بها مصلحة الناس، فيتسع الامتنان لما يبلغونه على الأنعام من منافع ومقاصد، ولا ينحصر في غرض بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص56، تحت عنوان «نكتة تنكير لفظ ﴿حاجة﴾ في السياق»","url":""}]},{"id":"s40-193","number":193,"surah":40,"verses":[80],"references":[{"surah":40,"verses":[80]}],"verseLabel":"غافر: 80","question":"لماذا عُبِّر عن الحاجات المستقرة في النفس بأنها ﴿فِي صُدُورِكُمْ﴾؟","answer":"لأن الصدور تحيط بالقلوب، والقلوب موضع المقاصد؛ فعُبِّر بالمحل الأوسع عن مستقر الرغبات الخفية، مبالغةً في إبراز أهمية ما يعقد الإنسان قلبه على بلوغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص56، تحت عنوان «بلاغة الكناية عن القلوب بالصدور»","url":""}]},{"id":"s40-128","number":128,"surah":40,"verses":[79,80],"references":[{"surah":40,"verses":[79,80]}],"verseLabel":"غافر: 79–80","question":"ما دلالة الجمع بين حمل الناس على الأنعام في البر وحملهم على الفلك في البحر؟","answer":"يجمع الامتنان بين وسيلتي الحمل في البر والبحر، وقُدِّم الحمل على الأنعام لاتصال الكلام بمنافعها، ثم ذُكرت الفلك ليعم التيسير الطريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص57، تحت عنوان «نكتة تقديم الحمل على الأنعام على الحمل على الفلك»","url":""}]},{"id":"s40-129","number":129,"surah":40,"verses":[81],"references":[{"surah":40,"verses":[81]}],"verseLabel":"غافر: 81","question":"لماذا جاء قوله تعالى: ﴿وَيُرِيكُمْ آيَاتِهِ﴾ بعد تفصيل منافع الأنعام؟","answer":"ليعمم بعد ذكر النعم المفصلة: فآيات الله لا تنحصر في الأنعام، بل تشمل كل ما يدل على وحدانيته وقدرته، وفي ذلك تجديد للتذكير بسائر النعم والدلائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص60، تحت عنوان «نكتة ما يفيد التذييل في قوله: ﴿ويريكم آياته﴾»","url":""}]},{"id":"s40-194","number":194,"surah":40,"verses":[81],"references":[{"surah":40,"verses":[81]}],"verseLabel":"غافر: 81","question":"ماذا يفيد الاستفهام في قوله تعالى: ﴿فَأَيَّ آيَاتِ اللَّهِ تُنْكِرُونَ﴾؟","answer":"هو استفهام إنكاري توبيخي؛ لأن آيات الله ظاهرة لا يكاد ينكرها ذو عقل، فجاء ليكشف أن جحودها بعد مشاهدتها سفه ومكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص61–62، تحت عنوان «بلاغة الاستفهام في قوله: ﴿فأي آيات الله﴾»","url":""}]},{"id":"s40-130","number":130,"surah":40,"verses":[82],"references":[{"surah":40,"verses":[82]}],"verseLabel":"غافر: 82","question":"ماذا يضيف قوله تعالى: ﴿وَآثَارًا فِي الْأَرْضِ﴾ إلى مشهد الأمم السابقة؟","answer":"يجعل آثار قوتهم وعمرانهم قائمة في الأرض المعهودة للمخاطبين، فيرون بأعينهم بقايا حضارات من سبقهم؛ فتغدو الآثار شاهدًا حاضرًا على ما انتهوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص74، تحت عنوان «فائدة الظرفية ﴿في الأرض﴾»","url":""}]},{"id":"s40-131","number":131,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"ماذا يصوّر قوله تعالى: ﴿فَرِحُوا بِمَا عِنْدَهُمْ مِنَ الْعِلْمِ﴾ من حال المكذبين؟","answer":"يصوّر شدة اعتدادهم بما ورثوه من معتقدات باطلة حتى تمسكوا بها، وجادلوا الرسل، وأعرضوا عن البينات الواضحة؛ فالفرح كناية عن رضا أغلق عليهم باب قبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص79–80، تحت عنوان «بلاغة الكناية في التعبير بالفرح»","url":""}]},{"id":"s40-195","number":195,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"لماذا سُمِّي ما عند المكذبين ﴿عِلْمًا﴾ مع أنه ضلال؟","answer":"سُمِّي علمًا على سبيل التهكم بهم؛ لأنهم زعموا الجهل علمًا وفرحوا به، فجاء اللفظ الذي يوحي بالتعظيم في مقام التحقير ليكشف غرورهم وسوء تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص80، تحت عنوان «بلاغة فن التهكم في السياق المحكم»","url":""}]},{"id":"s40-132","number":132,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"ما سر مقابلة فرحهم بعلمهم بحيق ما كانوا به يستهزئون؟","answer":"كان فرحهم بما عندهم باعثًا على الاستهزاء بالوعيد، فجاء ﴿حاق بهم﴾ ليصور إحاطة ما استهانوا به من العذاب. وبذلك ينقلب الأمن المتوهم والاعتداد بالنفس إلى مصير لا يجدون منه منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص83، تحت عنوان «بلاغة الاستعارة في ﴿وحاق بهم﴾»","url":""}]},{"id":"s40-133","number":133,"surah":40,"verses":[84,85],"references":[{"surah":40,"verses":[84,85]}],"verseLabel":"غافر: 84–85","question":"لماذا جمعوا عند رؤية العذاب بين ﴿آمَنَّا بِاللَّهِ وَحْدَهُ﴾ و﴿وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ﴾؟","answer":"يكشف الطباق بين الإيمان والكفر انقلاب موقفهم كاملًا عند معاينة العذاب: أثبتوا التوحيد ونفوا ما كانوا عليه من الشرك. لكنه يفضح أيضًا تأخر هذا الرجوع؛ فقد جاء إيمان اضطرار بعد استقرار الكفر، فلم يمحُه حين نزل البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص94، تحت عنوان «بلاغة الطباق في الجمع بين الإيمان والكفر»","url":""}]},{"id":"s40-134","number":134,"surah":40,"verses":[84],"references":[{"surah":40,"verses":[84]}],"verseLabel":"غافر: 84","question":"لماذا قيل ﴿آمَنَّا بِاللَّهِ وَحْدَهُ﴾ مع أن الإيمان بالله يُفهم منه التوحيد؟","answer":"جاءت كلمة ﴿وحده﴾ لتؤكد إيمانهم الجازم بالله وإفراده بالعبادة، وتنفي صراحة ما كانوا عليه من الشرك؛ فلا يبقى في اعترافهم احتمال إقرار بالله مع إثبات شركاء له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص94، تحت عنوان «نكتة التعبير بلفظ ﴿وحده﴾»","url":""}]},{"id":"s40-135","number":135,"surah":40,"verses":[85],"references":[{"surah":40,"verses":[85]}],"verseLabel":"غافر: 85","question":"لماذا جُعل عدم نفع الإيمان بعد نزول العذاب سنةً لله في عباده؟","answer":"ليبيّن أن الأمر ليس حالة عارضة تخص هؤلاء، بل حكم ثابت سبق في الأمم: الإيمان النافع هو إيمان الاختيار قبل ظهور البأس، أما ما يأتي بعد انكشاف العذاب فإيمان اضطرار لا يُقبل؛ وقد ذكر المصدر قوم يونس استثناءً من نزول العذاب بعد ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص98–99، تحت عنوان «نكتة فصل قوله: ﴿سُنَّتَ اللَّهِ﴾»","url":""}]},{"id":"s40-136","number":136,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"لماذا عُبّر عن زمن انكشاف الخسارة بكلمة ﴿هُنَالِكَ﴾؟","answer":"استعير اسم المكان للزمان ليجعل لحظة ظهور الخسران كأنها موضع شاخص يقف عنده الناس؛ فتغدو العاقبة حاضرة مرئية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص42، تحت عنوان «بلاغة استعارة اسم الإشارة المكاني للظرف الزماني»","url":""}]},{"id":"s40-199","number":199,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"لماذا قُدِّم القضاء بالحق على خسارة المبطلين؟","answer":"لأن الخسارة نتيجة الحكم الفاصل، فرتبها النظم بعد القضاء ترتيب السبب والمسبب، وأظهر أن الهلاك ثمرة بطلانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص43، تحت عنوان «نكتة تقديم القضاء على الخسارة»","url":""}]},{"id":"s41-1","number":1,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا سُمّيت سورة فصلت بهذا الاسم؟","answer":"لأن السورة أبرزت وصف القرآن بأنه كتاب فُصّلت آياته: بُيّنت معانيه وأحكامه وطرائق هدايته، فصار هذا الوصف البارز اسمًا دالًا على مركزية البيان القرآني فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص108–109، تحت عنوان «أسماء السورة ومناسبة تسميتها»","url":""}]}]);
